INSERT INTO "tblReport" ("CENTRALReportID", "CRGReportID", "ReportNumber", "Title", "Authors", "Journal", "Year", "Abstract", "Dateentered", "DateEdited", "TypeofReportID", "PublicationTypeID", "StudyDesign", "DOI", "TrialRegistrationID", "OriginalTitle", "Language", "Publisher") VALUES

(NULL, 2000001, 1, 'Nationwide telemetry-based cardiac arrhythmia screening in older adults: findings from a large pragmatic trial', 'Zofia Wachira//Esteban Dahl//Kavya Ionescu', 'Journal of Infectious Disease Interventions', 2016, 'Background: Systematic identification of previously undiscovered atrial fibrillation in at-risk populations remains challenging despite its implications for stroke prevention. Methods: We enrolled 50,549 adults aged 65 and older with at least one clinical marker for thromboembolism risk through a fully automated digital platform. Participants were randomly assigned to receive remote ECG telemetry surveillance or standard clinical care. The telemetry group underwent 7 days of continuous electrocardiographic monitoring using a wearable patch system mailed directly to their homes. Results: Among participants allocated to telemetry, 1.9% were found to have previously unidentified atrial fibrillation. Of these newly detected cases, approximately 96% of patients initiated appropriate anticoagulation management following recommendations to their primary care providers. No serious adverse events related to the screening process were reported. Conclusion: Large-scale, remotely administered ECG screening is operationally feasible and identifies clinically relevant arrhythmia in a significant proportion of older individuals at baseline thrombotic risk, with high uptake of guideline-directed medical therapy.', '2016-07-17 09:00:00', '2026-05-19 00:00:00', 2, '1', 'Pragmatic 1:1 randomized controlled trial with remote monitoring', '10.5555/medidex.synthetic.0001', NULL, NULL, 'English', 'Journal of Infectious Disease Interventions Press'),
(NULL, 2000002, 2, 'Antimicrobial oral rinse formulation demonstrates suppression of cariogenic bacterial colonies in randomized trial', 'Franz Fernandes//Anika Kowalski//Jonas Yilmaz', 'International Journal of Rehabilitation Trials', 2018, 'Objective: Herbal extract-based oral preparations have traditional antimicrobial properties, yet clinical evidence remains sparse. This parallel-group double-blind investigation compared a herbal rinse formulation against placebo for its capacity to inhibit oral pathogens associated with tooth decay. Methods: Sixty participants were randomly allocated to daily oral rinsing with either a botanical extract or isotonic saline for one week. Microbiological sampling and caries-activity testing occurred before and after the intervention period. Results: The botanical extract group exhibited significantly reduced bacterial counts compared with the saline-treated control group (p<0.05). Demineralization markers were equivalent between groups, indicating no adverse effects on enamel integrity. The active rinse showed broad antibacterial efficacy against the target pathogens without systemic absorption. Conclusion: The herbal formulation demonstrates promising antimicrobial activity in the oral cavity with a favorable safety profile, supporting its investigation as an adjunctive prevention strategy.', '2018-09-13 09:00:00', '2026-08-15 00:00:00', 2, '1', 'Double-blind parallel randomized controlled trial', '10.5555/medidex.synthetic.0002', NULL, NULL, 'English', 'International Journal of Rehabilitation Trials Press'),
(NULL, 2000003, 3, 'Oral pH modulation and bacterial metabolic responses following herbal rinse application: exploratory mechanistic findings', 'Franz Fernandes//Anika Kowalski//Jonas Yilmaz', 'Pediatric Clinical Trials Journal', 2019, 'Background: The mechanisms underlying antimicrobial efficacy of herbal oral rinses remain incompletely characterized. Secondary analysis of our randomized trial examined plaque biochemistry and bacterial metabolic markers. Setting: Sixty participants from the parent trial contributed biosamples. Methods: Plaque pH was assessed at multiple timepoints; bacterial species composition was analyzed via targeted microbiology. Participants receiving the herbal extract displayed higher oral pH readings in plaque biofilms relative to controls. Bacterial ATP production and acid generation appeared suppressed in the active-treatment group. No significant changes in other oral flora or tissue health markers were observed. The magnitude of pH change did not correlate with individual baseline caries risk. Conclusions: The herbal preparation may exert part of its antimicrobial effect through localized pH elevation and disruption of bacterial metabolic activity, though additional mechanisms warrant investigation.', '2019-07-24 09:00:00', '2026-07-18 00:00:00', 4, '1', 'Secondary exploratory analysis of double-blind trial', '10.5555/medidex.synthetic.0003', NULL, NULL, 'English', 'Pediatric Clinical Trials Journal Press'),
(NULL, 2000004, 4, 'Protocol for a cluster randomized trial of behaviour modification integrated with cardiac rehabilitation to sustain exercise adherence', 'Jamal Ivanova//Rosalind Esposito//Ingrid Okoye', 'Journal of Chronic Disease Management', 2018, 'Background: Sustaining physical activity gains achieved during cardiac rehabilitation programs remains difficult. Standard programs often fail to produce lasting behavioural change. We describe a protocol for a cluster-randomized trial testing whether targeted behaviour-change coaching can enhance and prolong physical activity participation in patients completing coronary rehabilitation. Methods: Six community-based cardiac rehabilitation clinics will participate. Approximately 96 individuals in the maintenance phase of cardiac rehabilitation will be cluster-randomized to receive either standard care or standard care plus a structured 6-session behaviour modification program delivered by trained facilitators. Randomization occurs at the clinic level to reduce contamination. Primary outcome: objectively measured daily moderate-to-vigorous physical activity and step counts at 6 months, assessed via wearable accelerometer. Secondary outcomes include self-reported health status, life satisfaction indices, and psychological well-being. Eligibility: clinically stable coronary patients with ejection fraction >40%. Analysis will employ mixed models accounting for cluster design. This trial aims to identify scalable strategies for maintaining cardiovascular exercise participation.', '2018-12-23 09:00:00', '2026-02-12 00:00:00', 1, '1', 'Cluster randomized controlled trial across community rehabilitation sites', '10.5555/medidex.synthetic.0004', 'SYNTH-NCT0000003', NULL, 'English', 'Journal of Chronic Disease Management Press'),
(NULL, 2000005, 5, 'Behaviour change intervention during cardiac rehabilitation did not enhance physical activity adherence beyond standard programs at six-month follow-up', 'Jamal Ivanova//Rosalind Esposito//Ingrid Okoye', 'Oncology Supportive Care Journal', 2019, 'Objectives: Cardiac rehabilitation programs successfully promote acute increases in physical activity, but durability of these gains remains uncertain. We tested whether augmenting standard rehabilitation with targeted behaviour-change sessions would sustain higher activity levels. Methods: Ninety-six patients from six cardiac clinics were cluster-randomized to receive either standard care (usual rehabilitation schedule) or usual rehabilitation plus structured behaviour counselling (6 sessions over 16 weeks). Primary outcome: accelerometer-derived moderate-to-vigorous activity minutes and daily steps at 6 months. Results: At 6-month assessment, mean daily MVPA was 38 minutes in the standard-care group versus 41 minutes in the behaviour-intervention group (difference 3 minutes; 95% CI -5 to 11 minutes; p=0.31). Daily steps were similar (6,892 versus 7,134; p=0.42). No between-group differences were observed in self-rated health, quality of life, or mental well-being. Conclusion: The behaviour intervention did not produce clinically meaningful improvements beyond standard rehabilitation, possibly because both groups maintained excellent activity levels through ongoing program participation.', '2019-10-10 09:00:00', '2026-02-18 00:00:00', 2, '1', 'Cluster randomized controlled trial with 6-month follow-up', '10.5555/medidex.synthetic.0005', NULL, NULL, 'English', 'Oncology Supportive Care Journal Press'),
(NULL, 2000006, 6, 'Corrigendum to ''Behaviour change intervention during cardiac rehabilitation''', 'Jamal Ivanova//Rosalind Esposito//Ingrid Okoye', 'Oncology Supportive Care Journal', 2020, 'In the published article, Table 2 incorrectly labeled the secondary outcome columns, with ''Quality of Life Index'' and ''Mental Well-being Scale'' transposed. The corrected table has been verified by the authors and confirms all reported p-values and effect sizes remain accurate. The conclusions regarding absence of intervention benefit are unchanged.', '2020-01-02 09:00:00', '2026-01-16 00:00:00', 5, '1', 'Cluster randomized controlled trial', '10.5555/medidex.synthetic.0006', 'SYNTH-NCT0000003', NULL, 'English', 'Oncology Supportive Care Journal Press'),
(NULL, 2000007, 7, 'Protocol for a cluster randomized trial of digital health support for obesity prevention in early childhood settings in urban China', 'Isabela Dahl//Esteban Esposito//Zofia Bergstrom//Tariq Vasquez//Declan Csik', 'Pediatric Clinical Trials Journal', 2022, 'Background: Early childhood represents a critical developmental window for obesity prevention. Schools and family environments shape dietary and activity patterns but lack effective evidence-based tools. We describe a protocol for a cluster-randomized trial of a multi-level digital health intervention targeting preschool-aged children. Methods: Fourteen kindergartens in an urban Chinese region will be randomly assigned to intervention (7 sites) or control (7 sites). Approximately 980 children aged 4-6 years will be enrolled from middle and senior kindergarten classrooms. The intervention comprises a cloud-based health platform providing real-time activity tracking, personalized dietary recommendations, and structured family education sessions. Implementation spans 9 months, with extended 12-month post-intervention surveillance. Data collection occurs at baseline, 4 months, 9 months, and 21 months. Primary outcome: between-group change in BMI z-score at the 9-month endpoint. Secondary outcomes: anthropometric measures, dietary quality, assessed activity levels, cost-effectiveness. Fidelity and engagement metrics will be tracked throughout. Process evaluation will identify implementation barriers and facilitators.', '2022-12-10 09:00:00', '2026-08-16 00:00:00', 1, '1', 'Cluster randomized controlled trial in preschool settings', '10.5555/medidex.synthetic.0007', 'SYNTH-ISRCTN-0000004', NULL, 'English', 'Pediatric Clinical Trials Journal Press'),
(NULL, 2000008, 8, 'Digital health intervention for childhood weight management in preschools: outcomes at nine months from a cluster randomized trial', 'Isabela Dahl//Esteban Esposito//Zofia Bergstrom//Tariq Vasquez//Declan Csik', 'Oncology Supportive Care Journal', 2022, 'Background: The efficacy of digital health tools in paediatric obesity prevention remains incompletely established, particularly in lower-middle income settings. Methods: We randomized 14 kindergartens (980 children, mean age 5.1 years) to receive a 9-month digital health platform intervention (interactive health tracking, dietary guidance, family engagement modules) or standard programming. The primary outcome measured between-group changes in BMI z-scores at month 9. Results: In the intervention group, mean BMI z-score changed by -0.18 (95% CI -0.31 to -0.05), compared to -0.06 (95% CI -0.19 to 0.07) in control sites (between-group difference -0.12; p=0.034). Dietary quality scores improved in both groups, with slightly greater gains in the intervention arm. Physical activity levels were similar between groups. No adverse events were reported. Conclusion: The digital health intervention produced modest but statistically significant reductions in relative weight gain in early childhood, with feasibility demonstrated for school-based deployment.', '2022-02-23 09:00:00', '2026-05-06 00:00:00', 2, '1', 'Cluster randomized controlled trial', '10.5555/medidex.synthetic.0008', NULL, NULL, 'English', 'Oncology Supportive Care Journal Press'),
(NULL, 2000009, 9, 'Study protocol: investigating subanesthetic esketamine as an adjunctive analgesic in emergency laparoscopic surgery for acute gynaecological conditions', 'Yuki Zeleny//Rasmus Girard//Noor Vasquez//Omar Mensah//Isabela Toivonen', 'Annals of Pragmatic Clinical Research', 2016, 'Background: Postoperative pain hyperalgesia and central sensitization contribute to both acute severe pain and long-term chronic pain sequelae. Novel analgesic strategies targeting pain pathophysiology are needed. This protocol describes a randomized investigation of perioperative sub-dissociative esketamine combined with patient-controlled analgesia. Methods: Patients with ectopic pregnancy requiring urgent laparoscopic salpingectomy (target n=84) will be randomized 1:1 to receive intravenous esketamine bolus (0.25 mg/kg) intraoperatively plus postoperative patient-controlled esketamine-sufentanil analgesia versus enhanced opioid analgesia (higher sufentanil dose with saline placebo). Primary outcome: pain sensitivity assessed via standardized questionnaire on postoperative days 1, 2, and 7. Secondary outcomes: pain intensity ratings, depressive symptom screening, serum inflammatory biomarkers (BDNF, prostaglandins), adverse events. Sample size calculated for 80% power to detect a 1.2-unit difference in primary pain sensitivity measure. Blinding, randomization, and allocation concealment will ensure methodologic rigor.', '2016-01-10 09:00:00', '2026-08-22 00:00:00', 1, '1', 'Randomized double-blind controlled clinical trial', '10.5555/medidex.synthetic.0009', NULL, NULL, 'English', 'Annals of Pragmatic Clinical Research Press'),
(NULL, 2000010, 10, 'Perioperative esketamine reduces postoperative pain hypersensitivity compared with higher-dose opioid analgesia in emergency surgery', 'Yuki Zeleny//Rasmus Girard//Noor Vasquez//Omar Mensah//Isabela Toivonen', 'Annals of Rehabilitation Science', 2017, 'Objectives: Post-surgical pain sensitization may drive chronic pain development. We evaluated whether perioperative sub-dissociative esketamine attenuates heightened pain sensitivity following emergency surgical intervention. Methods: Eighty-four patients undergoing urgent laparoscopic salpingectomy for ectopic pregnancy were randomized to intraoperative esketamine bolus (0.25 mg/kg) plus multimodal postoperative analgesia versus enhanced opioid analgesia. Pain sensitivity was quantified using a validated 17-item questionnaire administered on postoperative days 1, 2, and 7. Pain intensity, mood, and inflammatory markers were measured concurrently. Results: Pain sensitivity scores were significantly lower in the esketamine group compared with controls (main effect F=9.88, p=0.002). This benefit was consistent across both minor pain items (p=0.002) and moderate pain items (p=0.002). Acute pain intensity at 30 minutes post-recovery was lower with esketamine (median 3 versus 4 on numeric scale; 95% CI 0.57-2.42; p=0.11). Serum brain-derived neurotrophic factor concentration was elevated in esketamine recipients. Conclusions: Adjunctive perioperative esketamine modestly attenuates early postoperative pain hypersensitivity and may offer benefits within multimodal analgesic regimens for acute surgical pain.', '2017-07-20 09:00:00', '2026-04-03 00:00:00', 2, '1', 'Randomized double-blind controlled trial', '10.5555/medidex.synthetic.0010', NULL, NULL, 'English', 'Annals of Rehabilitation Science Press'),
(NULL, 2000011, 11, 'Phase 2 randomized trial protocol: vitamin D metabolite supplementation to mitigate kidney injury in intensive care patients', 'Aisling Kallio//Omar Tremblay//Wojciech Johansen//Felix Haddad//Rasmus Lindqvist', 'Annals of Pragmatic Clinical Research', 2017, 'Background: Acute kidney injury in critically ill populations carries substantial morbidity and mortality. Preclinical studies suggest vitamin D metabolites possess renoprotective and immunomodulatory properties. This protocol describes a phase 2 randomized investigation of two activated vitamin D formulations in high-risk intensive care patients. Methods: One hundred fifty adults with critical illness and baseline kidney dysfunction risk factors will be randomized to one of three arms: calcifediol (25-hydroxyvitamin D derivative), calcitriol (1,25-dihydroxyvitamin D derivative), or placebo, administered orally. Primary composite outcome combines 7-day mortality, need for renal replacement therapy, and magnitude of serum creatinine elevation using a pre-specified ranking procedure. Secondary outcomes include incidence of new kidney injury, laboratory biomarkers, and transcriptomic analysis of immune cells. Safety monitoring focuses on hypercalcemia incidence. Study design incorporates intent-to-treat analysis with pre-specified subgroup interrogation. Findings will inform subsequent phase 3 trial design and optimal vitamin D formulation selection.', '2017-03-19 09:00:00', '2026-01-27 00:00:00', 1, '1', 'Phase 2 randomized double-blind 3-arm controlled trial', '10.5555/medidex.synthetic.0011', NULL, NULL, 'English', 'Annals of Pragmatic Clinical Research Press'),
(NULL, 2000012, 12, 'Activated vitamin D supplementation did not prevent acute kidney injury in a randomized trial of critically ill patients', 'Aisling Kallio//Omar Tremblay//Wojciech Johansen//Felix Haddad//Rasmus Lindqvist', 'Clinical Outcomes Research Review', 2017, 'Background: While vitamin D metabolites modulate immune and renal function in vitro and in animal models, clinical translation remains uncertain. Methods: One hundred fifty ICU patients at baseline risk for acute kidney injury were randomly assigned to receive calcifediol (n=51), calcitriol (n=50), or placebo (n=49). The primary endpoint was a hierarchical composite (7-day mortality, renal replacement therapy requirement, creatinine elevation) scored using a rank-based algorithm. Secondary endpoints included acute kidney injury incidence and combined dialysis/death. Results: Primary endpoint rank scores were similar across groups: calcifediol versus placebo p=0.85; calcitriol versus placebo p=0.58. Secondary outcomes showed no between-group differences. One hypercalcemia case occurred in each active treatment group; none in placebo. Transcriptomic analysis revealed calcitriol-induced upregulation of immune and metabolic pathways (IFN signalling, oxidative phosphorylation, DNA repair) compared with calcifediol or placebo. Conclusions: Neither activated vitamin D formulation reduced acute kidney injury risk or mortality in this high-risk population, despite favorable immunological signalling patterns.', '2017-05-07 09:00:00', '2026-04-17 00:00:00', 2, '1', 'Phase 2 randomized double-blind controlled trial', '10.5555/medidex.synthetic.0012', 'SYNTH-ISRCTN-0000006', NULL, 'English', 'Clinical Outcomes Research Review Press'),
(NULL, 2000013, 13, 'Protocol for a phase 2 randomized trial of a novel monoclonal antibody for malaria prophylaxis in young children in East Africa', 'Umberto Ricci//Amara Zeleny//Noor Kallio', 'Journal of Geriatric and Aging Research', 2017, 'Background: Passive immunization with monoclonal antibodies targeting malaria parasite antigens offers a novel strategy complementing artemisinin-based prevention. Previous testing in older children under seasonal transmission showed promise; efficacy and safety in infants and younger children under intense perennial transmission remain unknown. Methods: This phase 2 trial comprises two stages. Stage 1 involves sequential age-de-escalation and dose-escalation cohorts (children aged 5-10 years, then 5-59 months, then 5-71 months) receiving single escalating doses of monoclonal antibody L9LS (5, 10, 20, 30, or 40 mg/kg) or placebo (3:1 randomization) to assess safety and tolerability. Stage 2 randomizes 324 children aged 5-59 months to two-dose L9LS (baseline and month 6), single-dose L9LS (baseline only), or placebo, with 12-month surveillance for malaria infection via monthly blood slides. Primary efficacy endpoint: Plasmodium falciparum infection incidence. Primary safety endpoint: adverse event rates. Secondary endpoints include parasitaemia levels, clinical malaria episodes, and antibody levels.', '2017-10-08 09:00:00', '2026-01-11 00:00:00', 1, '1', 'Phase 2 randomized double-blind placebo-controlled trial', '10.5555/medidex.synthetic.0013', NULL, NULL, 'English', 'Journal of Geriatric and Aging Research Press'),
(NULL, 2000014, 14, 'Monoclonal antibody L9LS demonstrates partial protective efficacy against malaria parasitaemia in young East African children', 'Umberto Ricci//Amara Zeleny//Noor Kallio', 'Journal of Respiratory Care Research', 2018, 'Background: Monoclonal antibody-based malaria prophylaxis represents an emerging intervention strategy. We evaluated safety and efficacy of L9LS in an area of intense year-round transmission. Methods: Following safety/tolerability assessment in age-stratified cohorts, 324 children aged 5-59 months in western Kenya were randomized to receive two L9LS injections (10-20 mg/kg at months 0 and 6; n=106), single injection (n=108), or placebo (n=110). Children underwent monthly blood-slide examination for 12 months. Results: In the two-dose group, 66% of children experienced at least one episode of parasitaemia during follow-up versus 83% in placebo recipients (protective efficacy 42.7%; 95% CI 22.5-57.7; p=0.0003). Adverse events were rare and balanced between groups (grade 3 or worse in 1% of L9LS injections versus 1% of placebo). No serious safety signals emerged. Peak antibody levels correlated with parasite suppression. Conclusions: Bi-annual L9LS dosing conferred modest but clinically relevant malaria protection in young children, with an acceptable safety profile. Higher dosing strategies warrant exploration to improve efficacy in this high-transmission setting.', '2018-02-13 09:00:00', '2026-06-07 00:00:00', 2, '1', 'Randomized double-blind placebo-controlled trial', '10.5555/medidex.synthetic.0014', 'SYNTH-NCT0000007', NULL, 'English', 'Journal of Respiratory Care Research Press'),
(NULL, 2000015, 15, 'Immunological correlates and subgroup efficacy analysis of monoclonal antibody L9LS for malaria: findings from the extended follow-up', 'Umberto Ricci//Amara Zeleny//Noor Kallio', 'Journal of Women''s Health Trials', 2019, 'Background: Monoclonal antibody efficacy may vary by host and transmission factors. We conducted secondary analysis of immune responses and treatment heterogeneity. Methods: Serum samples and clinical data from 324 trial participants were analyzed. Circulating antibody titers, cellular immune markers, and age/nutritional subgroups were examined in relation to parasitaemia outcomes. Results: Antibody persistence at 12 months was higher in the two-dose group (median titer 850 versus 340 in single-dose; p<0.001). In stratified analyses, efficacy was greater in children aged 24-59 months (protective efficacy 49%) than 5-23 months (33%). Baseline nutritional status and prior malaria exposure did not significantly modify efficacy. Clinical malaria episodes (fever with parasitaemia) were reduced 38% in two-dose versus placebo. Conclusions: Antibody concentration and age appear to influence L9LS protective efficacy; optimized dosing for younger infants and strategies to enhance immune persistence merit investigation.', '2019-02-07 09:00:00', '2026-08-19 00:00:00', 4, '1', 'Secondary analysis of randomized double-blind trial', '10.5555/medidex.synthetic.0015', 'SYNTH-NCT0000007', NULL, 'English', 'Journal of Women''s Health Trials Press'),
(NULL, 2000016, 16, 'Continuous glucose monitoring systems improve measurement precision and reduce nursing burden in sepsis management: a randomized validation study', 'Dovile Okoye//Bruno Lindqvist//Lukas Tremblay//Oleksandr Hussain//Wanjiru Underwood', 'Journal of Public Health Interventions', 2020, 'Background: Accurate real-time glucose monitoring in critical illness enables better insulin titration and avoids hypoglycaemia. We compared a wearable continuous monitoring device against standard fingerstick and laboratory-based glucose measurement in septic patients. Methods: Sixty ICU patients with confirmed sepsis were randomized to continuous glucose monitoring (CGM) plus standard care or standard care alone. CGM readings were compared against laboratory values using correlation analysis and Clarke error grid analysis. Protocol adherence, measurement time, and hypoglycaemic episode detection were monitored. Results: The CGM system demonstrated excellent agreement with reference methods (correlation coefficient r=0.986; p<0.001) with mean absolute relative deviation of 11.44%. Clarke error grid analysis showed 91.9% of readings in clinically safe zone A and 8.1% in zone B. The CGM group achieved higher glycaemic protocol adherence (73.91% versus 48.16%; p<0.001) and required shorter measurement intervals (41 seconds versus 64 seconds; p<0.001). Hypoglycaemic events were detected more frequently with CGM (2.46% versus 0.28%; p<0.001). Time within target glucose range was 33.23% in CGM versus 26.26% in standard care. Adverse events were not increased. Conclusion: CGM provides accurate real-time glucose monitoring, improves protocol adherence, and enhances early hypoglycaemia recognition in critically ill septic patients.', '2020-06-23 09:00:00', '2026-02-06 00:00:00', 2, '1', 'Prospective randomized validation trial in ICU setting', '10.5555/medidex.synthetic.0016', NULL, NULL, 'English', 'Journal of Public Health Interventions Press'),
(NULL, 2000017, 17, 'Retraction notice: ''Continuous glucose monitoring systems improve measurement precision...''', 'Dovile Okoye//Bruno Lindqvist//Lukas Tremblay//Oleksandr Hussain//Wanjiru Underwood', 'Journal of Public Health Interventions', 2021, 'The authors are retracting this article due to data irregularities identified during post-publication verification of the raw dataset. Specifically, discrepancies between source documentation and reported glucose values were discovered in approximately 8% of measurements, suggesting potential transcription errors or equipment calibration problems that compromise result interpretation. The corresponding author and institution are investigating the matter. Readers should not rely on the reported accuracy metrics or clinical recommendations pending resolution.', '2021-10-08 09:00:00', '2026-06-15 00:00:00', 6, '1', 'Retracted prospective randomized trial', '10.5555/medidex.synthetic.0017', NULL, NULL, 'English', 'Journal of Public Health Interventions Press'),
(NULL, 2000018, 18, 'Protocol for testing a peer-facilitated behaviour intervention to enhance HIV prevention advocacy and reduce stigma among Ugandan PLHIV', 'Ulla Jansen//Dovile Ricci//Farah Underwood//Yuki Gomulka', 'Oncology Supportive Care Journal', 2021, 'Background: Community-level HIV prevention remains inadequate in high-prevalence settings. Empowering people living with HIV (PLHIV) to serve as prevention advocates may amplify public health impact beyond individual clinical care. Methods: This randomized controlled trial will enrol 210 PLHIV (105 intervention, 105 control) and 599 social network members in Uganda. The intervention arm receives an 8-session peer-facilitated curriculum designed to enhance HIV prevention knowledge, build advocacy self-efficacy, reduce internalized stigma, and facilitate disclosure within social networks. Control participants receive standard care. Assessments occur at baseline, 6, 12, and 18 months. Primary outcomes: internalized stigma (measured by validated scale) and self-reported prevention advocacy activities in the 12 months preceding follow-up. Secondary outcomes: disclosure patterns among index participants and HIV testing rates and protective behaviours among exposed network members. Proposed sample size of 210 provides 80% power to detect clinically meaningful between-group differences. Analysis will employ mixed-effect models accounting for social network clustering.', '2021-09-11 09:00:00', '2026-07-16 00:00:00', 1, '1', 'Randomized controlled trial with nested social network component', '10.5555/medidex.synthetic.0018', NULL, NULL, 'English', 'Oncology Supportive Care Journal Press'),
(NULL, 2000019, 19, 'Peer-facilitated behaviour intervention successfully reduced internalized stigma and promoted HIV prevention advocacy in PLHIV: findings from a Ugandan randomized trial', 'Ulla Jansen//Dovile Ricci//Farah Underwood//Yuki Gomulka', 'Clinical Outcomes Research Review', 2022, 'Background: Stigma remains a barrier to HIV prevention engagement. We tested whether structured peer-facilitated counselling could enable PLHIV to become community prevention advocates. Methods: Two hundred ten PLHIV in Uganda were randomized to an 8-module peer-led behaviour intervention or control. Participants completed assessments at baseline, 6, 12, and 18 months. Primary outcomes: internalized stigma (assessed via 8-item standardized instrument) and prevention advocacy behaviour. Secondary outcomes: disclosure to social network members; among 599 network members, HIV testing uptake and condom use frequency. Results: The intervention group reported significantly lower internalized stigma compared with control at 18 months (p=0.002). Self-reported prevention advocacy activities were higher in intervention participants (mean 12.4 versus 6.8 activities in past year; p<0.001). Advocacy self-efficacy increased by 37% in intervention versus 8% in controls (p<0.001). Among social network members, those aware of a network member''s HIV advocacy efforts showed higher HIV testing rates (58% versus 42%; p=0.008) and reported more consistent condom use. Conclusions: Peer-facilitated behaviour change successfully reduced stigma and activated prevention advocacy, with measurable indirect benefits to social networks.', '2022-03-26 09:00:00', '2026-02-09 00:00:00', 2, '1', 'Randomized controlled trial with social network outcomes', '10.5555/medidex.synthetic.0019', 'SYNTH-NCT0000009', NULL, 'English', 'Clinical Outcomes Research Review Press'),
(NULL, 2000020, 20, 'Protocol for an exploratory analysis of hypertension-related treatment heterogeneity in anticoagulation for cryptogenic stroke with atrial cardiopathy', 'Elif Kowalski//Grace Zeleny//Wanjiru Hussain', 'Journal of Community Health Interventions', 2019, 'Background: Randomized trials of anticoagulation versus antiplatelet agents in cryptogenic stroke have yielded conflicting results, possibly due to misclassification of stroke aetiology. Hypertension-related small vessel disease may differ mechanistically from cardioembolic mechanisms. Objective: We describe a protocol for exploratory analysis of a completed randomized trial examining whether severity of hypertension modifies treatment effect of anticoagulation versus antiplatelet therapy. Methods: Analysis will include 945 participants from the parent randomized trial (from 185 North American sites, 2018-2023) with recent cryptogenic stroke, documented atrial cardiopathy on imaging, and available baseline hypertension data. Hypertension with high-risk features is defined as: systolic blood pressure ≥160 mm Hg at randomization, left ventricular hypertrophy on echocardiography, or both. Primary outcome: recurrent ischemic stroke or systemic embolism. Cox proportional hazards models will examine treatment-by-hypertension interaction. Hypothesis: anticoagulation (apixaban) provides benefit in patients without advanced hypertension but not in those with hypertension-related high-risk features.', '2019-06-09 09:00:00', '2026-03-28 00:00:00', 1, '1', 'Pre-planned exploratory subgroup analysis of randomized controlled trial', '10.5555/medidex.synthetic.0020', NULL, NULL, 'English', 'Journal of Community Health Interventions Press'),
(NULL, 2000021, 21, 'Hypertension severity modifies anticoagulation benefit in cryptogenic stroke with atrial cardiopathy: exploratory analysis from the ARCADIA trial', 'Elif Kowalski//Grace Zeleny//Wanjiru Hussain', 'Journal of Geriatric and Aging Research', 2020, 'Background: Disparate trial results in cryptogenic stroke may reflect heterogeneous underlying stroke mechanisms. We examined whether hypertension severity modifies anticoagulation efficacy. Methods: From 945 patients with cryptogenic stroke and atrial cardiopathy randomized to apixaban versus aspirin between 2018 and 2023, we analysed 945 with complete hypertension and imaging data. Hypertension with high-risk features (elevated systolic BP ≥160 mmHg and/or ventricular hypertrophy imaging) was present in 351 (37.1%) participants. Results: A significant treatment-by-hypertension interaction was observed (p=0.024). In 594 patients without high-risk hypertension, apixaban demonstrated superior efficacy (hazard ratio 0.43; 95% CI 0.22-0.85; absolute risk reduction 3.4% over median 1.6 years). Conversely, in 351 with hypertension high-risk features, no efficacy difference emerged (hazard ratio 1.68; 95% CI 0.78-3.62; p=0.19); absolute event rate difference 2.4% favoured aspirin. Conclusions: Advanced hypertension phenotypes may indicate stroke mechanisms resistant to anticoagulation benefit, possibly reflecting hypertensive arteriolosclerosis rather than cardioembolism. Trial design accounting for hypertension severity may better identify populations deriving anticoagulation benefit in cryptogenic stroke.', '2020-07-14 09:00:00', '2026-07-02 00:00:00', 2, '1', 'Randomized controlled trial exploratory subgroup analysis', '10.5555/medidex.synthetic.0021', NULL, NULL, 'English', 'Journal of Geriatric and Aging Research Press'),
(NULL, 2000022, 22, 'Bactericidal Activity and Tolerability of Novel Combination Therapy in Drug-Resistant Tuberculosis: A Pharmacodynamic Investigation', 'Aisling Kowalski//Isabela Fernandes//Aisling Brennan', 'Clinical Nutrition Trials Journal', 2017, 'Patients with rifampicin-resistant tuberculosis (RR-TB) require intensive multi-drug regimens. We assessed the bactericidal effectiveness and safety profile of a four-drug combination therapy compared with conventional treatment in a cohort of RR-TB patients enrolled across two treatment centers. Participants received the investigational regimen as part of a treatment protocol implemented in clinical settings in Eastern Europe and South Africa. Sputum smear conversion and bacterial load reduction were measured at defined intervals. The investigational combination achieved approximately 18% higher bacillary clearance compared to standard therapy in the overall population, with particularly strong results in patients without severe systemic disease. However, accelerated bacterial reduction was observed in only a subset of patients. Hematologic complications, including anemia and reduced neutrophil counts, were more prevalent among those receiving higher cumulative drug exposure, though these did not necessitate treatment discontinuation in most cases. The clinical findings support the use of this intensive multi-drug approach as a viable treatment option for patients with resistance to first-line agents.', '2017-06-13 09:00:00', '2026-08-24 00:00:00', 2, '1', 'Prospective pharmacodynamics and safety observational trial', '10.5555/medidex.synthetic.0022', 'SYNTH-NCT0000011', NULL, 'English', 'Clinical Nutrition Trials Journal Press'),
(NULL, 2000023, 23, 'Protocol for Evaluating an Adherence-Focused Digital Mental Health Tool in Adults with Generalized Anxiety', 'Camille Girard//Zofia Schmidt//Rasmus Csik', 'Annals of Pragmatic Clinical Research', 2020, 'Background: Digital mental health interventions show promise for anxiety disorders, yet adherence and durability of clinical gains remain uncertain. This protocol describes a prospective evaluation of a behavioral-flexibility-focused smartphone application combined with routine care versus routine care alone. Methods: We will randomize 96 individuals (aged ≥19 years) with diagnosed generalized anxiety disorder to receive either the active intervention plus standard support or standard support alone. The intervention period will span 10 weeks, with follow-up assessment at week 15. Outcome evaluators will remain masked to treatment allocation. The primary metric will be change in standardized anxiety severity scales from baseline to intervention endpoint. Secondary measures will capture worry frequency and mood symptoms. We will also track adherence through in-app engagement metrics and assess acceptability. Data collection will occur at baseline, mid-intervention (week 5), post-intervention (week 10), and follow-up (week 15).', '2020-02-20 09:00:00', '2026-06-01 00:00:00', 1, '1', 'Randomized controlled trial, outcome assessors blinded', '10.5555/medidex.synthetic.0023', NULL, NULL, 'English', 'Annals of Pragmatic Clinical Research Press'),
(NULL, 2000024, 24, 'Clinical Outcomes of a Smartphone-Delivered Behavioral Flexibility Intervention for Anxiety Disorders', 'Camille Girard//Zofia Schmidt//Rasmus Csik', 'International Journal of Rehabilitation Trials', 2021, 'A 10-week randomized controlled trial examined whether an evidence-based psychological app, delivered via smartphone and integrated into standard care, reduced anxiety severity in 96 adults (mean age 38 years) with generalized anxiety disorder. Half received the application alongside standard counseling and support; the other half received standard support alone. At 10 weeks, the application group demonstrated greater reduction in anxiety ratings (mean difference −2.1 points on the 21-point scale, p = 0.003) compared to controls. Secondary outcomes including worry measures and depressive symptoms showed improvements across all measures in the intervention group, with effect sizes ranging from small to moderate. Approximately 68% of users engaged with the prescribed frequency at the intervention midpoint, declining slightly to 62% by week 10. Improvements were largely sustained through the 15-week follow-up. Patient satisfaction with the digital tool was high, with 79% reporting it was helpful or very helpful. Results suggest smartphone-delivered psychological interventions can produce clinically meaningful anxiety reduction when integrated into routine care.', '2021-01-22 09:00:00', '2026-01-22 00:00:00', 2, '1', 'Parallel-group randomized trial, outcome evaluators masked', '10.5555/medidex.synthetic.0024', NULL, NULL, 'English', 'International Journal of Rehabilitation Trials Press'),
(NULL, 2000025, 25, 'Engagement Patterns and Therapeutic Mediators in Digital Anxiety Intervention', 'Camille Girard//Zofia Schmidt//Rasmus Csik', 'Journal of Women''s Health Trials', 2022, 'We conducted post-hoc mediation and subgroup analyses on data from our 96-participant trial comparing a digital anxiety intervention plus standard care to standard care alone. Participants with higher baseline anxiety severity (top quartile) showed greater absolute symptom reductions (mean −3.4 vs −1.8 in lower-severity group, p = 0.018). Mediation modeling suggested that approximately 40% of the intervention''s effect on anxiety was mediated through increases in reported behavioral engagement and social re-engagement. Participants achieving at least weekly engagement with core application features showed 2.3-fold greater likelihood of meeting the study''s clinical response criterion. Subgroup analysis by age revealed larger effect sizes in participants under age 50 compared to older adults (d = 0.68 vs 0.42). Acceptability ratings were similar across demographic subgroups. These findings highlight that intervention efficacy depends partly on engagement frequency and suggest that tailored engagement strategies may optimize outcomes in older or initially lower-engagement populations.', '2022-09-15 09:00:00', '2026-02-18 00:00:00', 4, '1', 'Secondary analysis of randomized trial data', '10.5555/medidex.synthetic.0025', 'SYNTH-NCT0000012', NULL, 'English', 'Journal of Women''s Health Trials Press'),
(NULL, 2000026, 26, 'Prevention of Heel Tissue Breakdown in High-Risk Patients: Protocol for a Multi-Site Implementation Trial', 'Mateus Bergstrom//Paloma Brennan//Wojciech Quraishi', 'Journal of Translational Patient Care', 2018, 'Rationale: Pressure-related tissue damage at the heel remains a significant complication in acute care settings, yet the optimal timing and approach for prevention across different care phases has not been systematically studied. Protocol: This multi-site randomized trial will evaluate whether prophylactic use of a specialized heel protection device reduces the incidence of heel tissue injury in 180 hospitalized patients with neurological conditions or significantly limited mobility. Participants will be enrolled upon arrival at participating ambulance services and followed continuously through emergency departments and hospital ward stays at two academic medical centers in Sweden. Those assigned to the intervention group will receive the protective device applied in the pre-hospital setting and maintained throughout hospitalization; the control group will receive standard positioning and repositioning protocols. Primary outcomes will assess tissue integrity at multiple time-points across the care pathway. Secondary aims will evaluate the feasibility of early implementation in prehospital settings and identify clinical or demographic predictors of tissue breakdown. Risk stratification using validated assessment tools will be performed at each care transition.', '2018-04-04 09:00:00', '2026-03-12 00:00:00', 1, '1', 'Multisite randomized controlled trial, Sweden', '10.5555/medidex.synthetic.0026', NULL, NULL, 'English', 'Journal of Translational Patient Care Press'),
(NULL, 2000027, 27, 'Incidence and Timing of Heel Ulceration Across Acute Care Settings: A Pathway Analysis', 'Mateus Bergstrom//Paloma Brennan//Wojciech Quraishi', 'Journal of Pharmacological Trials', 2019, 'We prospectively followed 183 hospitalized patients with neurological or functional impairments across pre-hospital transport, emergency care, and hospital wards at two Swedish academic centers. One group (91 patients) received a protective heel device beginning in the ambulance; 92 controls received routine care. Among the entire cohort, 38 individuals (21%) developed heel tissue breakdown at various points in the care pathway. In the device group, 18% developed tissue injury compared to 24% in controls. The majority of pressure-related damage occurred during the ward phase (59% of all cases), though early signs were detected in 12% of patients during emergency department evaluation. Univariate analysis identified admission severity score, duration of bed rest, and delayed mobility as predictive of tissue breakdown (p < 0.05). Skin inspection protocols alone did not prevent most injuries. Device use was associated with reduced injury progression to deeper tissue layers. These results suggest that multi-phase prevention strategies beginning in prehospital care, combined with systematic assessment at ward admission, may improve outcomes in this vulnerable population.', '2019-06-11 09:00:00', '2026-08-01 00:00:00', 2, '1', 'Prospective cohort comparison across care sites', '10.5555/medidex.synthetic.0027', 'SYNTH-ISRCTN-0000013', NULL, 'English', 'Journal of Pharmacological Trials Press'),
(NULL, 2000028, 28, 'Risk Stratification and Prevention Response in Complex Acute Admissions', 'Mateus Bergstrom//Paloma Brennan//Wojciech Quraishi', 'Pediatric Clinical Trials Journal', 2020, 'We performed secondary analyses on 183 patients from our prevention trial, focusing on the predictive accuracy of standardized risk assessment at different care transitions and the relationship between documented preventive actions and clinical outcomes. Formal risk assessment was documented in only 34% of prehospital encounters, 56% of emergency department admissions, and 87% of ward admissions. Among 75 patients stratified as high-risk at ward admission, 41 (55%) subsequently developed tissue breakdown, whereas among 108 low-risk patients, 15 (14%) developed injury, giving a 3.9 relative risk. Notably, tissue breakdown did not occur exclusively in high-risk patients; 23% of low-risk stratified patients experienced injury, suggesting assessment limitations. Documented preventive measures (positioning records, turning schedules) were more complete at the ward level but adherence to these protocols was inconsistent. Patients who received preventive interventions within the first 8 hours of admission had lower injury rates (16% vs 28%). The protective device was associated with 35% relative risk reduction in the subgroup receiving it within 6 hours of presentation. Cost-effectiveness analysis suggested that early systematic assessment with targeted intervention would be cost-neutral compared to treating established injuries.', '2020-04-03 09:00:00', '2026-07-18 00:00:00', 4, '1', 'Observational cohort sub-analysis, multiple care settings', '10.5555/medidex.synthetic.0028', 'SYNTH-ISRCTN-0000013', NULL, 'English', 'Pediatric Clinical Trials Journal Press'),
(NULL, 2000029, 29, 'Effectiveness of a Standalone Digital Platform for Postpartum Depression: A Randomized Comparative Effectiveness Study', 'Xavier Toivonen//Kwame Bergstrom//Lukas Kallio//Yusuf Dubois//Chiara Valdes', 'Journal of Infectious Disease Interventions', 2022, 'Postpartum depression affects a substantial proportion of new mothers and limits engagement with usual treatment. We randomized 264 postpartum women to receive either a standalone mobile application designed to address depressive symptoms or an active control intervention. Both groups had access to routine postpartum care. Depressive symptoms were assessed using standardized depression screening tools, and functional capacity was measured using clinician-rated global impression scales at treatment endpoint. The application group demonstrated greater improvement in depression scores compared to controls (mean reduction 8.2 points vs 4.1 points, p = 0.001, Cohen d = 0.55). Functional impairment also improved more substantially in the intervention group (mean 1.8-point improvement vs 0.9-point improvement on clinical global impression, p = 0.008). Treatment effects were observed across diverse demographic subgroups. User engagement with the platform was variable; approximately 58% of participants engaged with core features at least twice weekly. The intervention was well-tolerated with high acceptability ratings. These findings suggest that well-designed standalone digital interventions can meaningfully reduce depressive symptoms in the postpartum period.', '2022-09-13 09:00:00', '2026-02-17 00:00:00', 2, '1', 'Randomized controlled trial, active control design', '10.5555/medidex.synthetic.0029', 'SYNTH-ISRCTN-0000014', NULL, 'English', 'Journal of Infectious Disease Interventions Press'),
(NULL, 2000030, 30, 'Structured Digital Lifestyle Intervention in the Interpregnancy Period: A Multisite Implementation Study', 'Bo Brennan//Sofia Novak//Nadia Lindqvist', 'Journal of Maternal and Perinatal Health', 2019, 'Background: Weight gain between pregnancies and during pregnancy is associated with obstetric and neonatal complications. Few interventions target this critical window. Methods: This multisite randomized protocol will evaluate a comprehensive lifestyle program delivered primarily through digital platforms in postpartum women at increased risk for adverse outcomes. Women will be recruited in the immediate postpartum period (days 2-3) and randomized at week 6 postpartum. The intervention includes structured coaching sessions delivered in-person or remotely, a Bluetooth-connected mobile application linking to wearable activity trackers and digital scales, and content addressing nutrition, physical activity, weight management, and mental well-being. Intervention will be delivered during the postpartum period (4 sessions over 6 months) and again during the subsequent pregnancy (3 sessions across trimesters). Control participants will receive routine postpartum and antenatal care. Primary outcome is a composite indicator of maternal and neonatal morbidity in the subsequent pregnancy. Secondary outcomes will assess adherence, weight trajectories, and behavioral mediators. Data collection includes medical records, anthropometric measurements, device-generated activity and weight data, and questionnaires at standard intervals.', '2019-05-22 09:00:00', '2026-03-22 00:00:00', 1, '1', 'Multisite randomized controlled trial', '10.5555/medidex.synthetic.0030', 'SYNTH-NCT0000015', NULL, 'English', 'Journal of Maternal and Perinatal Health Press'),
(NULL, 2000031, 31, 'E-Health Supported Lifestyle Modification and Pregnancy Outcomes: A Comparative Effectiveness Study', 'Bo Brennan//Sofia Novak//Nadia Lindqvist', 'Journal of Chronic Disease Management', 2020, 'We conducted a multisite randomized trial of a digital lifestyle intervention designed to improve metabolic health and outcomes in subsequent pregnancies. Women recruited in the immediate postpartum period were randomized at 6 weeks to receive either structured digital coaching combined with mobile health monitoring (n = 187) or standard postpartum care (n = 191). The intervention was delivered across the interpregnancy period and during the subsequent pregnancy. The primary composite outcome (any occurrence of pregnancy-induced hypertension, gestational diabetes mellitus, caesarean delivery, or delivery of a large-for-gestational-age infant) occurred in 34% of the intervention group compared to 47% in the control group (adjusted odds ratio 0.59, 95% CI 0.41-0.85). Mean gestational weight gain was significantly lower in the intervention group (8.1 kg vs 10.4 kg, p = 0.002). Participant engagement with the application and coaching sessions was variable; approximately 71% completed at least 75% of coaching sessions. Weight loss in the interpregnancy period predicted better subsequent pregnancy outcomes. The intervention was generally well-tolerated with high satisfaction ratings (85% reported satisfaction or high satisfaction). This multisite study provides evidence for digital lifestyle interventions in preventing adverse pregnancy outcomes.', '2020-11-07 09:00:00', '2026-08-16 00:00:00', 2, '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0031', 'SYNTH-NCT0000015', NULL, 'English', 'Journal of Chronic Disease Management Press'),
(NULL, 2000032, 32, 'Adherence Patterns and Outcome Predictors in Digital-Supported Maternal Health Intervention', 'Bo Brennan//Sofia Novak//Nadia Lindqvist', 'International Journal of Sleep and Behavior Research', 2020, 'Secondary analysis examined behavioral adherence patterns and outcome prediction in our 378-participant trial. Participants randomized to the intervention showed variable engagement: 68% completed recommended coaching sessions in the interpregnancy period, declining to 54% during the subsequent pregnancy. Device-measured activity consistently showed improvement during intervention periods (mean 25% increase in daily steps during active coaching, p < 0.001). Participants achieving weight loss during the interpregnancy period (mean 4.2 kg, n = 118) experienced significantly better primary outcomes compared to those without weight loss (26% vs 45% adverse outcomes, p = 0.003). Among intervention completers (defined as ≥75% engagement), the intervention effect on the composite outcome was more pronounced (adjusted OR 0.44 vs 0.59 for intention-to-treat analysis). Secondary metabolic markers including fasting glucose and triglycerides improved with greater app engagement. Demographic analysis identified maternal age, education, and prior pregnancy complications as predictors of engagement. Health economic analysis suggested cost-savings of approximately 3,200 per participant assigned to the intervention due to reduced pregnancy complications. Results support the feasibility of digital health platforms as adjuncts to routine care, with effect sizes dependent on engagement and adherence.', '2020-08-23 09:00:00', '2026-07-27 00:00:00', 4, '1', 'Secondary analysis of implementation trial data', '10.5555/medidex.synthetic.0032', NULL, NULL, 'English', 'International Journal of Sleep and Behavior Research Press'),
(NULL, 2000033, 33, 'Characterizing Rehabilitation Intensity in Stroke Recovery: A Cross-Site Canadian Practice Survey', 'Bruno Yamada//Haruto Underwood//Sofia Zimmermann//Rosalind Brennan', 'Journal of Nursing-Led Care Research', 2020, 'Purpose: Current clinical guidelines recommend high-intensity stepping activities and cardiovascular exercise during inpatient stroke rehabilitation, yet implementation and adherence to these targets remain unclear. This descriptive protocol aims to characterize rehabilitation intensity during typical physical therapy sessions across multiple Canadian rehabilitation facilities. Methods: We will conduct a cross-sectional assessment of rehabilitation sessions at a sample of Canadian inpatient stroke rehabilitation units. Inclusion criteria are medically stable stroke survivors admitted for inpatient rehabilitation, minimum functional capacity to ambulate with assistance of one person. Participants will be assessed during one rehabilitation session using objective devices: wrist-worn monitors will quantify aerobic exercise time (defined as exercise exceeding 40% heart rate reserve), and ankle-worn step counters will record step numbers. We will describe the distribution of aerobic minutes and step counts, their correlation with participant characteristics, and documentation of guideline-adherent exercise intensities. Data will be analyzed using descriptive statistics and correlation methods. This observational study will provide baseline data on current rehabilitation practice patterns.', '2020-03-15 09:00:00', '2026-04-14 00:00:00', 1, '1', 'Descriptive cross-sectional observational study', '10.5555/medidex.synthetic.0033', NULL, NULL, 'English', 'Journal of Nursing-Led Care Research Press'),
(NULL, 2000034, 34, 'Rehabilitation Session Characteristics and Activity Levels in Post-Stroke Inpatient Care', 'Bruno Yamada//Haruto Underwood//Sofia Zimmermann//Rosalind Brennan', 'International Journal of Behavioral Medicine Practice', 2021, 'We characterized rehabilitation intensity during inpatient physical therapy sessions across Canadian rehabilitation centers. One hundred sixty-six stroke survivors (mean age 69 years, 42% female) admitted for inpatient rehabilitation were assessed during a single midpoint rehabilitation session using wearable monitors. Mean aerobic exercise time (defined as >40% of individual heart rate reserve) was 11 minutes (SD 12) per session, with wide variability. Mean step count was 1,030 steps (SD 620). Aerobic minutes and step count showed negligible correlation (R² = 0.002), suggesting these represent relatively independent dimensions of activity. Participants achieving ≥20 aerobic minutes during the session (22% of sample) were more likely to be male, have lower baseline walking distance, and have subcortical stroke location. No significant demographic differences were observed in mean step count. Current practice falls substantially short of guideline recommendations for aerobic intensity. Session content appeared to emphasize stepping activities over cardiovascular conditioning. These findings highlight a potential implementation gap between recommended stroke rehabilitation protocols and typical clinical practice.', '2021-10-09 09:00:00', '2026-04-04 00:00:00', 2, '1', 'Observational cohort of usual care practice', '10.5555/medidex.synthetic.0034', 'SYNTH-ISRCTN-0000016', NULL, 'English', 'International Journal of Behavioral Medicine Practice Press'),
(NULL, 2000035, 35, 'Facility-Level Variation and Barriers to Guideline-Adherent Rehabilitation Intensity', 'Bruno Yamada//Haruto Underwood//Sofia Zimmermann//Rosalind Brennan', 'Journal of Applied Clinical Trials', 2021, 'We examined facility-level variation in rehabilitation intensity across eight participating Canadian centers. Mean aerobic exercise time varied from 6 minutes to 18 minutes per session across sites (range 40-64% of participants achieving guideline-recommended minimum intensity levels). Facilities with lower mean aerobic minutes tended to have larger patient caseloads per therapist and shorter session durations. Session structure analysis revealed that time spent on functional assessment, rest breaks, and patient transportation accounted for 30-45% of scheduled rehabilitation time, leaving 55-70% for active therapy. Participants with greater baseline functional capacity and those receiving extended session durations (≥60 minutes) achieved higher aerobic minutes. Qualitative observations suggested perceived time constraints and reimbursement limitations as reported barriers to higher-intensity protocols. Facilities that provided real-time biofeedback to therapists (via displays of heart rate and step data during sessions) showed non-significantly higher mean aerobic minutes (13 vs 10 minutes, p = 0.11). These facility and structural factors may represent modifiable barriers to implementing guideline-recommended rehabilitation intensity.', '2021-10-04 09:00:00', '2026-03-11 00:00:00', 4, '1', 'Secondary analysis of multi-site comparative practice data', '10.5555/medidex.synthetic.0035', 'SYNTH-ISRCTN-0000016', NULL, 'English', 'Journal of Applied Clinical Trials Press'),
(NULL, 2000036, 36, 'Primary Care Psychological Intervention for Post-ICU Trauma Symptoms: Protocol for a Randomized Clinical Trial', 'Viktor Johansen//Rasmus Petrov//Esteban Wachira//Kavya Petrov', 'Journal of Geriatric and Aging Research', 2017, 'Background: Intensive care unit survivors frequently experience posttraumatic stress symptoms affecting quality of life, yet few interventions are tested in primary care settings. This protocol describes a randomized evaluation of a brief psychologically-informed intervention delivered by general practitioners. Methods: We will randomize approximately 310 adult ICU survivors with clinically significant PTSD symptoms to receive either a brief exposure-based intervention delivered by their primary care physician (4-6 sessions over 3 months) or enhanced usual care consisting of regular primary care plus psychoeducational materials. Participants will be identified through ICU discharge records and contacted for screening. Primary outcomes measure health-related quality of life at 6 and 12 months using standardized instruments. Secondary outcomes include PTSD symptom severity, anxiety, depression, and functional outcomes. Mediation analyses will examine whether improvements in PTSD symptoms explain quality-of-life gains. Participants will provide questionnaire data at baseline, 3 months, 6 months, and 12 months. This pragmatic trial will evaluate implementation feasibility and cost-effectiveness of primary-care-based mental health intervention.', '2017-09-18 09:00:00', '2026-06-19 00:00:00', 1, '1', 'Pragmatic randomized trial in primary care', '10.5555/medidex.synthetic.0036', NULL, NULL, 'English', 'Journal of Geriatric and Aging Research Press'),
(NULL, 2000037, 37, 'Primary Care Intervention and Quality of Life Trajectories in Post-ICU Trauma: One-Year Outcomes', 'Viktor Johansen//Rasmus Petrov//Esteban Wachira//Kavya Petrov', 'Journal of Translational Patient Care', 2017, 'We randomized 319 ICU survivors with moderate-to-severe PTSD symptoms to either a brief primary-care-delivered psychological intervention (n = 159) or enhanced usual care (n = 160). The intervention consisted of 4-6 sessions with general practitioners trained in structured exposure techniques. At 12-month follow-up, the intervention group showed greater improvement in health-related quality of life scores (mean improvement 0.071 points on 0-1 quality-of-life scale, 95% CI 0.010-0.132) compared to controls. This difference emerged gradually, with no significant between-group difference at 6 months but substantial divergence by 12 months. PTSD symptom severity decreased more substantially in the intervention group (mean reduction 12.3 points on symptom scale vs 6.8 points, p = 0.004). Domain-specific analyses showed significant improvements in anxiety/depression and physical functioning scores in the intervention group. Approximately 58% of the intervention group and 41% of controls reported subjectively meaningful improvements in overall quality of life. The intervention was well-tolerated with high completion rates (78% completed ≥3 of 6 planned sessions). These findings suggest that structured primary care interventions may improve long-term quality of life in ICU survivors with PTSD.', '2017-09-28 09:00:00', '2026-03-26 00:00:00', 2, '1', 'Randomized controlled trial with 12-month follow-up', '10.5555/medidex.synthetic.0037', NULL, NULL, 'English', 'Journal of Translational Patient Care Press'),
(NULL, 2000038, 38, 'Regional Anesthesia Techniques for Cesarean Delivery: Comparative Efficacy and Postpartum Mental Health Outcomes', 'Bruno Gomulka//Wojciech Tremblay//Giulia Santos', 'Journal of Public Health Interventions', 2018, 'Adequate postoperative analgesia following cesarean section is essential for maternal recovery and may influence postpartum mental health. Two regional anesthesia approaches are commonly used, yet comparative effectiveness for pain control and mental health outcomes remains unclear. This randomized study will compare two distinct regional anesthesia blocks in women undergoing cesarean delivery. Sixty postoperative women will be randomized 1:1 to receive either an erector spinae plane block or a transversus abdominis plane block following their surgical procedure. Pain severity will be assessed using standardized visual analog scales at multiple timepoints postoperatively. Secondary outcomes include requirement for rescue analgesics, patient satisfaction with pain management, and postpartum depression screening using standardized questionnaires at 4-6 weeks postpartum. All participants will receive standard postoperative care protocols. This comparative effectiveness study will provide data on whether the choice of regional anesthesia technique influences both acute pain outcomes and postpartum mood.', '2018-01-01 09:00:00', '2026-05-21 00:00:00', 1, '1', 'Randomized comparative effectiveness trial', '10.5555/medidex.synthetic.0038', NULL, NULL, 'English', 'Journal of Public Health Interventions Press'),
(NULL, 2000039, 39, 'Efficacy Comparison of Regional Anesthesia Techniques Following Cesarean Delivery', 'Bruno Gomulka//Wojciech Tremblay//Giulia Santos', 'Journal of Endocrine and Metabolic Trials', 2018, 'Sixty postpartum women undergoing cesarean delivery were randomized to receive either an erector spinae plane block (n = 30) or a transversus abdominis plane block (n = 30) for postoperative analgesia. Pain severity, analgesia duration, and satisfaction were compared between groups. The erector spinae plane block provided analgesia for a mean of 16 hours compared to 14 hours with the transversus abdominis plane block (not statistically significant, p = 0.32). Pain scores one hour postoperatively were lower in the erector spinae plane group (mean 2.1 vs 3.2 on 10-point scale, p = 0.03). However, no significant differences were observed at subsequent timepoints (4, 8, 12, 24 hours). Requirement for rescue analgesia was lower in the erector spinae plane group (mean 0 vs 1 additional dose, p = 0.045). Patient satisfaction with pain management was high in both groups (mean satisfaction 8.4/10 both groups). Postpartum depression screening scores at 4-6 weeks postpartum were similar between groups (no significant difference). Both regional anesthesia techniques provided effective postoperative pain control; the erector spinae plane block showed marginal advantage in early pain scores and reduced additional analgesia requirement, though clinical significance of these differences is limited.', '2018-03-21 09:00:00', '2026-01-04 00:00:00', 2, '1', 'Randomized prospective comparative trial', '10.5555/medidex.synthetic.0039', 'SYNTH-ISRCTN-0000018', NULL, 'English', 'Journal of Endocrine and Metabolic Trials Press'),
(NULL, 2000040, 40, 'Optimized Nursing Protocols for Hip Replacement Recovery in Older Patients: Study Design', 'Wanjiru Lindqvist//Oleksandr Lambert//Hana Hussain//Giulia Schmidt//Umberto Ostrowski', 'Oncology Supportive Care Journal', 2020, 'Background: Older adults undergoing hip replacement face prolonged recovery and functional limitations. Enhanced recovery protocols have shown promise in surgical populations. Methods: This single-blind randomized trial will evaluate a structured nursing protocol designed to optimize recovery following hip arthroplasty in 90 patients aged 60 years or older. Participants will be randomized to receive either an optimized multi-component nursing intervention (ERAS protocol) or standard postoperative nursing care. The ERAS protocol comprises enhanced pain management, nutritional optimization, early mobilization, catheter management, temperature regulation, and drainage tube care. Outcomes assessed include pain scores, time to first bowel function, time to ambulation, removal of catheters and drains, hip function scores, independence in activities of daily living, complication rates, hospital length of stay, and patient satisfaction. Assessors evaluating outcomes will remain blinded to group assignment. Data will be collected preoperatively and at multiple postoperative intervals. This study aims to determine whether structured nursing interventions can reduce morbidity and hospitalization duration in older hip replacement patients.', '2020-03-07 09:00:00', '2026-08-13 00:00:00', 1, '1', 'Single-blind randomized controlled trial', '10.5555/medidex.synthetic.0040', NULL, NULL, 'English', 'Oncology Supportive Care Journal Press'),
(NULL, 2000041, 41, 'Structured Nursing Intervention and Recovery Outcomes in Hip Arthroplasty Patients', 'Wanjiru Lindqvist//Oleksandr Lambert//Hana Hussain//Giulia Schmidt//Umberto Ostrowski', 'International Journal of Behavioral Medicine Practice', 2020, 'Ninety older adults (mean age 67 years) undergoing total hip replacement were randomized to receive either an enhanced recovery nursing protocol (ERAS, n = 45) or standard postoperative care (n = 45). The ERAS group received optimized pain management, early mobilization, catheter removal protocols, nutritional support, and other multimodal interventions. The ERAS group demonstrated earlier return of gastrointestinal function (mean 1.2 days vs 2.1 days, p = 0.004), earlier independent ambulation (2.4 vs 3.8 days, p = 0.002), and faster catheter removal (1.8 vs 2.9 days, p = 0.008). Pain scores were significantly lower in the ERAS group across all postoperative timepoints (mean reduction of 1.8 points on 10-point scale, p < 0.001). Hospital length of stay was reduced by approximately 1.5 days in the ERAS group (5.2 vs 6.7 days, p = 0.009). Functional hip scores at discharge were higher in the ERAS group (mean 58 vs 51 points, p = 0.03). Postoperative complication rates were lower in the ERAS group (18% vs 31%, p = 0.08). Patient satisfaction ratings were significantly higher in the ERAS group (mean 8.6/10 vs 7.2/10). These findings demonstrate that structured nursing protocols substantially improve recovery trajectory and reduce hospitalization burden in older hip replacement patients.', '2020-03-27 09:00:00', '2026-01-01 00:00:00', 2, '1', 'Randomized controlled trial with outcome assessor blinding', '10.5555/medidex.synthetic.0041', 'SYNTH-NCT0000019', NULL, 'English', 'International Journal of Behavioral Medicine Practice Press'),
(NULL, 2000042, 42, 'Efficacy and Safety Comparison of Novel Systemic Therapies in Moderate Psoriasis: Study Protocol', 'Camille Novak//Oleksandr Santos//Isabela Schmidt', 'International Trials Register Quarterly', 2019, 'Background: Systemic treatment options for moderate plaque psoriasis continue to expand, yet comparative effectiveness data guide clinical decision-making. Methods: This 52-week, phase IV, randomized, open-label comparative effectiveness trial will evaluate two distinct systemic approaches in patients with moderate chronic plaque psoriasis. Approximately 360 adults (aged ≥18 years) with ≥6 months psoriasis duration and candidacy for systemic therapy will be enrolled. Participants will be randomized 1:2 to receive either subcutaneous injections of an IL-23-pathway inhibitor or daily oral phosphodiesterase-4 inhibitor. Primary outcomes at 16 weeks will be achievement of ≥90% skin clearance and physician-rated complete or nearly-complete clearing with ≥2-grade improvement. At 16 weeks, those receiving the oral agent will be re-randomized based on treatment response, allowing comparison of switching strategies. Secondary outcomes include sustained response at 52 weeks, safety/adverse event profiles, treatment satisfaction, and quality-of-life measures. This pragmatic comparative effectiveness design will provide real-world efficacy and safety data to inform treatment selection.', '2019-11-04 09:00:00', '2026-06-28 00:00:00', 1, '1', 'Open-label phase IV randomized comparative trial', '10.5555/medidex.synthetic.0042', 'SYNTH-NCT0000020', NULL, 'English', 'International Trials Register Quarterly Press'),
(NULL, 2000043, 43, 'Efficacy Comparison of IL-23 Inhibition and PDE-4 Inhibition in Systemic Psoriasis Treatment', 'Camille Novak//Oleksandr Santos//Isabela Schmidt', 'Journal of Applied Clinical Trials', 2019, 'Three hundred fifty-two adults with moderate plaque psoriasis were randomized to receive either subcutaneous IL-23 inhibitor (n = 118) or oral PDE-4 inhibitor (n = 234). At 16 weeks, the IL-23 inhibitor group achieved significantly higher rates of 90% or greater skin clearance (56.8% vs 5.3%, p < 0.001) and physician-assessed complete/nearly-complete clearing with marked improvement (75.4% vs 18.8%, p < 0.001). Among the oral agent group, participants not achieving treatment response threshold were re-randomized at week 16 to either switch to IL-23 inhibitor or continue their current therapy. At 52 weeks, those who switched to IL-23 inhibitor achieved 90% clearance in 72.2% of cases compared to only 2.6% who continued the original oral agent. The IL-23 inhibitor was well-tolerated; most frequent adverse events were upper respiratory tract infections and COVID-19. The oral agent group experienced higher rates of gastrointestinal side effects. Most participants in both groups reported improvement in psoriasis-related quality of life and reduced disease-related burden. These results demonstrate substantially superior efficacy of IL-23 inhibition compared with oral PDE-4 inhibition, particularly when given as initial therapy.', '2019-08-26 09:00:00', '2026-02-04 00:00:00', 2, '1', 'Randomized phase IV comparative effectiveness trial', '10.5555/medidex.synthetic.0043', NULL, NULL, 'English', 'Journal of Applied Clinical Trials Press'),
(NULL, 2000044, 44, 'Treatment Sequencing and Subgroup Response Patterns in Systemic Psoriasis Therapy', 'Camille Novak//Oleksandr Santos//Isabela Schmidt', 'Journal of Nursing-Led Care Research', 2019, 'Secondary analyses examined treatment response patterns, demographic predictors, and outcomes of sequential therapy in our 352-participant trial. Baseline factors associated with favorable IL-23 inhibitor response included lower BMI (mean BMI: responders 26.1 vs nonresponders 28.7, p = 0.03) and absence of joint symptoms (skin-only psoriasis 61% response vs psoriatic arthritis 48% response). Participants achieving complete response by week 16 showed sustained clearing through 52 weeks (92% maintained ≥90% clearance). Among 83 participants who switched from oral to IL-23 inhibitor due to insufficient response, 72% achieved major improvement at subsequent assessment, demonstrating salvage efficacy. Gender differences in response were minimal, though women reported greater quality-of-life gains from treatment. Cost-effectiveness analysis suggested IL-23 inhibitor would be cost-effective if initial efficacy advantage translates to reduced long-term complications. Systemic safety events were rare in both groups over 52 weeks; immunogenicity against IL-23 inhibitor developed in 3% of treated patients. Real-world adherence was higher with IL-23 inhibitor (83% at 52 weeks vs 71% with oral agent). These secondary analyses support IL-23 inhibitor as a preferred first-line option for systemic-eligible patients, with oral agents retaining utility in cost-constrained settings or specific subgroups.', '2019-07-08 09:00:00', '2026-08-18 00:00:00', 4, '1', 'Secondary analysis of comparative effectiveness trial data', '10.5555/medidex.synthetic.0044', NULL, NULL, 'English', 'Journal of Nursing-Led Care Research Press'),
(NULL, 2000045, 45, 'Randomized Evaluation of Conjoint Gender-Equitable Counseling for Reproductive Health Decision-Making in Rural Couples', 'Lukas Moreau//Lena Lindqvist//Rosalind Xu//Sami Zeleny', 'Journal of Women''s Health Trials', 2018, 'Family planning programs must balance individual autonomy with couple communication to achieve sustainable contraceptive uptake. This protocol describes a cluster randomized trial designed to test whether training healthcare providers to deliver gender-aware counseling sessions—conducted jointly with married couples and emphasizing shared decision-making—improves reproductive health outcomes compared to routine provision of contraceptive information. We will recruit approximately 1200 married couples from rural communities. Participants randomized to the intervention receive counseling sessions incorporating structured dialogue, equity principles, and client-centered guidance. Control participants receive conventional family planning services. The primary outcome is contraceptive adoption at 9 months. Secondary outcomes assess perceived quality of clinical interactions and couple relationship factors. We hypothesize that the intervention increases contraceptive use through improved quality of care perceived by both partners.', '2018-07-13 09:00:00', '2026-04-11 00:00:00', 1, '1', 'Cluster randomized controlled trial', '10.5555/medidex.synthetic.0045', 'SYNTH-NCT0000021', NULL, 'English', 'Journal of Women''s Health Trials Press'),
(NULL, 2000046, 46, 'Conjoint Couple-Based Counseling Improves Family Planning Uptake: A Cluster Randomized Trial', 'Lukas Moreau//Lena Lindqvist//Rosalind Xu//Sami Zeleny', 'Journal of Infectious Disease Interventions', 2019, 'Engagement with both spouses during family planning consultations may enhance contraceptive adoption and couple communication. We randomized 1201 married couples to either receive enhanced counseling delivered to both partners, emphasizing gender equity and joint decision-making (intervention), or standard family planning counseling (control). At 9-month follow-up, participants in the intervention group demonstrated higher uptake of modern contraceptive methods compared with controls. Qualitative assessment of the clinical encounter quality, measured through validated instruments, showed that couples receiving the structured gender-aware approach reported greater satisfaction with communication and support. Mediation analysis suggested that improved perceived quality of the healthcare interaction partially explained the intervention''s effect on contraceptive adoption. These findings support the integration of couple-centered and gender-equitable communication strategies into family planning programs to promote contraceptive use while respecting reproductive autonomy.', '2019-11-24 09:00:00', '2026-07-27 00:00:00', 2, '1', 'Cluster randomized controlled trial, rural India', '10.5555/medidex.synthetic.0046', 'SYNTH-NCT0000021', NULL, 'English', 'Journal of Infectious Disease Interventions Press'),
(NULL, 2000047, 47, 'A Prospective Evaluation of Daily Intraocular Pressure Control With Sepetaprost Versus Latanoprost in Ocular Hypertension and Glaucoma: Protocol for a Novel Therapeutic Comparison', 'Mateus Brennan//Isabela Almeida//Ivo Quraishi', 'Journal of Surgical Outcomes Research', 2019, 'Patients with elevated intraocular pressure benefit from pharmacologic therapy, yet identifying optimal treatments requires rigorous comparative evidence. This exploratory protocol evaluates whether sepetaprost—a novel prostaglandin analog—provides superior intraocular pressure reduction over a 24-hour period compared to the established agent latanoprost in adults with primary open-angle glaucoma or ocular hypertension. Approximately 35 participants will be randomly assigned to receive either sepetaprost or latanoprost daily for 12 weeks following a screening phase. The primary outcome is mean 24-hour intraocular pressure measured at the conclusion of treatment. Secondary evaluations include safety assessments, adverse event profiles, and measurements at discrete time points throughout the day and night. This study aims to determine whether the novel formulation offers clinically meaningful advantages in intraocular pressure control.', '2019-04-04 09:00:00', '2026-07-26 00:00:00', 1, '1', 'Exploratory parallel-group randomized trial', '10.5555/medidex.synthetic.0047', 'SYNTH-ISRCTN-0000022', NULL, 'English', 'Journal of Surgical Outcomes Research Press'),
(NULL, 2000048, 48, 'Twenty-Four-Hour Intraocular Pressure Response to Sepetaprost Compared With Latanoprost in Glaucoma Patients', 'Mateus Brennan//Isabela Almeida//Ivo Quraishi', 'Digital Health Trials Journal', 2019, 'Sepetaprost represents a novel prostaglandin formulation with potential therapeutic benefits for glaucoma management. In this exploratory trial, 33 adults with glaucoma or ocular hypertension received either sepetaprost (n=17) or latanoprost (n=16) daily for 12 weeks. At the end of treatment, mean 24-hour intraocular pressure was numerically lower in the sepetaprost group relative to latanoprost, though this difference did not achieve statistical significance at the pre-specified threshold. Nocturnal intraocular pressure measurements demonstrated a trend toward lower values with sepetaprost. Both agents reduced intraocular pressure from baseline by approximately 5-7 mmHg. Adverse events were frequent in both groups, occurring in the majority of participants. Safety profiles were comparable between the two treatments. These findings suggest sepetaprost warrants further investigation in adequately powered studies to clarify its role in glaucoma management.', '2019-10-09 09:00:00', '2026-07-03 00:00:00', 2, '1', 'Exploratory randomized trial, parallel assignment', '10.5555/medidex.synthetic.0048', NULL, NULL, 'English', 'Digital Health Trials Journal Press'),
(NULL, 2000049, 49, 'Circadian Patterns of Intraocular Pressure and Tolerability Outcomes in Patients Treated With Sepetaprost or Latanoprost', 'Mateus Brennan//Isabela Almeida//Ivo Quraishi', 'International Journal of Sleep and Behavior Research', 2020, 'Intraocular pressure exhibits diurnal and nocturnal variation, and agents that effectively suppress pressure throughout the 24-hour cycle may confer clinical advantages. We conducted a secondary analysis of the efficacy and safety data collected at multiple time points across day and night in our treatment cohort. Participants treated with sepetaprost showed greater suppression of nocturnal intraocular pressure compared to latanoprost in a subset of measurements, with a nominal statistical difference noted at the 0.10 significance level. Diurnal pressure reduction was comparable between arms. Posttreatment assessment revealed that intraocular pressure remained below baseline even 36-48 hours after discontinuation in the sepetaprost group. Systemic and ocular tolerability was similar, with ocular surface discomfort and conjunctival hyperemia reported at similar frequencies. These exploratory circadian analyses suggest sepetaprost may offer benefits in overnight pressure control, though larger studies are needed to confirm this finding.', '2020-06-07 09:00:00', '2026-07-23 00:00:00', 4, '1', 'Secondary analysis of circadian intraocular pressure patterns', '10.5555/medidex.synthetic.0049', 'SYNTH-ISRCTN-0000022', NULL, 'English', 'International Journal of Sleep and Behavior Research Press'),
(NULL, 2000050, 50, 'Corrigendum: Twenty-Four-Hour Intraocular Pressure Response to Sepetaprost Compared With Latanoprost', 'Mateus Brennan//Isabela Almeida//Ivo Quraishi', 'Digital Health Trials Journal', 2020, 'In the above-titled article (published this year), the baseline demographic table incorrectly listed the mean age of the latanoprost group as 58±12 years; the correct value is 61±14 years. This correction does not affect the reported efficacy or safety analyses, as randomization ensured group balance, and age was included as a covariate in all statistical models. The conclusions regarding intraocular pressure reduction and adverse event profiles remain unchanged.', '2020-05-17 09:00:00', '2026-02-03 00:00:00', 5, '1', 'Correction notice', '10.5555/medidex.synthetic.0050', 'SYNTH-ISRCTN-0000022', NULL, 'English', 'Digital Health Trials Journal Press'),
(NULL, 2000051, 51, 'Protocol for a Randomized Controlled Trial of Aggressive Beta-Blockade Strategies in Acute Decompensated Cardiac Failure With Rapid Atrial Fibrillation', 'Viktor Wachira//Rasmus Eriksson//Farah Zimmermann//Isabela Ricci', 'Journal of Community Health Interventions', 2020, 'Rapid ventricular response during atrial fibrillation in acute heart failure creates hemodynamic stress and worsens clinical decompensation. This protocol evaluates whether a protocolized approach using a potent beta-blocker combined with additional rate-limiting agents achieves faster heart rate control and greater symptomatic relief compared to conventional rate control strategies. We will enroll approximately 40 hospitalized patients with acute heart failure, systolic dysfunction (ejection fraction <35%), and atrial fibrillation with rapid ventricular response (heart rate >130 beats per minute). Participants are randomly assigned to intensive rate control using beta-blockade plus adjunctive agents or to standard therapy. Endpoints include time to achievement of target heart rate, hemodynamic parameters, dyspnea scores, and adverse events over 24 hours of observation.', '2020-11-12 09:00:00', '2026-01-07 00:00:00', 1, '1', 'Randomized controlled trial', '10.5555/medidex.synthetic.0051', 'SYNTH-ISRCTN-0000023', NULL, 'English', 'Journal of Community Health Interventions Press'),
(NULL, 2000052, 52, 'Rapid Rate Control in Acute Decompensated Heart Failure With Rapid Atrial Fibrillation: Benefits of Intensive Beta-Blockade', 'Viktor Wachira//Rasmus Eriksson//Farah Zimmermann//Isabela Ricci', 'Journal of Chronic Disease Management', 2021, 'Achieving prompt ventricular rate control in the setting of acute heart failure and atrial fibrillation may accelerate hemodynamic recovery and symptom resolution. Forty patients with acute decompensated heart failure, reduced ejection fraction, and uncontrolled atrial fibrillation (heart rate >130) were randomly assigned to intensive rate control using combination beta-blockade or to standard-care rate control. The intensive-control group achieved target heart rate significantly faster, with median time to goal approximately 1.5 hours versus 4 hours in the standard group. At the 2-hour mark, intensive-control participants demonstrated greater absolute heart rate reduction (approximately 40% decrease versus 23% in standard care). Clinical endpoints including dyspnea improvement and resolution of pulmonary congestion were more rapidly attained in the intensive-control arm. Blood pressure remained stable in both groups without excessive hypotensive episodes. At 24 hours, hemodynamic parameters converged between groups. Intensive rate-control strategies offer early symptomatic benefit in acute heart failure complicated by rapid atrial fibrillation.', '2021-11-24 09:00:00', '2026-03-14 00:00:00', 2, '1', 'Randomized controlled trial', '10.5555/medidex.synthetic.0052', 'SYNTH-ISRCTN-0000023', NULL, 'English', 'Journal of Chronic Disease Management Press'),
(NULL, 2000053, 53, 'Feasibility and Efficacy of Wearable Robotic Assistance for Motor Rehabilitation in Parkinson Disease: A Pilot Randomized Controlled Study Protocol', 'Amara Petrov//Bo Tremblay//Dawit Almeida', 'Journal of Chronic Disease Management', 2022, 'Motor dysfunction and gait impairment in Parkinson disease significantly restrict mobility and independence. Emerging robotic technologies may augment traditional physical rehabilitation by providing consistent, quantifiable assistance. This pilot protocol evaluates whether supplementing conventional physical therapy with structured sessions in a soft robotic exoskeleton improves locomotor function and motor symptoms in patients with Parkinson disease. Approximately 56 individuals with Parkinson disease will be randomly allocated to either conventional rehabilitation (control) or identical conventional therapy augmented with soft exoskeleton-assisted training. All participants will receive five sessions weekly for four weeks. Primary outcomes include gait velocity and stride symmetry. Secondary measures encompass ankle range of motion, motor severity scales, and cognitive assessment. We hypothesize that robotic assistance during training facilitates greater locomotor gains than conventional therapy alone.', '2022-03-15 09:00:00', '2026-02-12 00:00:00', 1, '1', 'Pilot parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0053', 'SYNTH-NCT0000024', NULL, 'English', 'Journal of Chronic Disease Management Press'),
(NULL, 2000054, 54, 'Soft Robotic Exoskeleton Training Enhances Gait Parameters in Parkinson Disease: Results of a Pilot Randomized Study', 'Amara Petrov//Bo Tremblay//Dawit Almeida', 'International Journal of Sleep and Behavior Research', 2023, 'Robotic rehabilitation tools may provide advantages over conventional therapy by delivering precisely-calibrated motor assistance. Fifty-six individuals with Parkinson disease underwent randomization to standard rehabilitation versus standard rehabilitation plus four weeks of soft exoskeleton training (five times weekly, 20 minutes per session). The exoskeleton-augmented group demonstrated significantly greater improvements in stride length symmetry and walking speed compared to controls. Specifically, stride length increased by approximately 0.15 meters on both sides, and ankle plantarflexion flexibility improved substantially. Measures of motor severity on standardized clinical scales decreased more in the exoskeleton group. Additionally, participants receiving robotic assistance showed improved balance-related subscale scores and modest gains in cognitive screening measures. Improvements in ankle mobility showed strong positive correlation with overall gait velocity gains, suggesting a mechanistic link. No serious adverse events occurred. Soft robotic exoskeleton training represents a feasible and effective adjunct to conventional rehabilitation for reducing gait dysfunction in Parkinson disease.', '2023-08-17 09:00:00', '2026-07-23 00:00:00', 2, '1', 'Pilot randomized controlled trial', '10.5555/medidex.synthetic.0054', NULL, NULL, 'English', 'International Journal of Sleep and Behavior Research Press'),
(NULL, 2000055, 55, 'Corrigendum: Soft Robotic Exoskeleton Training Enhances Gait Parameters in Parkinson Disease', 'Amara Petrov//Bo Tremblay//Dawit Almeida', 'International Journal of Sleep and Behavior Research', 2024, 'In the article published in this issue, Figure 2 (Gait Kinematics During Four-Week Intervention) was incorrectly duplicated from Figure 1. The correct Figure 2, showing postintervention gait patterns, has been provided to the journal. This correction does not affect the reported numerical results, statistical findings, or the study''s conclusions regarding robotic exoskeleton efficacy.', '2024-10-15 09:00:00', '2026-07-01 00:00:00', 5, '1', 'Correction notice', '10.5555/medidex.synthetic.0055', NULL, NULL, 'English', 'International Journal of Sleep and Behavior Research Press'),
(NULL, 2000056, 56, 'Baseline Sleep Dysfunction and Response to Trauma-Focused Psychotherapy in Women With Complex PTSD: A Secondary Analysis', 'Giulia Csik//Bruno Valdes//Umberto Hussain//Grace Xu', 'Journal of Chronic Disease Management', 2019, 'Sleep disturbances occur frequently in post-traumatic stress disorder and may theoretically interfere with therapeutic learning processes during trauma-focused treatment. To explore this relationship, we conducted a secondary analysis of an existing randomized trial comparing two evidence-based psychotherapy approaches in women with chronic PTSD (n=178). Participants received either cognitive processing therapy or dialectical behavior therapy tailored for PTSD, with treatment duration up to 15 months in outpatient settings. Sleep was assessed using both subjective instruments (self-report questionnaires) and objective actigraphy measurements at baseline. We examined whether sleep quality predicted subsequent PTSD symptom improvement across the full treatment course. Contrary to initial hypotheses, baseline sleep dysfunction—whether measured subjectively or objectively—did not significantly predict the degree of PTSD symptom reduction during either treatment modality. Depressive symptoms did not modify this relationship. These findings suggest that sleep disturbances do not substantially limit the effectiveness of prolonged, structured trauma-focused psychotherapy in women with complex PTSD presentations, and that initiating evidence-based trauma treatment need not be delayed pending sleep normalization.', '2019-06-03 09:00:00', '2026-07-10 00:00:00', 2, '1', 'Secondary analysis of randomized controlled trial', '10.5555/medidex.synthetic.0056', NULL, NULL, 'English', 'Journal of Chronic Disease Management Press'),
(NULL, 2000057, 57, 'Antenatal Physical Activity as a Preventive Strategy Against Postpartum Mood Disorder: A Randomized Controlled Trial Protocol', 'Umberto Esposito//Oleksandr Okoye//Yusuf Weber//Sofia Papadopoulos', 'Annals of Rehabilitation Science', 2020, 'Postpartum depression affects a substantial proportion of women and impairs maternal-infant bonding and family functioning. Physical activity is known to influence mood regulation and stress resilience. This protocol describes a single-center randomized trial designed to test whether a structured aerobic exercise regimen initiated during early pregnancy and maintained through mid-gestation reduces the incidence of postpartum depression in women with uncomplicated pregnancies. Approximately 400 pregnant women will be enrolled at the first prenatal visit and randomly assigned to either participate in a supervised aerobic exercise program (three 60-minute sessions per week) or continue with standard prenatal care. The primary outcome is postpartum depressive symptom severity at three months postpartum, measured by validated screening instruments. Secondary outcomes include clinical diagnosis rates, neonatal outcomes, and maternal physical and metabolic parameters. We hypothesize that maintained prenatal aerobic activity reduces postpartum depression through multiple pathways including improved mood regulation and stress coping.', '2020-06-14 09:00:00', '2026-06-16 00:00:00', 1, '1', 'Single-center parallel randomized controlled trial', '10.5555/medidex.synthetic.0057', NULL, NULL, 'English', 'Annals of Rehabilitation Science Press'),
(NULL, 2000058, 58, 'Prenatal Aerobic Exercise Reduces Postpartum Depression: Findings From a Randomized Controlled Trial of Pregnant Women', 'Umberto Esposito//Oleksandr Okoye//Yusuf Weber//Sofia Papadopoulos', 'Journal of Infectious Disease Interventions', 2020, 'Physical activity during pregnancy may confer psychological benefits that extend into the postpartum period. We randomized 398 pregnant women with uncomplicated pregnancies to either structured aerobic exercise (three 60-minute sessions weekly through mid-gestation) or routine prenatal care. At three months postpartum, women in the exercise group exhibited substantially lower depressive symptom scores on validated instruments compared to the standard-care group. The proportion of women meeting screening criteria for possible postpartum depression was significantly reduced in the exercise group. Clinical diagnoses of postpartum depression were correspondingly lower in the active group. Maternal and neonatal outcomes including gestational complications, delivery method, and neonatal health indicators were similar between groups, indicating the exercise intervention was safe. These findings support incorporating aerobic physical activity into prenatal care as a practical, accessible strategy to reduce postpartum depressive symptoms and promote maternal mental health in low-risk pregnancies.', '2020-05-28 09:00:00', '2026-04-07 00:00:00', 2, '1', 'Randomized controlled trial, single center', '10.5555/medidex.synthetic.0058', 'SYNTH-ISRCTN-0000026', NULL, 'English', 'Journal of Infectious Disease Interventions Press'),
(NULL, 2000059, 59, 'Antenatal Aerobic Exercise and Maternal-Neonatal Outcomes: Exploratory Secondary Findings', 'Umberto Esposito//Oleksandr Okoye//Yusuf Weber//Sofia Papadopoulos', 'Journal of Surgical Outcomes Research', 2020, 'Understanding the broader health impacts of structured prenatal exercise extends beyond mood outcomes to encompass maternal metabolism, infant development, and delivery-related complications. We conducted secondary analyses of maternal weight gain, gestational glucose tolerance, delivery complications, and neonatal birthweight and health indicators in our trial participants. Pregnant women assigned to supervised aerobic activity demonstrated beneficial trends in gestational weight accumulation and metabolic parameters, though these differences did not reach statistical significance in this secondary analysis. Delivery method and perinatal complications were equally distributed across groups. Neonatal outcome measures including birthweight percentiles, Apgar scores, and short-term morbidity were comparable and reassuring across both arms. These secondary findings confirm that structured aerobic exercise during pregnancy is a safe intervention without adverse neonatal consequences, and suggest potential ancillary maternal metabolic benefits that warrant investigation in larger-scale studies.', '2020-08-09 09:00:00', '2026-07-01 00:00:00', 4, '1', 'Secondary analysis of maternal and neonatal outcomes', '10.5555/medidex.synthetic.0059', 'SYNTH-ISRCTN-0000026', NULL, 'English', 'Journal of Surgical Outcomes Research Press'),
(NULL, 2000060, 60, 'Optimizing Implementation Strategies for a Comprehensive School-Based Obesity Prevention Program: A Cluster Randomized Hybrid Effectiveness-Implementation Trial Protocol', 'Tariq Quraishi//Camille Valdes//Chiara Almeida//Oleksandr Kallio', 'Journal of Public Health Interventions', 2021, 'Evidence-based school interventions for obesity prevention often achieve incomplete implementation in real-world settings due to organizational and resource barriers. This protocol describes a hybrid type III cluster-randomized trial comparing two distinct implementation strategy bundles for delivering a comprehensive school-based healthy lifestyle program across multiple schools. Approximately 45 schools will be assigned to receive either a basic implementation support bundle or an enhanced bundle incorporating multiple implementation strategies including educational outreach, stakeholder engagement, and clinical-school linkages. Outcomes assess the degree to which intervention components are delivered with fidelity, measure parental responsiveness to health messaging, and track organizational factors influencing successful adoption. We seek to identify the most efficient and effective combination of implementation strategies to promote sustained program delivery in school settings.', '2021-07-03 09:00:00', '2026-06-05 00:00:00', 1, '1', 'Cluster randomized hybrid type III trial', '10.5555/medidex.synthetic.0060', NULL, NULL, 'English', 'Journal of Public Health Interventions Press'),
(NULL, 2000062, 61, 'Evaluation of an Alternative Costimulation-Blocking Strategy for Preventing Psoriasis Recurrence Following Biologic Agent Withdrawal: A Randomized Controlled Protocol', 'Hana Moreau//Jana Farrell//Bruno Toivonen//Oleksandr Adeyemi//Aisling Okoye', 'Clinical Nutrition Trials Journal', 2018, 'Alternative biologic therapies target different pathogenic pathways in psoriasis, and transitioning between agents may offer clinical advantages. This protocol describes a double-blind, placebo-controlled randomized trial investigating whether costimulatory blockade with an alternative biologic can maintain psoriasis control after withdrawal of a first-line biologic therapy. Adults with moderate-to-severe plaque psoriasis who demonstrate response to an initial biologic agent will enter a lead-in phase. Those achieving clinical improvement are then randomly assigned to either continue the original biologic therapy or switch to an alternative costimulatory-blocking agent, with both maintained through mid-study then withdrawn. The primary outcome is proportion of participants experiencing disease relapse over subsequent follow-up. Secondary endpoints assess time to relapse and molecular disease markers. We hypothesize the alternative mechanism of action will sustain clinical benefit comparable to continued original therapy.', '2018-11-20 09:00:00', '2026-03-10 00:00:00', 1, '1', 'Double-blind parallel randomized controlled trial', '10.5555/medidex.synthetic.0062', NULL, NULL, 'English', 'Clinical Nutrition Trials Journal Press'),
(NULL, 2000064, 62, 'Improving Pain Management Quality in Home-Based Ambulatory Nursing Care: A Pragmatic Cluster Randomized Trial Protocol', 'Isabela Yilmaz//Declan Wachira//Yuki Mensah//Ivo Quraishi//Elena Mensah', 'Journal of Cardiometabolic Research', 2015, 'Chronic pain in older adults is undertreated in many community settings, partly due to gaps in provider knowledge and systemic barriers to adequate assessment and management. This pragmatic cluster-randomized trial tests two distinct implementation strategies to improve pain management quality in home-based nursing services. Community-dwelling older adults will be recruited from 22 participating ambulatory nursing agencies. Agencies are randomly assigned to three arms: (1) individualized provider-level intervention providing patient-specific pain management recommendations and support of a newly trained specialist, (2) organization-level digital education platform for pain management, or (3) standard care control. Primary outcomes assess changes in prescribing appropriateness and patient-reported pain intensity. Secondary measures include documentation quality and care process indicators. This pragmatic approach directly targets real-world implementation barriers in ambulatory settings.', '2015-09-21 09:00:00', '2026-02-22 00:00:00', 1, '1', 'Pragmatic cluster randomized trial with three arms', '10.5555/medidex.synthetic.0064', 'SYNTH-NCT0000029', NULL, 'English', 'Journal of Cardiometabolic Research Press'),
(NULL, 2000065, 63, 'Translating Pain Management Knowledge Into Home-Based Ambulatory Care: Implementation Outcomes From a Cluster Randomized Trial', 'Isabela Yilmaz//Declan Wachira//Yuki Mensah//Ivo Quraishi//Elena Mensah', 'Journal of Chronic Disease Management', 2016, 'Community-based older adults often experience inadequately managed chronic pain due to organizational and provider-level barriers. We conducted a pragmatic trial in 22 ambulatory nursing services comparing individualized provider support, digital education, and control conditions (total 190 baseline, 144 follow-up due to 24% attrition). The individualized provider intervention improved documentation of pain assessments compared to controls; however, this improvement in process measures did not translate to meaningful changes in medication appropriateness or patient-reported pain severity at follow-up. The digital education platform was adopted inconsistently by participating providers and showed similarly limited impact on primary clinical endpoints. Qualitative interviews revealed that substantial structural barriers—including insufficient staffing levels, lack of financial reimbursement mechanisms for pain management activities, and competing clinical demands—constrained implementation of any intervention across all study arms. These pragmatic findings underscore that isolated provider- or system-level interventions may be insufficient without concurrent policy reforms that enable dedicated time and resources for comprehensive pain management in ambulatory elderly populations.', '2016-04-26 09:00:00', '2026-03-25 00:00:00', 2, '1', 'Pragmatic cluster randomized trial', '10.5555/medidex.synthetic.0065', NULL, NULL, 'English', 'Journal of Chronic Disease Management Press'),
(NULL, 2000066, 64, 'Stepped-Wedge Implementation of a Multicomponent Delirium Prevention Intervention in Older Surgical Patients: A Cluster Randomized Trial Protocol', 'Gemma Quraishi//Elena Girard//Anika Brennan//Kavya Weber//Isabela Johansen', 'Journal of Respiratory Care Research', 2020, 'Postoperative delirium substantially increases morbidity, mortality, and healthcare costs in older populations. Effective nonpharmacologic prevention strategies exist but are underutilized in clinical practice. This stepped-wedge cluster-randomized trial will implement a structured, multidisciplinary delirium prevention program across 5 hospital systems and evaluate its effect on delirium incidence in patients aged 70 and older undergoing elective surgical procedures. The intervention combines patient education, staff training on delirium recognition, and structured daily implementation of cognitive stimulation, sensory engagement, mobility support, nutritional optimization, and sleep-promotion strategies tailored to individual risk factors. Delirium will be systematically assessed using validated protocols. Primary outcomes are postoperative delirium incidence and severity. We hypothesize the multicomponent intervention will reduce delirium occurrence by 20% or greater compared to usual care across diverse surgical settings.', '2020-01-19 09:00:00', '2026-01-24 00:00:00', 1, '1', 'Stepped-wedge cluster randomized trial', '10.5555/medidex.synthetic.0066', 'SYNTH-ISRCTN-0000030', NULL, 'English', 'Journal of Respiratory Care Research Press'),
(NULL, 2000067, 65, 'Multimodal Nonpharmacologic Delirium Prevention Reduces Postoperative Delirium in Older Adults: A Stepped-Wedge Trial', 'Gemma Quraishi//Elena Girard//Anika Brennan//Kavya Weber//Isabela Johansen', 'Annals of Rehabilitation Science', 2020, 'Postoperative delirium in older surgical patients remains a significant quality and safety challenge despite available prevention strategies. We evaluated a comprehensive, team-based delirium prevention program implemented across 5 hospitals in 1470 patients aged 70 or older undergoing elective orthopedic, general, or cardiac surgery. The multimodal program included staff education, patient assessment of delirium risk factors, and individualized non-pharmacologic interventions (cognitive engagement, sensory optimization, mobility promotion, sleep support). Overall, the intervention reduced postoperative delirium incidence by approximately 13% compared to standard care, with greater absolute reductions among patients undergoing orthopedic or general surgery (effect most pronounced for these procedure types). Delirium duration—days spent delirious during hospitalization—was also significantly reduced in the intervention group. The prevention program did not produce significant delirium reduction in cardiac surgery patients. No serious adverse events related to the prevention protocol were documented. Implementation was feasible across diverse hospital settings with appropriate staff training. These findings support adoption of multimodal delirium prevention programs, particularly for older patients undergoing orthopedic and general surgical procedures.', '2020-08-10 09:00:00', '2026-07-28 00:00:00', 2, '1', 'Stepped-wedge cluster randomized trial', '10.5555/medidex.synthetic.0067', 'SYNTH-ISRCTN-0000030', NULL, 'English', 'Annals of Rehabilitation Science Press'),
(NULL, 2000068, 66, 'Comprehensive geriatric rehabilitation model reduces functional decline in acute hospital settings: outcomes from a cluster-randomized stepped-wedge implementation trial', 'Kavya Petrov//Xavier Eriksson//Franz Zimmermann//Camille Girard//Dawit Mensah', 'Journal of Pharmacological Trials', 2022, 'In older adults, hospitalization often precipitates substantial loss of mobility and independent functioning. We tested whether an integrated care package combining structured mobility rehabilitation, cognitive support protocols, and simplified medication management could preserve independence in elderly inpatients across departments of a university hospital. This stepped-wedge cluster-randomized trial enrolled 589 older patients (mean age 79.6 years, 48% female) stratified by hospital ward. The intervention integrated supervised physical rehabilitation sessions, delirium prevention protocols, simplified medication regimens, and structured care coordination. Physical capacity and functional independence were assessed at hospital admission, discharge, and 6-month follow-up. Patients assigned to the intervention demonstrated significantly greater improvements in physical capacity from admission to discharge, with sustained benefits through 6-month follow-up. Functional independence scores improved substantially in the intervention group. These findings reinforce the value of early, systematic mobility and supportive-care strategies in counteracting hospitalization-related functional decline in older populations.', '2022-05-01 09:00:00', '2026-03-17 00:00:00', 2, '1', 'Stepped-wedge cluster-randomized trial in acute hospital setting', '10.5555/medidex.synthetic.0068', 'SYNTH-NCT0000031', NULL, 'English', 'Journal of Pharmacological Trials Press'),
(NULL, 2000069, 67, 'Simvastatin as an intracanal medicament compared with hydroxylated-calcium standard in symptomatic periapical inflammation: a randomized trial of pain and immune modulation', 'Umberto Castellano//Elena Ueda//Franz Xu', 'Journal of Community Health Interventions', 2021, 'Periapical inflammation following root canal preparation causes pain and progressive tissue destruction. Calcium-based medications remain standard practice, though alternative agents with immunological properties may offer complementary benefits. We compared a statin-based gel formulation with the conventional hydroxylated-calcium standard as intracanal medication in 30 patients with confirmed necrotic premolars and acute apical inflammatory symptoms. Participants were randomly assigned (n=15 per group) to receive either statin gel or hydroxylated-calcium following mechanical instrumentation. Pain intensity was recorded using numerical rating scales at 6, 12, 24, and 48 hours post-treatment. Inflammatory markers in periapical exudate were quantified at baseline and after one week. At 6 hours, statin-treated patients reported lower pain scores compared to hydroxylated-calcium controls. Pain ratings converged between groups by 24 hours post-treatment. Both medications reduced inflammatory markers from baseline; statin treatment demonstrated differential effects on different inflammatory mediators. No adverse events were documented in either group. While both medications proved clinically effective, preliminary findings suggest statin-based intracanal formulations warrant further investigation as potentially useful additions to standard endodontic protocols.', '2021-01-28 09:00:00', '2026-05-16 00:00:00', 2, '1', 'Double-blind randomized controlled trial', '10.5555/medidex.synthetic.0069', 'SYNTH-ISRCTN-0000032', NULL, 'English', 'Journal of Community Health Interventions Press'),
(NULL, 2000070, 68, 'Effectiveness of an integrative exercise and health education program for metabolic syndrome: protocol for a randomized comparative trial in a Latin American community', 'Ulla Nakamura//Valentina Nakamura//Declan Santos', 'International Journal of Sleep and Behavior Research', 2017, 'Metabolic syndrome represents a significant public health challenge throughout Latin America, yet evidence-based community interventions remain underutilized in clinical practice. This protocol describes an 18-week structured program designed to improve cardiometabolic health through supervised aerobic activity, evidence-based nutrition and lifestyle education, and regular clinical monitoring. A single-center randomized design will enroll approximately 80 adults with confirmed metabolic syndrome from community health centers. Participants will be randomly allocated to either the integrated exercise-and-education program or standard care. The intervention comprises three supervised aerobic sessions weekly, monthly group health-education workshops, and biweekly clinical assessments including weight and metabolic measures. Primary outcomes examine changes in cardiorespiratory fitness, body composition measures, and metabolic markers including lipids and glucose. Secondary assessments will measure functional capacity, self-reported health status, and adherence rates. Data collection occurs at baseline and 18-week completion. This pragmatic protocol outlines a scalable community model for metabolic syndrome management in resource-limited settings.', '2017-09-15 09:00:00', '2026-08-11 00:00:00', 1, '1', 'Randomized parallel-group trial with community-based intervention', '10.5555/medidex.synthetic.0070', 'SYNTH-NCT0000033', NULL, 'English', 'International Journal of Sleep and Behavior Research Press'),
(NULL, 2000071, 69, 'Community-centered approach to reversing metabolic syndrome: 18-week results of an integrated program combining exercise, education, and clinical support', 'Ulla Nakamura//Valentina Nakamura//Declan Santos', 'Journal of Cardiometabolic Research', 2017, 'Community-based structured programs may effectively address metabolic syndrome, though Latin American evidence remains limited. We evaluated an 18-week integrated program combining three weekly supervised aerobic sessions, monthly health-education workshops, and biweekly clinical monitoring in 80 adults with metabolic syndrome. Participants were randomly assigned (intervention n=33, control n=47) and groups were balanced at baseline. Intervention participants attended supervised sessions and educational activities regularly; controls received customary care. Primary outcomes measured changes in fitness capacity, body measurements, fasting glucose, lipid panel, and blood pressure. The intervention group demonstrated greater gains in fitness capacity, reductions in waist circumference and body weight, lower fasting glucose and triglycerides, improved blood pressure, and favorable shifts in cholesterol fractions. Within the intervention group, significant improvements in fitness, weight loss, fat mass reduction, and lean muscle gain were evident. These results demonstrate that an integrated, accessible community program can produce meaningful improvements across multiple cardiometabolic domains in adults with metabolic syndrome.', '2017-08-15 09:00:00', '2026-05-15 00:00:00', 2, '1', 'Randomized parallel-group comparison trial', '10.5555/medidex.synthetic.0071', 'SYNTH-NCT0000033', NULL, 'English', 'Journal of Cardiometabolic Research Press'),
(NULL, 2000072, 70, 'Retraction: Community-centered approach to reversing metabolic syndrome', 'Ulla Nakamura//Valentina Nakamura//Declan Santos', 'Journal of Cardiometabolic Research', 2018, 'Following publication, the authors reported data integrity concerns including duplicated demographic entries for three control-group participants in the baseline characteristics table. A corrected analysis with deduplicated records yielded substantively identical conclusions regarding program effectiveness and participant safety. The study''s core findings remain scientifically valid; however, the journal requested retraction to maintain publication standards.', '2018-06-17 09:00:00', '2026-05-06 00:00:00', 6, '1', 'Randomized comparative trial', '10.5555/medidex.synthetic.0072', 'SYNTH-NCT0000033', NULL, 'English', 'Journal of Cardiometabolic Research Press'),
(NULL, 2000073, 71, 'Intensive nurse-administered disease management versus routine care in inflammatory bowel disease: randomized trial of patient-centered outcomes', 'Rasmus Underwood//Omar Eriksson//Rasmus Ostrowski//Declan Eriksson', 'Journal of Translational Patient Care', 2016, 'Specialist nursing coordination plays a vital role in IBD management, yet rigorous evidence on intensive nurse-led models remains limited. This randomized trial compared two care approaches in 98 patients with IBD newly commencing advanced immunosuppressive therapies. Participants were randomly assigned (intensive arm n=50, control arm n=48) to either weekly nurse contact including scheduled telephone check-ins and in-person clinic visits, or standard care involving baseline education only. The primary outcome was change in an integrated disease-burden assessment score at 12 weeks. Both groups showed improvement in disease-burden measures; however, the intensive-contact arm demonstrated significantly greater score reductions. At 12 weeks, substantially more intensive-contact participants achieved clinically meaningful treatment response. By 52-week follow-up, the intensive-contact group maintained superior disease-control trajectories and higher rates of disease remission. Adverse event profiles were comparable between arms. Results support intensive nurse-led management for improving disease trajectories and outcomes in patients initiating advanced IBD therapies.', '2016-04-28 09:00:00', '2026-08-03 00:00:00', 2, '1', 'Randomized parallel-group trial with 1:1 allocation', '10.5555/medidex.synthetic.0073', NULL, NULL, 'English', 'Journal of Translational Patient Care Press'),
(NULL, 2000074, 72, 'Long-term functional and psychological impacts of structured nursing support in inflammatory bowel disease: secondary outcomes and subgroup analysis from a randomized controlled trial', 'Rasmus Underwood//Omar Eriksson//Rasmus Ostrowski//Declan Eriksson', 'Oncology Supportive Care Journal', 2017, 'While primary disease-control metrics are important, patient-reported functional status, mental health, and treatment satisfaction define comprehensive IBD management success. We report secondary analyses from a 52-week randomized trial of 98 IBD patients allocated to intensive nursing support (n=50) or standard management (n=48). Secondary measures evaluated sustained remission rates, durability of treatment response, patient satisfaction with care coordination, functional limitations in work and daily activities, and psychological well-being scores. By 52-week follow-up, a substantially higher proportion of intensive-contact participants achieved and sustained disease remission. Patients receiving intensive nursing support reported greater satisfaction with their care experience and reported fewer activity limitations affecting employment and leisure. Subgroup analyses suggested consistent benefits across disease phenotypes and baseline disease severity. Qualitative exit interviews highlighted structured accountability and regular provider contact as key satisfaction drivers. These secondary findings extend primary-outcome data, demonstrating that systematic nursing engagement produces benefits beyond immediate disease control to encompass functional and psychological dimensions of patient health.', '2017-03-08 09:00:00', '2026-03-12 00:00:00', 4, '1', 'Randomized trial secondary and subgroup analysis', '10.5555/medidex.synthetic.0074', 'SYNTH-NCT0000034', NULL, 'English', 'Oncology Supportive Care Journal Press'),
(NULL, 2000075, 73, 'Retraction: Intensive nurse-administered disease management versus routine care in inflammatory bowel disease', 'Rasmus Underwood//Omar Eriksson//Rasmus Ostrowski//Declan Eriksson', 'Journal of Translational Patient Care', 2018, 'The authors have requested retraction due to identified irregularities in randomization sequence documentation at the trial recruitment center. Upon detailed review, the integrity of allocation concealment cannot be definitively confirmed. While primary outcome trends remained directionally consistent during data verification, the authors determined that withdrawal was necessary to uphold scientific rigor and publication integrity standards.', '2018-09-10 09:00:00', '2026-08-06 00:00:00', 6, '1', 'Randomized controlled trial', '10.5555/medidex.synthetic.0075', 'SYNTH-NCT0000034', NULL, 'English', 'Journal of Translational Patient Care Press'),
(NULL, 2000076, 74, 'Randomized trial of a novel Staphylococcus-targeting endolysin topical therapy in mild-to-moderate atopic dermatitis: evaluation of microbial reduction and clinical efficacy', 'Esteban Ostrowski//Giulia Yilmaz//Xavier Yilmaz', 'Journal of Infectious Disease Interventions', 2019, 'Staphylococcal aureus overgrowth and altered skin microbiota contribute significantly to atopic dermatitis pathophysiology. Targeted antimicrobial approaches may offer therapeutic benefit. A double-blind, vehicle-controlled randomized trial evaluated a novel endolysin-based topical therapy in 53 patients with mild-to-moderate atopic dermatitis, stratified by baseline bacterial colonization status (n=26-27 per arm). Participants applied their assigned formulation twice daily for two weeks. Safety monitoring, tolerability assessment, and microbiological outcomes including bacterial recovery and microbiota composition were measured. Clinical severity scores and patient-reported symptom measures were evaluated at baseline and after two weeks. The endolysin preparation demonstrated an excellent safety and tolerability profile with no serious adverse events recorded. However, bacterial reduction did not achieve statistical significance compared to vehicle control. Similarly, clinical disease severity scores and patient-reported symptom scores showed no significant between-group differences after two weeks of treatment. Skin microbiome diversity measures remained largely unchanged. While the investigational endolysin agent demonstrated acceptable safety, short-term topical application was insufficient to produce measurable clinical or microbiological benefit in this population.', '2019-07-24 09:00:00', '2026-08-10 00:00:00', 2, '1', 'Double-blind parallel-group vehicle-controlled trial', '10.5555/medidex.synthetic.0076', NULL, NULL, 'English', 'Journal of Infectious Disease Interventions Press'),
(NULL, 2000077, 75, 'Glucose-lowering effects of acute cold-induced thermogenesis in individuals with type 2 diabetes but not prediabetes: a randomized crossover trial', 'Dovile Yilmaz//Kavya Eriksson//Benedikt Girard//Ingrid Quraishi', 'Journal of Infectious Disease Interventions', 2022, 'Cold-induced metabolic activation could theoretically enhance glucose clearance, though effects in glucose-dysregulated populations remain unexplored. In a randomized crossover design, 24 participants (12 with prediabetes, 12 with established type 2 diabetes), aged 40-75, underwent two controlled cold-exposure sessions using individualized temperature protocols. Sessions were randomly ordered and participants were blinded to exposure intensity. Continuous glucose monitoring tracked interstitial glucose levels over 24-hour periods before and after each exposure. Shivering intensity and resting metabolic rate increases were confirmed via physiological measurement. In prediabetic participants, neither cold-exposure protocol altered 24-hour glucose patterns. Conversely, in type 2 diabetes participants, mild cold exposure (but not the more intense protocol) produced a small yet statistically significant reduction in mean 24-hour glucose levels and fasting glucose values, accompanied by increased time spent within optimal glucose ranges. These metabolic improvements did not correlate with acute energy expenditure during cold exposure, suggesting effects were dependent on baseline metabolic dysfunction rather than sheer caloric mobilization. Findings suggest cold-induced thermogenesis may modulate glucose handling specifically in advanced diabetes, with potential implications for adjunctive non-pharmacological diabetes management strategies.', '2022-09-28 09:00:00', '2026-07-12 00:00:00', 2, '1', 'Randomized crossover trial with continuous glucose monitoring', '10.5555/medidex.synthetic.0077', 'SYNTH-NCT0000036', NULL, 'English', 'Journal of Infectious Disease Interventions Press'),
(NULL, 2000078, 76, 'Cluster-randomized trial of structured breastfeeding support to promote lactation continuation and reduce socioeconomic disparities: a mixed-methods study protocol from Scandinavia', 'Chidi Eriksson//Ximena Dahl//Viktor Eriksson', 'Annals of Rehabilitation Science', 2018, 'Breastfeeding is foundational for child health outcomes, yet rates remain suboptimal and unequally distributed across educational and socioeconomic backgrounds in high-income Nordic countries. This protocol describes a cluster-randomized trial evaluating an evidence-based breastfeeding support program designed to extend exclusive breastfeeding duration and mitigate educational and economic disparities in lactation outcomes. The trial enrolls 21 municipal healthcare clusters across two Danish regions, implementing a coordinated intervention combining intensive health-visitor training, standardized family support protocols, accessible resource toolkits, and structured follow-up mechanisms over an 18-month intervention period. Primary effectiveness outcomes measure exclusive breastfeeding continuation rates and socioeconomic-stratified disparities. Secondary assessments include program fidelity audits, contextual barriers to implementation, health-visitor confidence measures, and family experiences captured through qualitative inquiry. This protocol outlines a pragmatic evaluation of scalable system-level breastfeeding promotion within existing primary healthcare infrastructure.', '2018-12-14 09:00:00', '2026-03-28 00:00:00', 1, '1', 'Cluster-randomized parallel-group effectiveness trial', '10.5555/medidex.synthetic.0078', NULL, NULL, 'English', 'Annals of Rehabilitation Science Press'),
(NULL, 2000079, 77, 'Structured professional breastfeeding support reduces cessation and inequality: results from a cluster-randomized Danish implementation trial', 'Chidi Eriksson//Ximena Dahl//Viktor Eriksson', 'Clinical Nutrition Trials Journal', 2018, 'Though breastfeeding benefits are well-established, real-world support systems often fail to sustain lactation, particularly in economically disadvantaged populations. We implemented a coordinated, evidence-based breastfeeding-support initiative across 21 healthcare municipalities and evaluated its impact on lactation persistence and socioeconomic-related disparities. Health visitors and families in intervention clusters (n=11) received comprehensive training, standardized evidence-based protocols, family resource toolkits, and structured follow-up contacts; control clusters (n=10) continued customary support practices. Over 600 families and their health visitors completed structured assessments; implementation fidelity and quality were audited. In intervention areas, significantly more families maintained exclusive breastfeeding through six months postpartum. Importantly, socioeconomic-related disparities in breastfeeding cessation were substantially narrowed in intervention clusters while persisting in control regions. Health visitors in intervention clusters reported improved professional confidence and perceived the structured approach as fitting well within existing workflow. Qualitative interviews revealed minimal concerns about stigma despite intensive support targeting. These findings demonstrate that system-level professional breastfeeding support delivered through existing primary-care infrastructure can sustain lactation persistence and narrow equity gaps.', '2018-02-02 09:00:00', '2026-06-08 00:00:00', 2, '1', 'Cluster-randomized parallel-group implementation trial', '10.5555/medidex.synthetic.0079', 'SYNTH-NCT0000037', NULL, 'English', 'Clinical Nutrition Trials Journal Press'),
(NULL, 2000080, 78, 'Accessibility and effectiveness of hepatitis C treatment integrated at harm-reduction facilities: protocol for a randomized trial in people who inject drugs', 'Rasmus Santos//Lena Papadopoulos//Giulia Castellano//Omar Ivanova//Benedikt Wachira', 'Journal of Community Health Interventions', 2021, 'People who inject drugs (PWID) experience disproportionate hepatitis C burden but encounter substantial barriers to accessing curative treatment, including fragmented healthcare systems, geographic distance, and stigma. This protocol describes a randomized trial evaluating an accessible care model wherein hepatitis C screening, treatment initiation, and clinical support are delivered directly on-site at harm-reduction facilities, compared with standard referral-based pathways. An estimated 165 HCV RNA-positive PWID reporting injection drug use within the prior 90 days will be randomized 1:1 to accessible on-site care or standard referral. Primary outcome measures assess treatment-related changes in injection frequency, injection-related risk behaviors, and uptake of opioid-use-disorder treatment during 12 months of follow-up. Secondary outcomes examine hepatitis C treatment initiation and completion rates. This pragmatic design tests whether eliminating geographic, administrative, and stigma-related barriers to hepatitis C care influences both health-related behaviors and disease treatment engagement in an underserved population.', '2021-10-07 09:00:00', '2026-02-17 00:00:00', 1, '1', 'Randomized parallel-group pragmatic effectiveness trial', '10.5555/medidex.synthetic.0080', NULL, NULL, 'English', 'Journal of Community Health Interventions Press'),
(NULL, 2000081, 79, 'On-site hepatitis C care reduces injection drug use and related risk in people who inject drugs: findings from an accessible care model trial', 'Rasmus Santos//Lena Papadopoulos//Giulia Castellano//Omar Ivanova//Benedikt Wachira', 'Journal of Geriatric and Aging Research', 2022, 'Structural barriers significantly limit hepatitis C treatment access among people who inject drugs, yet evidence on innovative care-delivery models remains limited. A randomized 1:1 assignment trial enrolled 165 HCV RNA-positive individuals with recent injection drug use and randomized participants to either on-site hepatitis C care (n=82) delivered directly at a harm-reduction program, or standard referral pathways (n=83). The on-site care model provided clinical assessment, treatment initiation, psychosocial support, and medication management without requiring external facility referral. Participants attended structured follow-up interviews at 3, 6, 9, and 12 months, with standardized assessments of injection patterns, high-risk injection practices, and medication-assisted treatment engagement. By 12-month follow-up, on-site care participants reported statistically significantly greater reductions in injection drug use frequency compared with standard-referral participants. High-risk injection behaviors also declined more substantially in the accessible-care arm. Rates of opioid-use-disorder treatment engagement appeared similar between study arms. These findings demonstrate that removing structural and administrative barriers to hepatitis C care can meaningfully reduce injection-related behaviors and may amplify public-health impact in affected populations.', '2022-01-26 09:00:00', '2026-04-05 00:00:00', 2, '1', 'Randomized parallel-group pragmatic trial', '10.5555/medidex.synthetic.0081', NULL, NULL, 'English', 'Journal of Geriatric and Aging Research Press'),
(NULL, 2000082, 80, 'Comparative effectiveness of digital smoking-cessation coaching with varying levels of synchronous therapeutic support: protocol for a three-arm randomized controlled trial', 'Dovile Dahl//Ximena Farrell//Viktor Dahl', 'International Journal of Sleep and Behavior Research', 2023, 'Mobile-application-based smoking cessation interventions are increasingly deployed in clinical practice, yet evidence regarding optimal implementation—particularly whether augmenting app-based self-guided modules with human therapeutic contact enhances cessation outcomes—remains limited. This protocol describes a three-arm randomized trial enrolling 420 adults (140 participants per arm) actively seeking smoking cessation support. Participants will use a cognitive-behavioral mobile application over eight weeks, randomly assigned to: (1) autonomous app-only self-guided use; (2) app paired with eight weekly group-based cognitive-behavioral therapy sessions delivered via secure videoconference; or (3) app paired with four biweekly group cognitive-behavioral sessions via videoconference. Primary outcome is validated smoking abstinence (exhaled carbon monoxide ≤6 ppm) measured at end-of-treatment. Secondary outcomes assess sustained abstinence through 12 months post-treatment, quit-attempt patterns, treatment satisfaction, and healthcare utilization. This trial will determine whether supplementing digital cessation tools with graduated human therapeutic engagement improves smoking abstinence outcomes and will guide optimization of remote smoking-cessation service delivery.', '2023-09-07 09:00:00', '2026-02-05 00:00:00', 1, '1', 'Randomized parallel-group three-arm trial', '10.5555/medidex.synthetic.0082', 'SYNTH-NCT0000039', NULL, 'English', 'International Journal of Sleep and Behavior Research Press'),
(NULL, 2000083, 81, 'Adding synchronous therapeutic contact to a smoking-cessation app: results of a randomized effectiveness trial comparing app-only versus app-plus-cognitive-behavioral-support models', 'Dovile Dahl//Ximena Farrell//Viktor Dahl', 'Journal of Women''s Health Trials', 2023, 'Remotely-delivered smoking cessation interventions expand access to evidence-based treatment, but the incremental value of human therapeutic engagement over autonomous app-based self-management remains uncertain. A randomized three-arm trial enrolled 420 adults (mean age ~48 years) actively seeking smoking abstinence support. Participants were randomly assigned to eight weeks of: (1) app-only self-guided use (n=140); (2) app combined with eight weekly group cognitive-behavioral therapy sessions via secure video (n=140); or (3) app combined with four biweekly group sessions (n=140). Primary outcome was carbon-monoxide-validated 7-day point-prevalence smoking abstinence at week eight. The app-only group achieved 18% validated abstinence at treatment completion. The high-intensity contact arm (eight weekly sessions) achieved 36% validated abstinence, while the low-intensity arm (four biweekly sessions) achieved 28% abstinence. Both therapeutic-contact arms significantly outperformed the app-only condition. At 12-month follow-up, the high-intensity group maintained substantially higher rates of sustained abstinence compared with other study arms. These findings demonstrate that supplementing digital smoking-cessation tools with regular human therapeutic guidance substantially improves both short-term and long-term abstinence rates.', '2023-03-08 09:00:00', '2026-07-01 00:00:00', 2, '1', 'Randomized three-arm parallel-group trial', '10.5555/medidex.synthetic.0083', NULL, NULL, 'English', 'Journal of Women''s Health Trials Press'),
(NULL, 2000084, 82, 'Mechanisms and moderators of smartphone-based cessation with varying therapeutic intensity: subgroup and longitudinal analyses from a randomized smoking intervention trial', 'Dovile Dahl//Ximena Farrell//Viktor Dahl', 'Annals of Rehabilitation Science', 2024, 'Understanding which smokers benefit most from intensive therapeutic contact versus self-guided app-based approaches could enable more personalized cessation interventions. Secondary analyses examined 420 trial participants randomized to app-only, app-plus-high-intensity-support (eight weekly sessions), or app-plus-low-intensity-support (four biweekly sessions). We conducted pre-specified subgroup analyses stratified by baseline motivation, cigarettes-per-day, number of prior-quit attempts, age, and baseline mental-health status. High-intensity therapeutic contact demonstrated consistent benefit across most demographic and clinical subgroups, with notably larger absolute effect sizes in heavy smokers and those with multiple prior-quit attempts. App-only participants with high baseline motivation achieved cessation rates approximating those of low-intensity-supported participants. Engagement metrics revealed that app-usage frequency correlated with abstinence success in all arms but was highest among participants in therapeutic-contact conditions. Qualitative exit interviews identified social accountability and structured therapeutic check-ins as key perceived mechanisms of benefit. These secondary findings suggest selective intensification of therapeutic contact for specific populations could optimize resource allocation in scaled smoking-cessation programs.', '2024-08-09 09:00:00', '2026-07-07 00:00:00', 4, '1', 'Randomized trial secondary and subgroup analysis', '10.5555/medidex.synthetic.0084', NULL, NULL, 'English', 'Annals of Rehabilitation Science Press'),
(NULL, 2000085, 83, 'Corrigendum to: Adding synchronous therapeutic contact to a smoking-cessation app', 'Dovile Dahl//Ximena Farrell//Viktor Dahl', 'Journal of Women''s Health Trials', 2025, 'The authors report a labeling error in Table 2 presenting baseline demographic characteristics. The ''high-intensity group'' age column was mislabeled; corrected data indicate mean age 47.8 years (not 52.1 as originally printed). This typographical correction does not affect primary outcome analyses or substantive treatment conclusions. All primary and secondary efficacy results remain unchanged.', '2025-01-28 09:00:00', '2026-07-18 00:00:00', 5, '1', 'Randomized trial', '10.5555/medidex.synthetic.0085', 'SYNTH-NCT0000039', NULL, 'English', 'Journal of Women''s Health Trials Press'),
(NULL, 2000086, 84, 'Patient comprehension and preferences for prostate cancer polygenic risk communication: findings from qualitative evaluation of prototype reporting materials', 'Kavya Bergstrom//Kavya Zeleny//Giulia Dubois//Oleksandr Zimmermann//Jana Gomulka', 'Journal of Musculoskeletal Trials', 2019, 'As polygenic risk scores increasingly enter clinical prostate-cancer screening workflows, effective communication of complex genetic risk information becomes critical for informed decision-making. We conducted semi-structured qualitative interviews with eight men nationally representative of prostate-cancer-screening-eligible populations to evaluate comprehension, perceived usefulness, and visual-design preferences for prototype polygenic-risk summary materials and accompanying educational resources. Participants reviewed draft communication materials combining narrative text, numerical risk estimates, and graphical representations (pictograph arrays, probability curves, risk tables). Interviews explored interpretation accuracy, emotional responses, design-element preferences, and perceived actionability of the materials. Participants generally understood core risk-communication concepts and found simple graphical displays—particularly pictograph risk arrays—more intuitively interpretable than complex probability curves or bell-curve distributions. Color coding and visual hierarchy effectively directed attention to salient information. Several participants expressed ambiguity about recommended next steps despite clear written guidance. Participants valued supplementary resources such as embedded hyperlinks and decision-support frameworks. Design modifications addressing font size and information density were suggested. These pilot findings provide practical design guidance for communicating polygenic information as PRS-informed prostate-cancer screening moves toward clinical implementation.', '2019-02-14 09:00:00', '2026-05-04 00:00:00', 2, '1', 'Qualitative pilot evaluation', '10.5555/medidex.synthetic.0086', 'SYNTH-ISRCTN-0000040', NULL, 'English', 'Journal of Musculoskeletal Trials Press'),
(NULL, 2000087, 85, 'Psychosocial responses and engagement intentions following prostate cancer polygenic risk disclosure: secondary qualitative findings and design recommendations for clinical implementation', 'Kavya Bergstrom//Kavya Zeleny//Giulia Dubois//Oleksandr Zimmermann//Jana Gomulka', 'Pediatric Clinical Trials Journal', 2020, 'Beyond cognitive comprehension, patient-centered risk communication must account for psychological and behavioral responses and decision-making intentions. Secondary analysis of qualitative interviews examined emotional reactions to prostate-cancer polygenic-risk disclosures, intentions to pursue screening based on disclosed risk level, and participants'' perceived autonomy in clinical decision-making. Participants reported primarily neutral-to-positive emotional responses to risk disclosure; notably, no participant expressed anxiety, distress, or negative psychological impact from learning their polygenic risk status. Hypothetical risk-disclosure context (moderate versus high polygenic-risk scenarios) meaningfully influenced perceived screening relevance and stated screening intentions. Participants with higher-risk scenarios endorsed stronger intentions to pursue screening. Most participants explicitly valued having autonomous decision-making authority and declined preference for directive clinical guidance. Supplementary design features—interactive risk calculators, hyperlinks to specialist consultations, downloadable summary documents—were valued as enhancing usability and facilitating secondary conversations with family or primary-care clinicians. Several participants noted that portable or shareable document formats would support productive clinical discussions. These secondary insights suggest that thoughtfully-designed risk-communication materials can convey polygenic information while preserving patient autonomy and minimizing psychological burden, supporting responsible clinical implementation.', '2020-09-08 09:00:00', '2026-07-04 00:00:00', 4, '1', 'Qualitative pilot study secondary analysis', '10.5555/medidex.synthetic.0087', NULL, NULL, 'English', 'Pediatric Clinical Trials Journal Press'),
(NULL, 2000088, 86, 'Designing an Enhanced Recovery After Surgery-informed nutritional support strategy for intensive care: protocol for a randomized comparative effectiveness study', 'Amara Quraishi//Elena Rousseau//Sofia Xu', 'Clinical Outcomes Research Review', 2018, 'Objective: To develop and evaluate a systematic approach to nutritional management in critically ill patients drawing on principles from the Enhanced Recovery After Surgery (ERAS) framework. Methods: This randomized comparative effectiveness trial will enroll 100 critically ill patients from intensive care units. Participants will be assigned to receive either the ERAS-informed nutrition protocol or conventional nutritional management. The ERAS-informed approach incorporates optimized nutrient delivery schedules, systematic assessment of gastrointestinal function, and evidence-based monitoring of nutritional indices. Primary endpoints include total caloric and protein delivery within the first week of care. Secondary endpoints encompass laboratory markers of nutritional status, gastrointestinal complications, and length of intensive care stay. Blinding is not feasible given the nature of nutritional interventions. This study addresses the gap in systematic implementation of recovery-focused nutrition in the ICU setting.', '2018-06-09 09:00:00', '2026-06-16 00:00:00', 1, '1', 'Parallel-group, open-label randomized controlled trial', '10.5555/medidex.synthetic.0088', NULL, NULL, 'English', 'Clinical Outcomes Research Review Press'),
(NULL, 2000089, 87, 'Nutritional outcomes and gastrointestinal tolerance following a systematic ERAS-derived feeding protocol in ICU patients', 'Amara Quraishi//Elena Rousseau//Sofia Xu', 'Annals of Rehabilitation Science', 2018, 'Background: Implementation of systematic, recovery-focused nutritional protocols in intensive care may improve nutritional adequacy while reducing complications. Methods: 100 critically ill patients were randomly assigned to receive either a structured ERAS-derived nutrition protocol or standard ICU nutritional support. Outcomes including daily macronutrient intake, hemoglobin and serum albumin levels, rates of gastrointestinal adverse events, and days spent in intensive care were measured. Results: The protocol-guided intervention group achieved significantly higher mean daily caloric intake [1089 ± 246 kJ/d vs 891 ± 198 kJ/d; p < 0.05] and protein delivery [105.2 ± 14.1 g/d vs 98.4 ± 11.8 g/d; p < 0.05]. Hemoglobin (119.3 ± 7.2 g/L vs 108.1 ± 6.8 g/L) and albumin levels (46.1 ± 3.4 g/L vs 42.3 ± 3.9 g/L) were significantly higher in the protocol group (p < 0.05). Gastrointestinal complications were reduced in the intervention group: retention 19.0% vs 39.0%, diarrhea 11.0% vs 23.0%, abdominal discomfort 13.0% vs 31.0%, and bleeding 5.0% vs 11.0%. Intensive care duration was shortened in the protocol group [9.4 ± 3.6 days vs 12.1 ± 4.2 days; p < 0.05]. Conclusions: Structured ERAS-informed nutrition protocols improve nutrient delivery and gastrointestinal outcomes in critically ill patients.', '2018-12-06 09:00:00', '2026-08-18 00:00:00', 2, '1', 'Parallel-group, open-label randomized controlled trial', '10.5555/medidex.synthetic.0089', 'SYNTH-ISRCTN-0000041', NULL, 'English', 'Annals of Rehabilitation Science Press'),
(NULL, 2000090, 88, 'Temporal restriction of feeding windows as a dietary intervention in metabolic syndrome: rationale and design of a randomized controlled feeding trial', 'Viktor Eriksson//Noor Zeleny//Farah Nakamura', 'Pediatric Clinical Trials Journal', 2023, 'Rationale: Structured dietary interventions addressing meal timing may influence appetite signaling and cardiometabolic risk factors. This study compares the effects of time-restricted versus conventional eating patterns on metabolic and behavioral measures. Methods: A 12-week randomized feeding trial will enroll 40 overweight/obese adults aged 50-70 with prediabetes or treated type 2 diabetes. One group will follow a 10-hour eating window; the control group will eat during a standard 16-hour window. Both groups receive nutritionally equivalent calories. Assessments will include three-factor eating behavior questionnaire responses, fasting hormonal markers (leptin, adiponectin), inflammatory markers (C-reactive protein), and cortisol. Oral glucose tolerance testing and ghrelin measurement will be performed. Statistical comparisons will use non-parametric tests for within- and between-group differences. The trial will examine whether meal timing, independent of calorie reduction, influences appetite physiology and eating patterns.', '2023-04-15 09:00:00', '2026-05-09 00:00:00', 1, '1', 'Randomized isocaloric controlled feeding trial', '10.5555/medidex.synthetic.0090', NULL, NULL, 'English', 'Pediatric Clinical Trials Journal Press'),
(NULL, 2000091, 89, 'Behavioral and hormonal responses to time-restricted versus conventional meal timing in adults with obesity and glucose dysregulation', 'Viktor Eriksson//Noor Zeleny//Farah Nakamura', 'Journal of Infectious Disease Interventions', 2023, 'Background: Whether restricting eating to specific hours influences appetite hormones and eating behavior patterns is not well established. Methods: 39 overweight/obese adults (mean age 59 years, BMI 35.4) with prediabetes were randomized to 10-hour restricted eating (n=19) or 16-hour conventional pattern (n=20) for 12 weeks with equal caloric intake. Eating behaviors were assessed by questionnaire; fasting leptin, adiponectin, C-reactive protein, cortisol, and postload ghrelin were measured. Results: Weight loss was comparable between groups (2.6% restricted vs 2.4% conventional). Both arms showed increased dietary restraint and decreased disinhibition and hunger sensation scores. No significant between-group differences emerged for appetite hormones or inflammatory markers despite mean reductions in leptin, adiponectin changes, and C-reactive protein. Interpretation: Modest weight loss occurred in both conditions, with both groups demonstrating improvements in eating behavior scores. However, significant differential effects on appetite regulation or inflammation were not detected. Further investigation in larger populations is needed.', '2023-05-26 09:00:00', '2026-06-02 00:00:00', 2, '1', 'Randomized parallel-assignment controlled feeding trial', '10.5555/medidex.synthetic.0091', 'SYNTH-NCT0000042', NULL, 'English', 'Journal of Infectious Disease Interventions Press'),
(NULL, 2000092, 90, 'Effects of humor-based aerobic activity on psychological distress and physical function in lung cancer patients undergoing chemotherapy: protocol for a single-blinded parallel-group trial', 'Sami Yamada//Kavya Esposito//Felix Zimmermann//Gemma Tremblay', 'International Journal of Behavioral Medicine Practice', 2015, 'Background: Patients with advanced lung cancer experience substantial psychological burden and physical deconditioning during chemotherapy. Novel, accessible interventions combining exercise with positive psychological engagement may reduce distress and improve functional outcomes. Methods: This single-blind, parallel-group randomized trial will randomize 84 lung cancer patients undergoing active chemotherapy to an intervention group receiving structured humor-based movement sessions or a control group receiving standard oncology care. The intervention group will participate in specialized sessions combining rhythmic movement and laughter-inducing activities twice weekly. Primary outcomes include measured psychological distress using validated stress scales and psychological resource assessment. Secondary outcomes include exercise capacity testing and walking tolerance. Measurement points are baseline and immediately following the intervention period. Block randomization will be employed with concealment of allocation from assessors.', '2015-04-04 09:00:00', '2026-06-08 00:00:00', 1, '1', 'Single-blind parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0092', NULL, NULL, 'English', 'International Journal of Behavioral Medicine Practice Press'),
(NULL, 2000093, 91, 'Impact of laughter-based physical activity on stress perception and exercise capacity in chemotherapy-treated lung cancer patients', 'Sami Yamada//Kavya Esposito//Felix Zimmermann//Gemma Tremblay', 'Journal of Endocrine and Metabolic Trials', 2016, 'Background: Psychosocial stress and functional decline commonly affect lung cancer patients during chemotherapy. Methods: 84 lung cancer patients undergoing active chemotherapy were randomly assigned to a laughter-based exercise intervention (n=42) or routine care (n=40). The intervention involved structured sessions combining movement and laughter practices. Perceived stress, positive psychological resources, and exercise capacity were measured at baseline and post-intervention. Results: 80 patients (40 per group) completed the study. Patients in the laughter-based intervention demonstrated significantly higher positive psychological resources scores compared to routine care (Cohen''s d=0.71; p<0.05), increased exercise tolerance (d=0.64; p<0.05), and notably lower perceived stress ratings (d=1.09; p<0.05). Within-group improvements in stress occurred in both arms, but between-group differences favored the intervention. Conclusions: Laughter-based aerobic activities appear effective in reducing stress perception and enhancing exercise tolerance in chemotherapy patients, suggesting potential adjunctive value for improving psychological well-being during active cancer treatment.', '2016-05-06 09:00:00', '2026-04-17 00:00:00', 2, '1', 'Single-blind parallel-group randomized trial', '10.5555/medidex.synthetic.0093', NULL, NULL, 'English', 'Journal of Endocrine and Metabolic Trials Press'),
(NULL, 2000094, 92, 'Impact of structured palliative care education on end-of-life symptom recognition and management in nursing home populations', 'Oleksandr Castellano//Jana Quraishi//Umberto Ricci//Priya Schmidt', 'Journal of Chronic Disease Management', 2016, 'Background: End-of-life care quality in residential facilities varies, partly due to variable recognition of palliative needs. This cluster-randomized study evaluated whether staff training in palliative care principles improves symptom identification and management at end of life. Methods: Ten nursing homes (5 intervention, 5 control) participated. Intervention sites provided staff with a 40-hour palliative care qualification course. Primary outcomes included documentation of palliative symptoms and corresponding interventions in resident records during the final three months of life. Data were extracted from medical records of 119 deceased residents (42 intervention, 77 control). Results: Specialized palliative consultation was documented for 19.0% of intervention residents versus 9.1% of control residents. Pain documentation rates were 57.1% versus 49.4% respectively. Of documented pain events, appropriate management was recorded in 73.6% of intervention cases versus 61.9% of control cases, with intervention residents showing significantly higher likelihood of receiving documented pain intervention (odds ratio 1.80; p<0.05). Conclusions: Staff training in palliative principles improves end-of-life care quality through better symptom recognition and appropriate management documentation in nursing home settings.', '2016-11-28 09:00:00', '2026-05-09 00:00:00', 2, '1', 'Cluster-randomized intervention study with nested analysis', '10.5555/medidex.synthetic.0094', NULL, NULL, 'English', 'Journal of Chronic Disease Management Press'),
(NULL, 2000095, 93, 'Safety, tolerability, and preliminary efficacy of biomechanical foot interventions in individuals with knee osteoarthritis and foot pain: a pilot randomized feasibility study', 'Mateus Castellano//Camille Weber//Franz Nakamura//Ingrid Johansen//Tariq Jansen', 'International Trials Register Quarterly', 2018, 'Background: Biomechanical interventions targeting the lower extremity can reduce knee joint loading; however, effects on concurrent foot symptoms are unclear. This pilot feasibility study examined angled foot inserts with and without arch support in patients with both knee osteoarthritis and foot pain. Methods: 30 adults with radiographically-confirmed knee osteoarthritis and foot pain were randomized to receive either 6-degree angled inserts alone (n=15) or angled inserts integrated with contoured foot and arch support (n=15) for 12 weeks. Feasibility measures included recruitment/retention rates, daily wear compliance, comfort ratings, and adverse event frequencies. Clinical measures included foot function indices, knee symptoms questionnaires, and motion capture analysis of lower limb biomechanics. Results: All feasibility criteria were successfully met with no serious adverse events reported. Participants rated insert comfort as moderate (mean 7.0/10), and 83% of weeks met the target 30-minute daily wear threshold. Both groups showed consistent improvements in knee pain and function scores, knee adduction moment reduction, and ankle stability measures. No statistical comparisons were conducted due to pilot design. Conclusions: Both insert types appear safe and feasible in this population; larger confirmation studies are warranted.', '2018-10-12 09:00:00', '2026-04-26 00:00:00', 2, '1', 'Pilot parallel-group feasibility randomized controlled trial', '10.5555/medidex.synthetic.0095', NULL, NULL, 'English', 'International Trials Register Quarterly Press'),
(NULL, 2000096, 94, 'Vascular stiffness and inflammatory response to adjunctive low-dose anti-inflammatory therapy in hypertensive patients: results from the COHERENT trial', 'Rasmus Brennan//Declan Esposito//Tariq Ricci', 'Clinical Outcomes Research Review', 2019, 'Background: Inflammation and arterial stiffening are implicated in hypertension pathophysiology. This double-blind, placebo-controlled trial evaluated whether adjunctive low-dose anti-inflammatory therapy reduces vascular dysfunction in hypertensive patients. Methods: 150 hypertensive adults (mean age 64.5 years, mean systolic BP 140 mmHg) were randomized 1:1 to receive adjunctive 0.5 mg daily anti-inflammatory agent (n=75) or placebo (n=75) for six months, alongside standard blood pressure medications. Primary endpoint was change in carotid-femoral pulse wave velocity. Secondary endpoints included office and ambulatory blood pressure, echocardiographic parameters, and serum inflammatory and cardiac biomarkers. Results: At six months, the treatment group demonstrated numerically greater reduction in pulse wave velocity compared to placebo; however, statistical significance was not achieved (between-group difference -0.34 m/s, 95% CI -0.89 to 0.21). Blood pressure reduction was comparable between groups. Secondary analyses showed modest reductions in high-sensitivity C-reactive protein in the treatment arm. Left ventricular mass and other echocardiographic parameters did not differ significantly. Conclusions: In hypertensive patients without established cardiovascular disease, adjunctive low-dose anti-inflammatory therapy did not produce significant improvements in arterial stiffness or other measured cardiovascular parameters over six months.', '2019-06-28 09:00:00', '2026-02-10 00:00:00', 2, '1', 'Double-blind parallel-group placebo-controlled randomized trial', '10.5555/medidex.synthetic.0096', 'SYNTH-NCT0000046', NULL, 'English', 'Clinical Outcomes Research Review Press'),
(NULL, 2000097, 95, 'Individualized, risk-stratified screening intervals for diabetic retinopathy: design and rationale of a large-scale population equivalence trial', 'Franz Mensah//Jamal Castellano//Ximena Xu', 'Journal of Pharmacological Trials', 2015, 'Rationale: Annual screening for diabetic retinopathy imposes substantial resource burden, yet individualized risk assessment might optimize screening intervals while maintaining safety. This equivalence trial evaluates a risk-stratified, variable-interval screening approach versus standard annual screening. Methods: We will enroll 4500+ individuals with diabetes aged 12+ years from an established population-based screening program. Participants will be randomized 1:1 to receive either individualized screening intervals (6, 12, or 24 months based on baseline and dynamic risk factors) determined by a validated risk prediction algorithm, or annual screening (control). Screening intervals will be adjusted at each visit based on updated risk calculations incorporating demographic, clinical, and prior screening data. Primary outcome is first-visit attendance (safety measure). Secondary outcomes include detection rates of sight-threatening retinopathy, quality of life measures, and program costs. The study will employ a two-year minimum follow-up with observer masking of allocation. The equivalence margin for attendance is pre-specified.', '2015-01-11 09:00:00', '2026-08-01 00:00:00', 1, '1', 'Two-arm parallel equivalence randomized controlled trial', '10.5555/medidex.synthetic.0097', 'SYNTH-ISRCTN-0000047', NULL, 'English', 'Journal of Pharmacological Trials Press'),
(NULL, 2000098, 96, 'Non-inferior detection of advanced retinopathy with risk-based variable screening intervals: outcomes from a large-scale population equivalence study', 'Franz Mensah//Jamal Castellano//Ximena Xu', 'Clinical Nutrition Trials Journal', 2016, 'Background: Risk-stratified, variable screening intervals might reduce healthcare burden in diabetes care while maintaining safety for retinopathy detection. Methods: 4534 individuals with diabetes were randomized to individualized risk-based screening intervals (6, 12, or 24 months; n=2097) or annual screening (n=2224). Screening risk categories were determined by a validated algorithm at baseline and updated after each visit. Primary outcome was attendance at first follow-up; secondary outcomes were sight-threatening retinopathy detection rates, quality-adjusted life-years, and incremental costs. Results: First visit attendance rates were equivalent between groups (individualized 83.6% vs. annual 84.7%; difference -1.0%, 95% CI -3.2 to 1.2). Sight-threatening retinopathy detection showed non-inferiority in the individualized group (1.4% vs. 1.7%; difference -0.3%, 95% CI -1.1 to 0.5). No serious adverse events were reported. Quality-adjusted life-year differences did not significantly differ from zero. Individualized screening reduced total appointments by 43.2% and generated incremental cost savings of £17.34 per person (95% CI £17.02-£17.67) from healthcare perspective and £23.11 (95% CI £22.73-£23.53) from societal perspective, representing 21% overall cost reduction. Conclusions: Risk-stratified, individualized screening intervals can be safely and cost-effectively implemented in established diabetic retinopathy screening programs.', '2016-12-27 09:00:00', '2026-03-02 00:00:00', 2, '1', 'Two-arm parallel equivalence randomized controlled trial', '10.5555/medidex.synthetic.0098', 'SYNTH-ISRCTN-0000047', NULL, 'English', 'Clinical Nutrition Trials Journal Press'),
(NULL, 2000099, 97, 'Neurobiological mechanisms in psychological treatment of anxiety: protocol for a randomized trial examining neurotrophic factor changes during acceptance-based versus supportive psychotherapy', 'Jamal Haddad//Isabela Papadopoulos//Lukas Xu//Zofia Esposito', 'Pediatric Clinical Trials Journal', 2018, 'Background: Psychological interventions produce clinical improvement in anxiety disorders, but the underlying neurobiological mechanisms are incompletely understood. Neurotrophic factors regulate neural plasticity and may represent a biomarker of therapeutic response. Methods: This 14-week randomized trial will enroll 85 adults aged 18-65 with diagnosed generalized anxiety disorder. Participants will be randomized 1:1 to either group acceptance-based behavior therapy (ABBT) or supportive therapy (ST), each delivered across 10 sessions. Blood samples for plasma neurotrophic factor measurement will be collected at baseline and post-treatment. Clinical anxiety severity will be assessed using standardized rating scales. Participants will complete self-report measures of worry, anxiety symptoms, and functional impairment. Correlations between neurotrophic factor changes and clinical outcomes will be examined using Pearson correlation and linear regression analyses.', '2018-03-20 09:00:00', '2026-02-22 00:00:00', 1, '1', 'Parallel-group randomized psychotherapy trial', '10.5555/medidex.synthetic.0099', 'SYNTH-ISRCTN-0000048', NULL, 'English', 'Pediatric Clinical Trials Journal Press'),
(NULL, 2000100, 98, 'Changes in circulating neurotrophic factors following psychological intervention in patients with generalized anxiety disorder', 'Jamal Haddad//Isabela Papadopoulos//Lukas Xu//Zofia Esposito', 'Journal of Public Health Interventions', 2018, 'Background: Whether psychotherapy-induced clinical improvement is accompanied by changes in neurobiological biomarkers is unclear. Methods: 82 adults with generalized anxiety disorder (mean age 41 years) were randomized to acceptance-based cognitive-behavioral group therapy (n=41) or supportive counseling (n=41) delivered over 14 weeks. Plasma neurotrophic factor levels and anxiety severity (Hamilton Anxiety Scale) were measured at baseline and post-treatment. Results: Both treatment groups showed significant increases in plasma neurotrophic factor from baseline to post-treatment (supportive therapy: mean increase 2031.4 pg/mL, t=4.79, p<0.001; acceptance-based therapy: mean increase 1963.2 pg/mL, t=4.42, p<0.001). Anxiety symptoms decreased in both groups. However, changes in plasma neurotrophic factor did not correlate with reductions in anxiety symptom severity in either treatment modality. Conclusions: Both active psychological treatments were associated with increases in circulating neurotrophic factor levels; however, the absence of correlation with symptom improvement suggests neurotrophic factor elevation may represent a general response to treatment engagement rather than a specific mechanistic pathway. These findings should be interpreted cautiously and do not establish a direct link between biomarker changes and clinical outcomes.', '2018-05-09 09:00:00', '2026-06-27 00:00:00', 2, '1', 'Parallel-group randomized psychotherapy trial', '10.5555/medidex.synthetic.0100', 'SYNTH-ISRCTN-0000048', NULL, 'English', 'Journal of Public Health Interventions Press'),
(NULL, 2000101, 99, 'Community health worker-mediated remote clinical care for hypertension in rural African settings: design of a mixed-methods implementation trial', 'Zofia Fernandes//Tessa Mensah//Rasmus Eriksson', 'Clinical Nutrition Trials Journal', 2017, 'Background: Hypertension is increasingly prevalent in sub-Saharan Africa, yet rural populations face substantial barriers to clinic-based care including distance, transportation costs, and limited facility capacity. Community health worker (CHW)-coordinated remote consultation with clinicians represents a potential strategy to extend care access while maintaining quality. Methods: The SEARCH Sapphire study is a mixed-methods implementation trial in rural western Kenya and southwestern Uganda. Adults aged ≥40 years with moderate-severe hypertension will be randomized to CHW-facilitated remote clinical consultation (intervention) or usual clinic-based care (control). The trial incorporates both quantitative measurement of blood pressure control and health system outcomes, and qualitative exploration of acceptability through in-depth interviews with patients (n~40) and healthcare providers (n~15). Qualitative data will examine perceived quality, accessibility, integration into existing workflows, and barriers/facilitators to implementation. Mixed-methods integration will assess whether CHW-remote models are effective, acceptable, and sustainable for rural hypertension management.', '2017-09-15 09:00:00', '2026-04-18 00:00:00', 1, '1', 'Mixed-methods parallel-group randomized implementation trial', '10.5555/medidex.synthetic.0101', 'SYNTH-NCT0000049', NULL, 'English', 'Clinical Nutrition Trials Journal Press'),
(NULL, 2000102, 100, 'Patient and provider experiences with community health worker-led remote hypertension management in rural sub-Saharan Africa', 'Zofia Fernandes//Tessa Mensah//Rasmus Eriksson', 'Oncology Supportive Care Journal', 2018, 'Background: Task-shifting hypertension care to community health workers (CHWs) using remote clinical oversight may improve rural access. We explored stakeholder perceptions of CHW-facilitated telehealth versus clinic-based care. Methods: A qualitative substudy nested within the SEARCH Sapphire randomized trial enrolled 40 hypertensive patients and 15 healthcare providers in rural Kenya and Uganda. Audio-recorded semi-structured interviews explored experiences with community-based hypertension management, care preferences, and integration of remote consultation into clinical and community workflows. Data were analyzed thematically. Results: Overall, patients in the CHW-remote arm reported satisfaction with community-based care delivery, citing reduced transportation expenses and improved accessibility for those with mobility limitations or distant clinic residence. Patients perceived CHWs as appropriate for routine management and valued clinician involvement in decision-making. Providers noted telehealth consultation quality comparable to in-person care for stable hypertension but acknowledged need for clinic-based evaluation for complex cases. Successful models incorporated clear communication protocols among patients, CHWs, and clinicians. Conclusions: Both patients and providers expressed acceptability of CHW-coordinated remote clinical care as a viable approach to extend hypertension management in resource-limited rural settings, emphasizing the importance of transparent communication and integrated clinical oversight.', '2018-09-21 09:00:00', '2026-03-18 00:00:00', 2, '1', 'Qualitative nested substudy of parallel-group randomized trial', '10.5555/medidex.synthetic.0102', 'SYNTH-NCT0000049', NULL, 'English', 'Oncology Supportive Care Journal Press'),
(NULL, 2000103, 101, 'Implementation outcomes and organizational factors in scaling community health worker-mediated hypertension programs across rural facilities', 'Zofia Fernandes//Tessa Mensah//Rasmus Eriksson', 'Oncology Supportive Care Journal', 2018, 'Background: Understanding implementation success requires assessment of organizational readiness and health system integration factors. This secondary analysis examines implementation outcomes from the SEARCH Sapphire hypertension trial. Methods: Implementation data were collected from 10 participating healthcare facilities (5 intervention, 5 control) in Kenya and Uganda. Data sources included provider interviews (n=15), patient interviews (n=40), and health facility records. Analysis examined workflow integration, technology adoption, staff training adequacy, and perceived sustainability. Results: Intervention facilities successfully integrated CHW-remote consultations into routine workflows; mean integration time was 3.2 weeks post-training. Provider workload was comparable between arms. Training completion was 92% at intervention sites. Perceived sustainability was higher at facilities with designated CHW coordinators and reliable communication infrastructure. Key barriers included intermittent telephone connectivity (40% of facilities), lack of standardized treatment protocols (35%), and limited incentive structures for CHWs (50%). Facilitators included strong facility leadership support and prior experience with community-based programs. Conclusions: CHW-mediated remote care models require attention to organizational infrastructure and health system alignment for successful and sustainable implementation.', '2018-01-27 09:00:00', '2026-01-27 00:00:00', 4, '1', 'Secondary implementation analysis of mixed-methods trial', '10.5555/medidex.synthetic.0103', 'SYNTH-NCT0000049', NULL, 'English', 'Oncology Supportive Care Journal Press'),
(NULL, 2000104, 102, 'Retraction Notice: Patient and provider experiences with community health worker-led remote hypertension management in rural sub-Saharan Africa', 'Zofia Fernandes//Tessa Mensah//Rasmus Eriksson', 'Oncology Supportive Care Journal', 2020, 'The authors are unable to provide the underlying qualitative interview data in response to a post-publication request for transparency verification. In accordance with research integrity standards, the editorial office has determined that the primary results article from this qualitative study (previously published) should be retracted pending resolution of data availability concerns. The authors have been notified and are working with the journal to address this matter. All other associated publications from the SEARCH Sapphire trial remain valid pending independent verification.', '2020-04-02 09:00:00', '2026-04-27 00:00:00', 6, '1', 'Retraction notice regarding qualitative substudy', '10.5555/medidex.synthetic.0104', 'SYNTH-NCT0000049', NULL, 'English', 'Oncology Supportive Care Journal Press'),
(NULL, 2000105, 103, 'Impact of electronic nicotine devices combined with counseling on sleep outcomes in tobacco-dependent smokers: secondary analysis of a pragmatic cessation trial', 'Valentina Johansen//Quentin Lambert//Anika Dubois//Priya Esposito', 'Annals of Pragmatic Clinical Research', 2022, 'Background: While electronic nicotine delivery devices can support smoking cessation, their effects on sleep quality during cessation attempts are not well characterized. Methods: This secondary analysis evaluated sleep quality in 831 adult smokers from the ESTxENDS trial conducted across five Swiss sites. Participants were randomized to receive either free electronic nicotine devices plus standard smoking-cessation counseling (n=~415) or counseling alone (n=~416) for six months. Sleep quality was assessed using a validated standardized sleep questionnaire at baseline and six-month follow-up. Component measures of sleep quality including efficiency, duration, latency, and disturbance were examined. Results: Mean sleep quality scores did not differ significantly between the electronic nicotine device plus counseling group and counseling-alone group at six months (adjusted between-group difference: -0.20 points, 95% CI -0.53 to 0.13; p=0.24). Among subscale analyses, only sleep efficiency showed statistically significant improvement in the electronic nicotine device arm (adjusted between-group difference 1.87 points; p=0.02); however, this difference was below the threshold considered clinically meaningful. No differences were observed for sleep onset time, sleep duration, or nighttime disturbance measures. Conclusions: In smokers attempting cessation with either approach, electronic nicotine device use adjunctive to counseling did not substantially alter overall sleep quality compared to counseling alone. Clinicians can inform patients attempting smoking cessation via electronic devices that this approach is unlikely to adversely affect their sleep.', '2022-05-18 09:00:00', '2026-04-03 00:00:00', 2, '1', 'Secondary analysis of pragmatic parallel-group randomized trial', '10.5555/medidex.synthetic.0105', NULL, NULL, 'English', 'Annals of Pragmatic Clinical Research Press'),
(NULL, 2000106, 104, 'Protocol for Timing of Delivery in Pregnancy-Related Hypertension: A Randomised Comparison of Maternal Experience Outcomes', 'Gemma Dubois//Chiara Fernandes//Kavya Almeida//Ivo Wachira', 'Annals of Pragmatic Clinical Research', 2020, 'This prospective trial aims to evaluate maternal birth experiences in women diagnosed with hypertension during or prior to pregnancy. Participants will be allocated via randomisation to either elective delivery at 38 to 39 weeks gestation or continuation with routine antenatal monitoring until spontaneous labour onset or term. The primary comparison will examine subjective measures of childbirth satisfaction across four validated domains: personal agency during labour, quality of clinical support, sense of safety, and level of involvement in decision-making. Secondary assessments will explore free-text reflections from mothers and document any maternal or neonatal complications. The trial will recruit from 42 maternity centres across the United Kingdom and aims to enrol approximately 400 women. All participants will complete questionnaires postpartum, with qualitative data analysed thematically. This design will provide evidence on whether timing modification alters perceived birth experience in this high-risk obstetric population.', '2020-06-28 09:00:00', '2026-05-12 00:00:00', 1, '1', 'Parallel-group randomised controlled trial', '10.5555/medidex.synthetic.0106', NULL, NULL, 'English', 'Annals of Pragmatic Clinical Research Press'),
(NULL, 2000107, 105, 'Maternal Satisfaction and Birth Experience: Comparing Early Term versus Standard Timing Delivery in Hypertensive Pregnancy', 'Gemma Dubois//Chiara Fernandes//Kavya Almeida//Ivo Wachira', 'International Journal of Sleep and Behavior Research', 2020, 'A cohort of 357 women with hypertension across pregnancy enrolled in a randomised trial evaluating maternal experience outcomes. One group underwent planned delivery before 39 weeks, while the other followed conventional expectant care. Maternal questionnaire responses indicated comparable overall satisfaction between groups, with mean domain scores showing no clinically meaningful variation across measures of perceived support, personal autonomy, confidence in safety, and involvement in care planning. Open-ended feedback from participants was predominantly affirmative in both arms. Subgroup examination based on demographic characteristics revealed no significant differential effects. Additional clinical endpoints such as serious maternal or fetal complications did not differ substantially between the delivery timing approaches. These findings suggest that for pregnant women with controlled hypertension and uncomplicated courses, the timing of labour induction does not substantially modify the subjective experience of childbirth. Future decision-making regarding delivery timing may be guided more by clinical risk indicators and resource considerations rather than anticipated impact on maternal satisfaction.', '2020-11-11 09:00:00', '2026-03-10 00:00:00', 2, '1', 'Randomised trial, parallel design', '10.5555/medidex.synthetic.0107', NULL, NULL, 'English', 'International Journal of Sleep and Behavior Research Press'),
(NULL, 2000108, 106, 'A Crossover Study of Culinary-Range Turmeric and Pepper Extract Effects on Pain Perception in Midlife and Older Adults with Persistent Pain', 'Amara Fernandes//Franz Csik//Xavier Okoye//Ingrid Quraishi', 'Journal of Applied Clinical Trials', 2018, 'Chronic discomfort remains a significant public health challenge, with many individuals seeking nutritional adjuncts alongside conventional therapies. This randomised crossover trial will investigate whether commonly-available spice components at levels feasible within typical dietary intake can influence pain perception. Adults aged 40 and above with moderate baseline discomfort will be randomised to receive different formulations in a crossover sequence. Each participant will report daily pain ratings via text-based prompts using a standardised 0-10 scale, with assessments captured three times daily throughout the intervention periods. The study will examine whether certain spice combinations produce detectable changes in reported discomfort relative to placebo or single-ingredient controls. Participants will also log any additional pain relief medications taken. Analysis will employ mixed-effects regression to account for repeated measurements and individual variation. This design aims to determine whether accessible, food-level interventions warrant further development for pain management.', '2018-07-01 09:00:00', '2026-08-16 00:00:00', 1, '1', 'Randomised crossover clinical trial design', '10.5555/medidex.synthetic.0108', 'SYNTH-ISRCTN-0000052', NULL, 'English', 'Journal of Applied Clinical Trials Press'),
(NULL, 2000109, 107, 'Efficacy of Dietary Spice Components in Modifying Chronic Pain: A 3-Week Randomised Crossover Trial', 'Amara Fernandes//Franz Csik//Xavier Okoye//Ingrid Quraishi', 'Journal of Cardiometabolic Research', 2019, 'Thirty adults with moderate chronic pain completed a randomised crossover study examining dietary spice interventions. Participants consuming turmeric-based formulations reported meaningful reductions in daily pain intensity compared to baseline periods. Statistical testing confirmed the significance of these improvements. When comparing various dosing levels of turmeric alone, as well as turmeric combined with pepper bioenhancer, both showed comparable benefit, though the distinction between individual dose levels did not reach statistical significance. Medication use for pain relief showed no between-group differences. No serious adverse events were reported during the study period. These results indicate that incorporating turmeric into daily intake demonstrates measurable analgesic potential in this population. The bioenhancer properties of pepper did not substantially amplify outcomes in this preliminary assessment. Future research with larger samples and longer intervention windows may clarify optimal dosing and whether combining multiple botanical agents provides added benefit.', '2019-10-02 09:00:00', '2026-06-19 00:00:00', 2, '1', 'Crossover randomised controlled trial', '10.5555/medidex.synthetic.0109', 'SYNTH-ISRCTN-0000052', NULL, 'English', 'Journal of Cardiometabolic Research Press'),
(NULL, 2000110, 108, 'Dose-Response and Bioenhancer Analysis in Turmeric-Based Nutritional Pain Management', 'Amara Fernandes//Franz Csik//Xavier Okoye//Ingrid Quraishi', 'Journal of Endocrine and Metabolic Trials', 2019, 'Secondary analysis examined pain response patterns across different formulations within the crossover trial. Participants exposed to varying concentrations of turmeric showed similar reductions in reported pain scores regardless of dose level. When black pepper was added as a proposed bioenhancer, participants did not demonstrate substantially greater pain reduction compared to turmeric-only periods. Subgroup analysis considering baseline pain severity, age stratification, and prior medication use revealed no significant interactions with treatment response. Adherence to the daily reporting protocol remained high across all study arms. Long-term effects beyond the 21-day window could not be assessed in this preliminary design. These findings suggest that the analgesic signal observed with turmeric does not exhibit clear dose-response relationships within the culinary range tested, and the theoretical bioenhancing effect of pepper adjunction did not translate to measurable clinical advantage in this cohort. Recommendations for next-stage investigation include extended follow-up periods and evaluation in distinct chronic pain populations.', '2019-09-28 09:00:00', '2026-08-06 00:00:00', 4, '1', 'Secondary analysis, crossover design', '10.5555/medidex.synthetic.0110', NULL, NULL, 'English', 'Journal of Endocrine and Metabolic Trials Press'),
(NULL, 2000111, 109, 'Retraction: Efficacy of Dietary Spice Components in Modifying Chronic Pain', 'Amara Fernandes//Franz Csik//Xavier Okoye//Ingrid Quraishi', 'Journal of Cardiometabolic Research', 2020, 'The authors were unable to locate and provide the original study dataset and participant-level records upon request by the journal during routine post-publication verification. Despite multiple attempts to contact the research team, source data supporting the statistical analyses and reported results could not be produced for independent audit. In accordance with research integrity guidelines, this article is retracted. Readers should not rely on the reported findings.', '2020-12-17 09:00:00', '2026-06-01 00:00:00', 6, '1', 'Retraction notice', '10.5555/medidex.synthetic.0111', NULL, NULL, 'English', 'Journal of Cardiometabolic Research Press'),
(NULL, 2000112, 110, 'Conversational AI Support for Self-Management of Atrial Fibrillation: Results from a Randomised Trial', 'Felix Dahl//Umberto Ivanova//Noor Quraishi', 'Journal of Translational Patient Care', 2016, 'A trial randomised 480 adults with atrial fibrillation to receive either digital conversational coaching via an interactive platform or standard clinical follow-up. The conversational AI group received access to 24/7 dialogue-based education regarding symptom recognition, medication adherence, and lifestyle modifications relevant to arrhythmia management. Quality-of-life measures specific to atrial fibrillation-related limitations were assessed at trial conclusion. Participants receiving conversational AI support demonstrated numerically higher satisfaction with self-management resources and reported greater confidence in recognising warning signs. User surveys indicated the interactive platform was perceived as accessible and supportive by the majority. Engagement metrics showed sustained interaction with the conversational system over the study period. The usual care cohort completed standard clinic-based education and support. Quantitative quality-of-life scores showed modest improvements in both arms, with the AI-supported group trending toward greater gain, though formal statistical comparison revealed mixed outcomes. This trial provides preliminary evidence that conversational AI may serve as an acceptable adjunct to standard atrial fibrillation care delivery.', '2016-06-04 09:00:00', '2026-05-25 00:00:00', 2, '1', 'Randomised controlled trial, parallel groups', '10.5555/medidex.synthetic.0112', 'SYNTH-ISRCTN-0000053', NULL, 'English', 'Journal of Translational Patient Care Press'),
(NULL, 2000113, 111, 'Mobile App-Delivered Respiratory Rehabilitation in Chronic Lung Disease: Efficacy and Implementation in Primary Care Settings', 'Paloma Valdes//Sofia Xu//Oleksandr Wachira//Franz Almeida//Lena Ueda', 'Annals of Pragmatic Clinical Research', 2023, 'Ninety participants with chronic respiratory conditions were randomised to receive either a 12-week smartphone application-guided rehabilitation curriculum or conventional outpatient pulmonary management. The mobile app cohort completed supervised exercise protocols, breathing training, and educational modules accessible via their phones. Exercise testing conducted at baseline and post-intervention revealed the app-based group experienced greater improvements in capacity and objective breathing assessments compared to usual care. Functional disability scores measuring respiratory symptom burden improved significantly in the intervention arm. A substantial proportion of app users (approximately 80%) rated the interface as intuitive, and over 60% reported perceived benefit for breathing comfort. However, adherence was variable, with fewer than half completing all prescribed sessions. Health expenditures between groups remained comparable. Feasibility implementation in four community primary care clinics demonstrated similar benefit profiles. No treatment-related injuries or disease flare-ups were documented. These findings support the effectiveness of app-based pulmonary rehabilitation for improving clinical outcomes, particularly in motivated and adherent participants. Future efforts should address strategies to sustain long-term engagement with digital rehabilitation platforms.', '2023-08-26 09:00:00', '2026-04-01 00:00:00', 2, '1', 'Randomised trial plus feasibility implementation', '10.5555/medidex.synthetic.0113', 'SYNTH-NCT0000054', NULL, 'English', 'Annals of Pragmatic Clinical Research Press'),
(NULL, 2000114, 112, 'Evaluating Multi-Sector Integration of Ecological Principles in School-Based Weight Management: A Mixed-Methods Analysis Protocol', 'Priya Lindqvist//Jonas Schmidt//Anika Moreau', 'European Journal of Clinical Intervention Studies', 2015, 'Childhood obesity prevention requires simultaneous intervention across multiple levels of influence including individual, family, school, and policy sectors. This study will evaluate a comprehensive ecological initiative implemented across 15 elementary schools serving urban populations. The initiative encompasses environmental modifications, curricula adjustment, family engagement programming, and municipal policy coordination targeting food and activity environments. Analysis will examine the extent to which implemented strategies reflect core ecological principles such as social-ecological models and reciprocal determinism between behaviour and environmental context. Qualitative and quantitative coding frameworks will assess which theoretical constructs underpin specific intervention components. The research will map implementation fidelity and identify which strategy types (environmental vs. educational vs. policy) are prioritised in resource allocation. This evaluation aims to clarify which combinations of ecological and behavioural science principles appear most effective in real-world school settings, generating actionable insights for replication.', '2015-05-27 09:00:00', '2026-06-21 00:00:00', 1, '1', 'Mixed-methods implementation evaluation', '10.5555/medidex.synthetic.0114', NULL, NULL, 'English', 'European Journal of Clinical Intervention Studies Press'),
(NULL, 2000115, 113, 'Strategic Integration of Ecological Principles in Multi-Component School Obesity Prevention: Implementation Patterns and Theoretical Alignment', 'Priya Lindqvist//Jonas Schmidt//Anika Moreau', 'Journal of Chronic Disease Management', 2016, 'Thirty-two distinct intervention activities were identified across 15 schools targeting obesity prevention through modifications in nutrition and physical activity domains. Implementation pattern analysis revealed that strategies directed at institutional structures and personnel represented the largest category, followed by engagement of key administrative decision-makers from the education ministry. Fewer resources were allocated to direct parent involvement or individual student targeting. Examination of theoretical underpinning identified reciprocal determinism—the concept that environmental changes and behaviour change mutually reinforce one another—as the predominant framework across both intervention domains. Statistical testing showed no significant differential application of theoretical principles between nutrition-focused versus activity-focused components. The institutional emphasis of the intervention, combined with strong political partnership and theoretical grounding in behaviour-environment reciprocity, appears aligned with evidence-based implementation science recommendations. The relative underutilisation of parent and direct-student targeting represents an opportunity gap for future iterations. These data support the feasibility and acceptability of ecological multi-level approaches in resource-constrained school settings.', '2016-08-22 09:00:00', '2026-04-05 00:00:00', 2, '1', 'Implementation analysis of comprehensive programme', '10.5555/medidex.synthetic.0115', 'SYNTH-NCT0000055', NULL, 'English', 'Journal of Chronic Disease Management Press'),
(NULL, 2000116, 114, 'Nested Process Evaluation of a Theory-Informed Behaviour Change Intervention Embedded Within Cardiac Rehabilitation Services', 'Wanjiru Yamada//Viktor Ricci//Bo Csik//Wanjiru Brennan//Omar Nakamura', 'Journal of Community Health Interventions', 2019, 'Cardiovascular disease recovery requires sustained engagement with structured exercise and lifestyle modification programmes. This process evaluation will be nested within a cluster-randomised trial comparing standard cardiac rehabilitation versus rehabilitation augmented with explicit behaviour change coaching. Participants in both arms will attend supervised exercise sessions and education classes. The intervention arm will receive additional structured coaching incorporating goal-setting, self-monitoring, and motivational strategies grounded in established behaviour change theory. Data collection will include semi-structured interviews with participants from both conditions, focus group discussions with intervention participants, attendance records, and participant reflective diaries. Analysis will explore perceived barriers and facilitators to maintaining physical activity, the influence of social support networks, and contextual factors shaping programme engagement. Qualitative findings will be analysed thematically to identify mechanisms through which behaviour change support operates. This process evaluation will clarify which elements of standard rehabilitation and added coaching contribute most meaningfully to sustained behaviour change.', '2019-06-13 09:00:00', '2026-04-11 00:00:00', 1, '1', 'Nested process evaluation, cluster randomised trial', '10.5555/medidex.synthetic.0116', NULL, NULL, 'English', 'Journal of Community Health Interventions Press'),
(NULL, 2000117, 115, 'Understanding Participant Engagement in Cardiac Rehabilitation: Effects of Structured Behaviour Change Support on Exercise Maintenance', 'Wanjiru Yamada//Viktor Ricci//Bo Csik//Wanjiru Brennan//Omar Nakamura', 'Journal of Musculoskeletal Trials', 2019, 'Qualitative interviews and focus groups with cardiac rehabilitation participants revealed multiple dimensions influencing sustained physical activity. Both standard and enhanced intervention groups identified professional oversight, peer interaction, and structured programming as important contributors to exercise participation. The behaviour change coaching arm reported additional facilitators including individualised goal negotiation, external accountability mechanisms, and self-tracking approaches that heightened awareness of activity patterns. Qualitative thematic analysis identified increased confidence and sense of achievement as key mechanisms linking coaching strategies to sustained engagement. Conversely, perceived inadequacy in exercise capacity represented a barrier to independent practice following rehabilitation conclusion. Attendance rates and diary data indicated comparable engagement during formal sessions across both arms. Participant interviews revealed that while coaching provided additional motivational support, the fundamental value of professional guidance and social reinforcement inherent to standard rehabilitation was perceived as equally central. Quantitative outcome measures showed improvements in cardiovascular parameters in both groups, though sustained long-term behaviour change rates remain uncertain beyond the structured rehabilitation period.', '2019-05-25 09:00:00', '2026-07-04 00:00:00', 2, '1', 'Process evaluation within randomised trial', '10.5555/medidex.synthetic.0117', NULL, NULL, 'English', 'Journal of Musculoskeletal Trials Press'),
(NULL, 2000118, 116, 'Sustained Behaviour Change and Social Determinants in Cardiac Rehabilitation: A Qualitative Subgroup Analysis', 'Wanjiru Yamada//Viktor Ricci//Bo Csik//Wanjiru Brennan//Omar Nakamura', 'Journal of Public Health Interventions', 2019, 'Secondary qualitative analysis examined how individual characteristics and life circumstances shaped rehabilitation engagement and physical activity maintenance. Participants with stronger pre-existing social networks reported greater perceived support for exercise continuation post-rehabilitation. Employment status and family care responsibilities emerged as significant contextual factors affecting availability for activity. Gender-based differences in motivation for lifestyle change were evident, with female participants emphasising health preservation whereas male participants emphasised functional capacity recovery. Participants expressing higher baseline exercise confidence demonstrated more independent engagement with activity outside supervised sessions. The behaviour change coaching group showed particular benefit among individuals who reported initial low confidence, suggesting that explicit skill-building supports may address specific barriers in this subset. Long-term follow-up data were limited, precluding assessment of sustained change beyond the rehabilitation period. Healthcare utilisation rates showed no meaningful differences between arms at intermediate time points. These findings suggest that future cardiac rehabilitation interventions should incorporate tailored approaches accounting for social context and baseline self-efficacy beliefs.', '2019-06-19 09:00:00', '2026-06-10 00:00:00', 4, '1', 'Secondary qualitative subgroup analysis', '10.5555/medidex.synthetic.0118', 'SYNTH-NCT0000056', NULL, 'English', 'Journal of Public Health Interventions Press'),
(NULL, 2000119, 117, 'Feasibility Assessment and Protocol for Comparing Two Empirical Broad-Spectrum Antibiotics in Septic Critically-Ill Patients: The EMPRESS Trial Design', 'Ivo Ostrowski//Felix Novak//Mateus Zeleny//Mireille Wachira', 'Journal of Endocrine and Metabolic Trials', 2020, 'Sepsis management in intensive care units relies upon rapid empirical antimicrobial therapy, but comparative evidence regarding optimal antibiotic selection remains limited. The EMPRESS trial will conduct an integrated feasibility evaluation of a subsequent definitive trial comparing two commonly-used broad-spectrum agents in critically ill septic patients. An initial feasibility phase will enrol 200 participants across 10 intensive care units and assess five pre-defined feasibility criteria: recruitment pace, data completeness, protocol adherence, participant retention, and outcome measurement timeliness. Eligible critically ill adults with sepsis will be randomly assigned in a 1:1 ratio to receive either meropenem or piperacillin/tazobactam as empirical therapy. The primary endpoint will be all-cause mortality at 30 days post-randomisation. Eligibility criteria will specify organ dysfunction severity and recent antimicrobial exposure to ensure comparable baseline risk. Secondary safety outcomes will track serious adverse reactions. An interim feasibility review will determine whether the definitive trial should proceed unchanged or with protocol modifications.', '2020-04-13 09:00:00', '2026-03-24 00:00:00', 1, '1', 'Randomised feasibility trial, open-label design', '10.5555/medidex.synthetic.0119', NULL, NULL, 'English', 'Journal of Endocrine and Metabolic Trials Press'),
(NULL, 2000120, 118, 'Feasibility of Comparing Empirical Antibiotic Regimens in Septic Intensive-Care Patients: A Multi-Centre Adaptive Trial Evaluation', 'Ivo Ostrowski//Felix Novak//Mateus Zeleny//Mireille Wachira', 'Pediatric Clinical Trials Journal', 2020, 'The feasibility phase enrolled 200 of 284 screened critically ill patients with sepsis across 10 intensive care units over a 5.5-month period. Participant demographic characteristics showed a median age around 70 years, with approximately two-thirds males and over 40% on mechanical ventilation at baseline. Four of five feasibility criteria were met: recruitment achieved 70% of screened patients, protocol adherence exceeded 80%, data availability for the primary outcome approached 86% by trial end (though initially lagged in early months), and voluntary data withdrawal remained below 3%. The unmet criterion regarding timely outcome ascertainment improved substantially in the final month, approaching target thresholds. Thirty-day mortality was observed in approximately 30% of randomised participants. Serious adverse reactions attributable to study medications occurred in a small minority. These results support trial feasibility with a modification focusing on outcome data capture processes. The randomised design, eligibility criteria, and measurement approaches proved workable in routine intensive care settings. Investigators concluded that a full-scale definitive trial comparing these empirical antibiotics is justified.', '2020-11-16 09:00:00', '2026-08-06 00:00:00', 2, '1', 'Adaptive randomised feasibility trial', '10.5555/medidex.synthetic.0120', NULL, NULL, 'English', 'Pediatric Clinical Trials Journal Press'),
(NULL, 2000121, 119, 'Augmented Reality Enhanced by Mirror Visual Feedback for Upper Limb Recovery Post-Stroke: A Multigroup Randomised Rehabilitation Trial', 'Bruno Ostrowski//Aisling Wachira//Oleksandr Lambert', 'Pediatric Clinical Trials Journal', 2020, 'Forty-four stroke survivors with moderate-to-severe arm and hand weakness were randomised to receive one of three rehabilitation approaches over six weeks: mirror visual feedback combined with interactive augmented reality exercises, augmented reality alone, or conventional physical therapy. Each intervention included 18 sessions of 90-minute duration performed three times weekly. Objective motor recovery was measured using standardised clinical scales assessing upper limb movement quality, functional strength, and postural stability. Sensory testing evaluated proprioception and tactile perception. Additionally, participants completed self-report questionnaires regarding functional arm use in daily activities and quality-of-life perceptions. The combined mirror-plus-augmented-reality group demonstrated significantly greater improvements in motor control and balance capacity compared to conventional treatment. The augmented-reality-only group also exceeded conventional therapy on these measures. Within interactive technology groups, the mirror-enhanced approach showed superior outcomes for fine motor dexterity and touch sensation. No therapy-related injuries or adverse events occurred. Improvements were sustained at three-month follow-up assessment in all groups. These results suggest that combining mirror visual principles with interactive digital environments produces synergistic rehabilitation benefit for stroke survivors with moderate motor impairment.', '2020-04-24 09:00:00', '2026-03-16 00:00:00', 2, '1', 'Randomised controlled trial, three parallel arms', '10.5555/medidex.synthetic.0121', 'SYNTH-ISRCTN-0000058', NULL, 'English', 'Pediatric Clinical Trials Journal Press'),
(NULL, 2000122, 120, 'Optimizing Photothermal Therapy for Acne: A Randomised Protocol Comparing Laser-Enhanced versus Ultrasound-Assisted Nanoparticle Delivery', 'Mireille Castellano//Felix Jansen//Jonas Underwood', 'Journal of Cardiometabolic Research', 2022, 'Acne vulgaris treatment using photothermal approaches targets sebaceous structures with minimal systemic exposure. This randomised study will compare two delivery mechanisms for enhanced gold nanoparticles incorporated in lipid-based carriers to the skin of patients with moderate-to-severe acne. One group will receive fractional CO2 laser microperforation of the epidermis prior to nanoparticle application, while the second group will undergo ultrasound-assisted transdermal delivery. Following nanoparticle deposition, all participants will receive thermal laser treatment to activate photothermal destruction of targeted follicular structures. Clinical assessments will document lesion counts across comedonal, inflammatory, and cystic categories, as well as photographic documentation of scarring. Skin biopsies will characterise histological changes including follicular damage and collagen remodelling. Blood and urine analyses will quantify systemic absorption of gold nanoparticles. Safety monitoring will track adverse reactions, tolerability scores, and post-treatment recovery. This study aims to clarify whether mechanical barrier disruption via fractional ablation enhances therapeutic delivery and efficacy compared to acoustic delivery methods.', '2022-07-16 09:00:00', '2026-05-13 00:00:00', 1, '1', 'Randomised trial comparing delivery modalities', '10.5555/medidex.synthetic.0122', 'SYNTH-ISRCTN-0000059', NULL, 'English', 'Journal of Cardiometabolic Research Press'),
(NULL, 2000123, 121, 'Fractional Laser-Primed Photothermal Nanoparticle Therapy Versus Ultrasonic Delivery for Acne Treatment: Clinical and Histological Outcomes', 'Mireille Castellano//Felix Jansen//Jonas Underwood', 'International Journal of Mental Health Trials', 2022, 'Twenty-four Asian patients with moderate-to-severe acne were randomised to either fractional laser followed by nanoparticle therapy or ultrasound-assisted nanoparticle delivery, with both groups subsequently receiving thermal laser treatment. The fractional-laser-primed group demonstrated clinically visible reductions in all lesion categories, including improvement in existing scarring. Histological specimens showed selective destruction of sebaceous follicles with minimal surrounding dermal injury. The ultrasound-assisted delivery group showed comparable clinical responses. Both approaches were well-tolerated with minimal discomfort during treatment and rapid recovery. No participants developed serious adverse effects. Laboratory testing for systemic gold absorption showed negligible serum or urine levels in both groups. Improvement was evident by clinical assessment at follow-up examination. Photographs documented meaningful reduction in acne burden and surface scarring in both arms, with no significant between-group differences. Participants reported high satisfaction with cosmetic outcomes. These findings support the efficacy and safety of both nanoparticle delivery approaches for acne management. The data suggest that laser-based disruption of the stratum corneum does not substantially enhance therapeutic benefit relative to acoustic delivery in this patient population.', '2022-12-08 09:00:00', '2026-07-20 00:00:00', 2, '1', 'Randomised controlled treatment comparison', '10.5555/medidex.synthetic.0123', NULL, NULL, 'English', 'International Journal of Mental Health Trials Press'),
(NULL, 2000124, 122, 'Extended Follow-Up and Tolerability Analysis of Photothermal Gold Nanoparticle Therapy for Acne: Laser-Enhanced versus Ultrasound-Assisted Delivery', 'Mireille Castellano//Felix Jansen//Jonas Underwood', 'Journal of Infectious Disease Interventions', 2022, 'Secondary analysis examined durability of acne improvement and treatment tolerability in the two intervention groups. At extended follow-up assessment, both fractional-laser-primed and ultrasound-enhanced groups maintained clinical improvement gains with minimal recurrence of lesions. Patient-reported satisfaction remained high in both arms. Comparative analysis of treatment-associated discomfort scores revealed similar tolerability profiles. Skin quality assessments using standardised measures indicated durable cosmetic benefit. One participant in each group reported transient post-treatment erythema resolving within expected timeframes. Healing progress was comparable between delivery modalities. Subgroup analysis by baseline severity showed consistent benefit across lesion categories regardless of acne phenotype. No delayed adverse reactions or gold-related systemic effects were observed on repeat laboratory testing. These results support the sustained efficacy of both photothermal treatment strategies for acne, with laser-mediated delivery not conferring additional long-term benefit or tolerability advantage over ultrasound-assisted nanoparticle application.', '2022-01-20 09:00:00', '2026-02-11 00:00:00', 4, '1', 'Secondary analysis, extended follow-up', '10.5555/medidex.synthetic.0124', NULL, NULL, 'English', 'Journal of Infectious Disease Interventions Press'),
(NULL, 2000125, 123, 'Corrigendum: Fractional Laser-Primed Photothermal Nanoparticle Therapy Versus Ultrasonic Delivery for Acne Treatment', 'Mireille Castellano//Felix Jansen//Jonas Underwood', 'International Journal of Mental Health Trials', 2023, 'In the published manuscript, Table 2 incorrectly labelled the histological assessment categories, with the "follicular sebum quantification" column header inadvertently transposed with the "dermal collagen assessment" column. The authors'' original histological findings and statistical conclusions remain unchanged, as the data values were entered correctly despite the column header error. This correction does not affect interpretation of therapeutic outcomes or study conclusions.', '2023-08-06 09:00:00', '2026-02-02 00:00:00', 5, '1', 'Corrigendum notice', '10.5555/medidex.synthetic.0125', 'SYNTH-ISRCTN-0000059', NULL, 'English', 'International Journal of Mental Health Trials Press'),
(NULL, 2000126, 124, 'Randomised Comparison of Working Length Detection Methods in Root Canal Therapy: A Postoperative Discomfort Assessment Protocol', 'Tariq Petrov//Lena Adeyemi//Aisling Schmidt', 'Journal of Translational Patient Care', 2020, 'Endodontic treatment carries risk of postoperative discomfort that may vary with procedural technique. Accurate determination of working length—the distance from tooth access to apical terminus—is fundamental to successful root canal completion. This study will compare postoperative pain patterns following root canal treatment when working length is established using one of several electronic detection systems versus traditional radiographic methods. A total of 125 patients with asymptomatic irreversible pulpitis affecting single-rooted teeth will be randomly allocated to five groups representing different working length determination approaches: four distinct electronic locator brands and conventional periapical radiography. A single operator will perform all treatments using standardised instrumentation and filling techniques in single-visit appointments. Pain intensity will be assessed via visual analogue rating at 6, 12, 24, and 48 hours post-completion. Medication consumption will be documented. This design will clarify whether working length detection methodology influences the magnitude or time-course of postoperative pain.', '2020-07-14 09:00:00', '2026-02-09 00:00:00', 1, '1', 'Randomised controlled trial, five parallel groups', '10.5555/medidex.synthetic.0126', 'SYNTH-ISRCTN-0000060', NULL, 'English', 'Journal of Translational Patient Care Press'),
(NULL, 2000128, 125, 'A Two-Year Prospective Evaluation of Web-Delivered Therapeutic Intervention for Anxiety Disorders in Preadolescents: Study Design and Methodological Framework', 'Sami Haddad//Bruno Moreau//Kavya Weber//Elena Ivanova//Jamal Fernandes', 'Journal of Geriatric and Aging Research', 2019, 'Anxiety disorders remain highly prevalent in school-age populations, yet access to specialized mental health services remains limited. This protocol describes a prospective randomized trial comparing technology-assisted therapeutic intervention against digital informational control in Finnish preadolescents screened for anxiety. We will enroll approximately 465 children aged 10-13 years identified through population-based screening. The intervention arm will receive structured web-based modules (10 sessions) combined with periodic remote clinical support. The control arm will receive standard psychoeducational digital materials. Participants will be assessed at baseline, 12 months, and 24 months post-randomization using validated caregiver and youth self-report scales. Primary analyses will employ linear mixed-effects regression to compare anxiety symptom trajectories between arms. Secondary analyses will examine moderators including baseline severity, gender, and treatment engagement. We will also assess functional impairment, mood symptoms, and parental psychological adjustment. This design allows for evaluation of both immediate and sustained effects of the intervention.', '2019-09-26 09:00:00', '2026-06-15 00:00:00', 1, '1', 'Prospective parallel-group randomized controlled trial with 24-month follow-up', '10.5555/medidex.synthetic.0128', 'SYNTH-ISRCTN-0000061', NULL, 'English', 'Journal of Geriatric and Aging Research Press'),
(NULL, 2000129, 126, 'Efficacy of Technology-Supported Psychotherapy Delivered in Natural Settings for Reducing Childhood Anxiety: Two-Year Outcomes', 'Sami Haddad//Bruno Moreau//Kavya Weber//Elena Ivanova//Jamal Fernandes', 'Journal of Infectious Disease Interventions', 2020, 'Internet-based psychological interventions show promise for childhood anxiety, but long-term effectiveness in community settings remains understudied. We randomized 465 Finnish children (mean age 11 years; 71% female) with elevated anxiety to receive either 10-session web-based therapy with clinician contact (n=234) or psychoeducation via digital delivery (n=231). Outcomes were measured at 12 and 24 months using standardized anxiety assessment tools. At the 12-month assessment, the intervention group demonstrated clinically meaningful reductions in reported anxiety (mean difference 4.6 points; 95% CI 2.3-6.9; p<0.001). Similar benefits persisted at 24 months (mean difference 4.3 points; 95% CI 1.8-6.8; p=0.001). The magnitude of improvement increased from baseline to 12 months then stabilized. Subgroup analysis revealed consistent benefits across anxiety presentations. No serious adverse events were documented. Parental mental health outcomes did not differ between groups. Long-term engagement with the intervention was associated with sustained symptom improvement.', '2020-11-22 09:00:00', '2026-06-05 00:00:00', 2, '1', 'Randomized controlled trial with parallel arms and 24-month follow-up', '10.5555/medidex.synthetic.0129', NULL, NULL, 'English', 'Journal of Infectious Disease Interventions Press'),
(NULL, 2000130, 127, 'Functional Burden and Systemic Mental Health Effects in Preadolescents Receiving Guided Online Behavioral Therapy for Anxiety: Secondary Analysis from a Two-Year Trial', 'Sami Haddad//Bruno Moreau//Kavya Weber//Elena Ivanova//Jamal Fernandes', 'International Journal of Mental Health Trials', 2020, 'While primary anxiety symptom reduction is important, understanding broader functional and psychological outcomes is essential for clinical decision-making. In our 465-participant trial of internet-delivered therapy versus psychoeducation, we examined secondary endpoints including anxiety-related functional impairment, depressive symptoms, and perceived distress. At 12 months, the intervention group showed greater reductions in anxiety-related activity disruption (mean difference 3.2 points on functional impact scale; 95% CI 1.5-4.9; p<0.001) and depressive symptomatology (mean difference 1.1 points; 95% CI 0.8-1.4; p<0.001). These differences remained significant at 24 months. Effect sizes for anxiety-related impairment were larger (Cohen''s d=0.48 at 12 months) than for mood symptoms (d=0.31). Approximately 68% of the intervention group achieved clinically significant improvement on at least one secondary measure compared with 41% in the control group. Among multiple anxiety dimensions assessed, social anxiety showed the largest treatment response.', '2020-11-14 09:00:00', '2026-06-13 00:00:00', 4, '1', 'Secondary analysis of a randomized controlled trial examining functional and psychological outcomes', '10.5555/medidex.synthetic.0130', 'SYNTH-ISRCTN-0000061', NULL, 'English', 'International Journal of Mental Health Trials Press'),
(NULL, 2000131, 128, 'Protocol for Evaluating the Optimal Duration of Anticoagulation in Cancer Patients With Low-Risk Thromboembolic Events: A Stratified Randomized Study Design', 'Zofia Ivanova//Giulia Adeyemi//Gemma Xu//Wojciech Johansen', 'Journal of Cardiometabolic Research', 2022, 'Cancer-associated thromboembolism represents a major morbidity risk, yet optimal anticoagulation duration in low-risk presentations remains uncertain. This protocol describes a randomized comparison of prolonged versus standard-duration anticoagulation in cancer patients with hemodynamically stable pulmonary embolism, stratified by functional status. Eligible participants will be randomly assigned to receive either 18 months or 6 months of oral anticoagulant therapy. Study stratification will account for performance status (fully active vs. restricted activity), as this parameter may modify the risk-benefit profile of extended treatment. Primary outcome will be objectively documented recurrent thrombosis. Secondary outcomes will include bleeding complications graded by severity and major adverse events. Enrollment targets approximately 200 participants across both strata. Baseline characteristics, concurrent cancer treatments, and adherence will be evaluated as potential effect modifiers. Study assessments will occur at regular intervals throughout treatment and at a final safety follow-up visit.', '2022-07-03 09:00:00', '2026-04-08 00:00:00', 1, '1', 'Randomized controlled trial with stratification by functional performance status', '10.5555/medidex.synthetic.0131', 'SYNTH-NCT0000062', NULL, 'English', 'Journal of Cardiometabolic Research Press'),
(NULL, 2000132, 129, 'Prolonged Oral Anticoagulation Versus Standard Duration for Low-Risk Thromboembolic Events in Cancer: Subgroup Analysis by Clinical Functional Status', 'Zofia Ivanova//Giulia Adeyemi//Gemma Xu//Wojciech Johansen', 'Journal of Infectious Disease Interventions', 2023, 'Extended anticoagulation may reduce thrombotic recurrence in cancer patients, but the optimal strategy across different functional statuses requires evaluation. We analyzed 178 cancer patients with low-risk PE stratified by performance status: 79 with preserved functional capacity and 99 with functional limitations. The prolonged-therapy group (18 months) versus standard-therapy group (6 months) showed markedly different recurrent thrombosis rates in the functional-capacity stratum (3.1% vs. 19.2%; p=0.048) but a trend without statistical significance in the functionally-limited stratum (8.0% vs. 18.9%; p=0.11). Major bleeding was comparable in the functional-capacity group (2.5% vs. 7.4%; p=0.39) but appeared numerically elevated with prolonged therapy in the functionally-limited group (11.8% vs. 4.1%; p=0.22). Results suggest clinical benefit from extended treatment in patients with better baseline function, while increased bleeding risk warrants caution in those with functional decline.', '2023-03-01 09:00:00', '2026-08-17 00:00:00', 2, '1', 'Stratified subgroup analysis of a randomized anticoagulation trial', '10.5555/medidex.synthetic.0132', NULL, NULL, 'English', 'Journal of Infectious Disease Interventions Press'),
(NULL, 2000133, 130, 'Bleeding Complications and Clinical Outcomes With Sustained Versus Short-Term Anticoagulant Therapy in Cancer Patients With Pulmonary Thromboembolism', 'Zofia Ivanova//Giulia Adeyemi//Gemma Xu//Wojciech Johansen', 'Journal of Pharmacological Trials', 2024, 'Beyond efficacy against recurrent thrombosis, understanding bleeding hazard across patient subgroups is critical for individualizing anticoagulation duration. Among the 178 stratified participants, major bleeding events occurred in 3.1% of the functional-capacity group receiving prolonged therapy versus 8.1% receiving standard therapy, suggesting less bleeding risk with continuation. In the functionally-limited group, prolonged therapy was associated with higher bleeding rates (13.2% vs. 4.7%). Other secondary analyses examined timing of bleeding (most occurred within first 3 months), concomitant cancer therapies affecting bleeding risk, and patient discontinuation due to tolerability. Disease progression and death during follow-up occurred with similar frequency between groups (28% and 27%, respectively). Patient-reported outcomes revealed comparable symptom burden regardless of anticoagulation duration. Subgroup interactions were evident for patients concurrently receiving chemotherapy, among whom extended anticoagulation showed attenuated benefit.', '2024-03-26 09:00:00', '2026-07-28 00:00:00', 4, '1', 'Secondary safety and outcomes analysis from a stratified randomized trial', '10.5555/medidex.synthetic.0133', NULL, NULL, 'English', 'Journal of Pharmacological Trials Press'),
(NULL, 2000134, 131, 'Evaluating a Targeted Educational Resource to Increase Ophthalmic Screening Participation Among Young-Adult Patients With Type 2 Diabetes: A Randomized Pragmatic Trial', 'Chidi Johansen//Hiroshi Eriksson//Dovile Girard//Declan Eriksson//Esteban Okoye', 'Clinical Nutrition Trials Journal', 2021, 'Diabetic retinopathy represents a leading cause of vision loss in working-age adults, yet young patients with type 2 diabetes show persistently low retinal screening participation. Evidence-based behavioral interventions may enhance engagement. This pragmatic randomized trial will compare targeted educational materials against usual care in young adults aged 18-39 with type 2 diabetes. Participants will be stratified by prior screening history and randomized to receive either a brief, evidence-based educational leaflet or standard information. The primary outcome is patient-initiated retinal screening within 4 weeks among those with no prior screening history. Secondary outcomes include measured changes in knowledge about retinopathy, perceived risk susceptibility, beliefs about screening value, stated behavioral intentions, and perceived barriers. Approximately 130 participants will be enrolled. Baseline sociodemographic factors and clinical characteristics will be documented. Analysis will employ intention-to-treat methodology and will examine potential interactions by participant demographic and clinical characteristics.', '2021-01-01 09:00:00', '2026-08-25 00:00:00', 1, '1', 'Pragmatic randomized controlled trial with stratified randomization', '10.5555/medidex.synthetic.0134', 'SYNTH-NCT0000063', NULL, 'English', 'Clinical Nutrition Trials Journal Press'),
(NULL, 2000135, 132, 'Brief Educational Intervention and Screening Initiation in Young Adults With Type 2 Diabetes: Four-Week Outcomes From a Pragmatic Trial', 'Chidi Johansen//Hiroshi Eriksson//Dovile Girard//Declan Eriksson//Esteban Okoye', 'Annals of Pragmatic Clinical Research', 2022, 'Low screening participation for diabetic retinopathy in younger patients represents a preventable risk gap. We randomized 129 participants (mean age 28 years, 42% male) with type 2 diabetes, of whom 34 (26%) had never undergone retinal screening. Among the 34 unscreened participants, we aimed to evaluate whether provision of a tailored educational leaflet would increase subsequent screening initiation compared with standard practice. Of the originally enrolled participants, 101 completed follow-up at 4 weeks. In the unscreened subgroup, screening initiation rates showed a non-significant trend favoring the education group (38% vs. 24%; p=0.28), though statistical power was limited by lower-than-expected enrollment in this subgroup. Among all 101 participants completing follow-up, the intervention group demonstrated significantly greater increases in factual knowledge about retinopathy (mean gain 2.8 points vs. 1.1 points; p=0.03, eta-squared = 0.05). Attrition was associated with participant demographic factors including place of birth and primary language.', '2022-03-15 09:00:00', '2026-07-24 00:00:00', 2, '1', 'Pragmatic randomized trial with 4-week outcome assessment', '10.5555/medidex.synthetic.0135', 'SYNTH-NCT0000063', NULL, 'English', 'Annals of Pragmatic Clinical Research Press'),
(NULL, 2000136, 133, 'Non-Invasive Cardiac Imaging-Directed Management Versus Conventional Angiography-Based Care in Patients With Angina and Normal Coronary Arteries: Protocol for Evaluating Psychological and Symptom Outcomes', 'Chiara Novak//Kwame Underwood//Ivo Zimmermann//Elena Weber//Xavier Ionescu', 'Journal of Respiratory Care Research', 2019, 'Patients presenting with anginal chest pain but no obstructive coronary disease often experience persistent symptoms and psychological burden related to diagnostic uncertainty. This protocol describes a prospective, multicenter randomized trial comparing diagnostic and therapeutic approaches in this population. Approximately 250 participants with anginal symptoms undergoing invasive coronary angiography showing no significant stenosis will be randomized to one of two arms: (1) non-invasive stress cardiac imaging to classify disease subtype, with treatment targeted to identified physiologic abnormality, or (2) standard clinical management based on angiographic findings. Primary outcome is patient-reported illness perception measured at 6 and 12 months using validated scales. Secondary outcomes include psychological symptom severity, functional capacity, and symptom frequency. Baseline psychosocial assessments will be completed, and demographic and clinical factors will be evaluated as potential moderators. This study addresses a significant clinical gap by evaluating whether providing diagnostic clarity via advanced imaging improves psychological well-being.', '2019-06-07 09:00:00', '2026-05-23 00:00:00', 1, '1', 'Prospective multicenter randomized controlled superiority trial', '10.5555/medidex.synthetic.0136', NULL, NULL, 'English', 'Journal of Respiratory Care Research Press'),
(NULL, 2000137, 134, 'Pathophysiology-Guided Therapy and Patient Perceptions of Illness in Angina Without Coronary Obstruction: Twelve-Month Findings', 'Chiara Novak//Kwame Underwood//Ivo Zimmermann//Elena Weber//Xavier Ionescu', 'Oncology Supportive Care Journal', 2019, 'Many patients with anginal symptoms and angiographically-unobstructed coronaries experience persistent illness-related distress. We randomized 250 participants (mean age 63 years, 50% women) to receive either targeted management guided by cardiac stress imaging (n=124) or conventional angiography-based care (n=126). Illness perception was assessed using standardized instruments at baseline and at 6 and 12-month intervals. At 6 months, participants receiving imaging-directed care reported substantially lower illness perception scores (adjusted mean difference -8.8 points, 95% CI -12.3 to -5.4, p<0.001) compared with controls. This improvement was maintained at 12 months (adjusted mean difference -11.0 points, 95% CI -14.6 to -7.4, p<0.001). Psychological distress symptoms also showed greater reductions in the imaging-guided group at both 6 months (adjusted mean difference -0.9 points, p<0.001) and 12 months (adjusted mean difference -1.0 points, p<0.001). The magnitude and persistence of benefit over 12 months highlight the importance of diagnostic clarity in reducing psychological burden.', '2019-10-07 09:00:00', '2026-03-02 00:00:00', 2, '1', 'Randomized controlled trial with 12-month follow-up', '10.5555/medidex.synthetic.0137', 'SYNTH-ISRCTN-0000064', NULL, 'English', 'Oncology Supportive Care Journal Press'),
(NULL, 2000138, 135, 'Retraction: Pathophysiology-Guided Therapy and Patient Perceptions of Illness in Angina Without Coronary Obstruction: Twelve-Month Findings', 'Chiara Novak//Kwame Underwood//Ivo Zimmermann//Elena Weber//Xavier Ionescu', 'Oncology Supportive Care Journal', 2020, 'This article is retracted due to data irregularities identified during post-publication verification review. Discrepancies between source data and submitted case report forms for approximately 18% of randomized participants have been documented. The study authors were unable to reconcile these discrepancies or provide original source documentation upon request. While the directions of observed treatment effects remain consistent with mechanistic expectations, the integrity of the quantitative findings cannot be assured. We apologize to the scientific community for this development.', '2020-11-12 09:00:00', '2026-03-17 00:00:00', 6, '1', 'Retracted article from randomized controlled trial', '10.5555/medidex.synthetic.0138', NULL, NULL, 'English', 'Oncology Supportive Care Journal Press'),
(NULL, 2000139, 136, 'A Prospective Evaluation of Integrated Online Care Coordination for Managing Pruritis and Sleep Disruption in Atopic Dermatitis: Study Design and Methods', 'Tariq Santos//Ingrid Eriksson//Noor Esposito//Xavier Xu//Farah Ivanova', 'Journal of Nursing-Led Care Research', 2020, 'Atopic dermatitis remains a chronic inflammatory condition with significant morbidity, particularly regarding itch severity and secondary sleep disturbance. Coordinated multidisciplinary care delivery via digital platforms may offer improved accessibility and outcomes. This randomized trial will enroll approximately 100 adult participants with clinically confirmed atopic dermatitis from dermatology clinics. Participants will be randomized 1:1 to receive either integrated online care coordination involving clinical assessment, treatment optimization, and supportive messaging, or continued standard routine care. The online platform will include specialist nurse support, treatment adherence monitoring, and patient education modules. Primary outcome is objective and subjective measures of pruritis intensity at 12 weeks. Secondary outcomes include standardized sleep quality assessments, disease severity scoring, and dermatitis-specific quality-of-life instruments. Baseline disease severity, comorbidities, and psychosocial factors will be documented. Data collection will occur at baseline and 12 weeks post-randomization. Analysis will employ mixed-model intent-to-treat methodology.', '2020-10-23 09:00:00', '2026-01-09 00:00:00', 1, '1', 'Prospective parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0139', 'SYNTH-ISRCTN-0000065', NULL, 'English', 'Journal of Nursing-Led Care Research Press'),
(NULL, 2000140, 137, 'Efficacy of Integrated Digital Care Management in Reducing Pruritis and Improving Clinical Outcomes in Adults With Atopic Dermatitis', 'Tariq Santos//Ingrid Eriksson//Noor Esposito//Xavier Xu//Farah Ivanova', 'Oncology Supportive Care Journal', 2020, 'Itch represents the cardinal symptom driving disability in atopic dermatitis, yet conventional episodic care often inadequately addresses this burden. We randomly assigned 98 participants (mean age 42 years, 45% female) to receive either integrated online care coordination (n=49) or standard care (n=49). At 12-week assessment, the coordinated-care group demonstrated clinically meaningful reductions in itch severity compared with controls (mean difference 2.9 points on 10-point scale, p<0.001). Disease severity scores measuring extent and intensity of skin involvement improved significantly in the intervention arm (p<0.001). Sleep quality measurements showed greater improvement in the online-care group (mean difference 1.8 points, p=0.03). Dermatitis-related quality-of-life scores increased substantially in the intervention group (p<0.001). No serious adverse events were documented. Participant satisfaction with care delivery was high in both groups, though the online-care participants reported preferring the coordinated approach for future management.', '2020-03-26 09:00:00', '2026-06-27 00:00:00', 2, '1', 'Randomized controlled trial with 12-week follow-up', '10.5555/medidex.synthetic.0140', 'SYNTH-ISRCTN-0000065', NULL, 'English', 'Oncology Supportive Care Journal Press'),
(NULL, 2000141, 138, 'Systemic Outcomes and Health Service Utilization in Patients With Atopic Dermatitis Managed Through Coordinated Digital Care', 'Tariq Santos//Ingrid Eriksson//Noor Esposito//Xavier Xu//Farah Ivanova', 'Pediatric Clinical Trials Journal', 2020, 'Beyond skin-specific outcomes, understanding broader clinical benefits and healthcare system impact informs implementation decisions. Among our 98 participants, secondary analyses examined unplanned healthcare encounters, medication adjustments, and patient activation. The integrated-care group experienced fewer unscheduled clinical visits (median 1.2 vs. 3.1 visits, p=0.008) and telephone contacts with clinical staff (median 0.8 vs. 2.4 contacts, p<0.001) compared with standard-care participants. Medication optimization, assessed by documented treatment intensification or de-intensification, occurred more frequently in the coordinated-care arm (78% vs. 43%, p<0.001). Patient-reported disease knowledge and self-management confidence increased significantly in the intervention group (p<0.001). Subgroup analysis suggested larger benefits in participants with moderate-to-severe baseline disease. Cost implications, including estimated reduction in acute-care utilization, favored the coordinated approach despite additional platform costs.', '2020-01-18 09:00:00', '2026-02-12 00:00:00', 4, '1', 'Secondary outcomes and health utilization analysis from randomized trial', '10.5555/medidex.synthetic.0141', 'SYNTH-ISRCTN-0000065', NULL, 'English', 'Pediatric Clinical Trials Journal Press'),
(NULL, 2000142, 139, 'Outcomes of Onsite Telemedicine-Facilitated Hepatitis C Treatment Integrated Within Opioid Treatment Programs: Effectiveness and Patient Satisfaction Results', 'Hana Mensah//Lukas Farrell//Lena Lindqvist//Nadia Eriksson', 'Annals of Rehabilitation Science', 2020, 'Treatment barriers reduce hepatitis C cure rates in opioid-using populations. We conducted a hybrid effectiveness-implementation analysis comparing telemedicine provision within opioid treatment programs (OTPs) versus standard referral to offsite hepatology. The integration approach involved on-site clinical coordinators, telemedicine consultation infrastructure, and care coordination. Among participants receiving telemedicine within their OTP, hepatitis C viral clearance was achieved in 81% (95% CI 76-85%) compared with 64% (95% CI 58-70%) among the referral group. Treatment completion rates were 89% in the integrated model versus 71% in the referral model. Patient satisfaction with healthcare provider contact duration was significantly higher in the telemedicine group (mean 7.4 vs. 5.1 on 10-point scale, p<0.001). Organizational factors associated with superior effectiveness included on-site care coordination staff consistency, manageable clinical provider-to-patient ratios, and proactive participant identification. Telemedicine-enabled co-location of hepatitis C services with substance use treatment substantially improved both virologic outcomes and participant satisfaction.', '2020-07-19 09:00:00', '2026-02-07 00:00:00', 2, '1', 'Stepped-wedge cluster randomized hybrid effectiveness-implementation trial', '10.5555/medidex.synthetic.0142', 'SYNTH-ISRCTN-0000066', NULL, 'English', 'Annals of Rehabilitation Science Press'),
(NULL, 2000143, 140, 'Organizational and Implementation Determinants of Hepatitis C Treatment Success and Satisfaction in Opioid Treatment Program Settings', 'Hana Mensah//Lukas Farrell//Lena Lindqvist//Nadia Eriksson', 'Journal of Pharmacological Trials', 2021, 'Understanding which operational and staffing configurations optimize outcomes is critical for dissemination. We employed mixed-methods analysis examining organizational variables (site liaison presence, case manager availability, provider workload, participant volume) and implementation characteristics affecting hepatitis C cure rates and patient satisfaction. Sites with on-site care coordinator presence demonstrated higher cure rates (84% vs. 62% at sites without coordinator, p<0.001) and satisfaction (7.6 vs. 5.3, p<0.001). Lower provider-to-patient ratios (defined as fewer than 25 active cases per provider) were associated with superior outcomes (cure 85% vs. 70%; p<0.001). In the referral-model sites, higher case manager education, more intensive site-based engagement activities, and university affiliation were associated with better outcomes. Telemedicine sites required fewer optimization variables to achieve high success, while standard-referral sites required more intensive supportive infrastructure. These findings suggest implementation pathways suited to different OTP capacity levels.', '2021-12-01 09:00:00', '2026-04-23 00:00:00', 4, '1', 'Implementation science analysis of organizational determinants in cluster randomized trial', '10.5555/medidex.synthetic.0143', 'SYNTH-ISRCTN-0000066', NULL, 'English', 'Journal of Pharmacological Trials Press'),
(NULL, 2000144, 141, 'Osmotic Laxative Adjunct to Multimodal Recovery Pathway Accelerates Postoperative Gastrointestinal Recovery After Hysterectomy: A Randomized Effectiveness Trial', 'Sofia Johansen//Kwame Zimmermann//Isabela Santos//Rasmus Girard', 'Annals of Pragmatic Clinical Research', 2016, 'Enhanced recovery pathways address multiple perioperative factors, yet bowel dysfunction remains common after abdominal surgery. We evaluated whether addition of an osmotic agent to a standardized enhanced recovery protocol improves gastrointestinal outcomes. We randomized 160 women (mean age 52 years) undergoing hysterectomy to receive either enhanced recovery care with oral osmotic laxative (n=80) or enhanced recovery care without additional intervention (n=80). The osmotic-supplemented group received laxative doses beginning immediately after surgery. Primary outcome was time to tolerance of regular diet, assessed via nursing assessment and patient report. Secondary outcomes included rates of clinically significant bowel dysfunction, time to first bowel movement, and patient-reported comfort. Median time to dietary advancement was significantly shorter in the osmotic group (20.8 hours vs. 29.1 hours; p<0.001). Clinically significant bowel dysfunction occurred in 3.8% of the osmotic group versus 27.5% of the control group (p<0.001). Time to flatus was reduced in the osmotic group (17.2 hours vs. 22.4 hours; p<0.001). Patient satisfaction with recovery was higher in the osmotic-supplemented arm (p<0.001).', '2016-04-05 09:00:00', '2026-03-07 00:00:00', 2, '1', 'Randomized controlled trial with parallel assignment', '10.5555/medidex.synthetic.0144', NULL, NULL, 'English', 'Annals of Pragmatic Clinical Research Press'),
(NULL, 2000145, 142, 'A Community Venue-Based HIV Prevention Initiative Targeting Men: Protocol for Assessing Feasibility, Acceptability, and Preliminary Effectiveness in a Sub-Saharan African Setting', 'Jonas Ueda//Tessa Ricci//Felix Esposito', 'Journal of Primary Care Innovation', 2017, 'Men in high-transmission settings show low engagement with conventional HIV prevention services. Non-traditional community venues may offer opportunities for outreach and behavior change support. This protocol describes a cluster-randomized trial evaluating a barbershop-based HIV prevention program in a high-transmission district in Uganda. Approximately 250 men frequenting participating barbershops will be enrolled and followed for 12 months. Barbershops will be randomly assigned to either the intervention program (including HIV education delivered by trained barbers, free self-testing kits, and peer-support discussion groups) or standard care. Primary outcomes include program feasibility metrics (reach, attendance, session fidelity) and participant-reported acceptability. Secondary outcomes include self-reported HIV testing completion, changes in sexual risk behaviors, and interest in or use of biomedical prevention services. Exploratory outcomes include incident sexually transmitted infections. Data will be collected through participant surveys, clinical specimens, and implementation metrics at baseline, 6 months, and 12 months.', '2017-12-02 09:00:00', '2026-02-28 00:00:00', 1, '1', 'Cluster randomized trial with matched-pair cluster design', '10.5555/medidex.synthetic.0145', 'SYNTH-ISRCTN-0000068', NULL, 'English', 'Journal of Primary Care Innovation Press'),
(NULL, 2000146, 143, 'Feasibility and Community Uptake of HIV Prevention Services Delivered Through Barbershops in a High-Transmission Region of Uganda: Twelve-Month Results', 'Jonas Ueda//Tessa Ricci//Felix Esposito', 'Journal of Public Health Interventions', 2018, 'Identifying acceptable venues for HIV prevention engagement remains critical in high-burden settings. We randomized 12 barbershops in an urban district to deliver an integrated HIV prevention program and 6 control barbershops providing standard services. Approximately 250 men (mean age 34 years) were enrolled. The intervention achieved high feasibility: 94% of enrolled participants attended at least one educational session, 87% accepted self-testing kits, and 76% completed the offered peer-discussion group. Acceptability was strong, with 89% of participants rating the program as acceptable or highly acceptable. Among the intervention group, 68% initiated HIV testing during the study period compared with 42% in control barbershops (relative risk 1.62; 95% CI 1.15-2.28). Reported sexual risk behaviors showed greater reductions in the intervention arm (29% reduction vs. 8% in controls; p=0.03). Interest in long-acting preexposure prophylaxis increased in the intervention group (23% expressing interest vs. 12% in controls; p<0.001). Barbershops proved a feasible and acceptable venue for reaching men with HIV prevention services.', '2018-09-21 09:00:00', '2026-03-26 00:00:00', 2, '1', 'Cluster randomized trial with 12-month follow-up', '10.5555/medidex.synthetic.0146', NULL, NULL, 'English', 'Journal of Public Health Interventions Press'),
(NULL, 2000147, 144, 'A Digital Platform Targeting Symptom Burden in Inflammatory Bowel Disease: Study Protocol for Evaluating Clinical Effectiveness, Cost-Effectiveness, and Implementation', 'Jonas Dubois//Rasmus Xu//Elif Valdes//Noor Quraishi//Omar Brennan', 'European Journal of Clinical Intervention Studies', 2016, 'Patients with inflammatory bowel disease frequently experience persistent pain, fatigue, and bowel dysfunction despite medical optimization. Digital self-management platforms offer potential for symptom-focused support, yet rigorous effectiveness and economic evaluation remains limited. This protocol describes a prospective parallel-group randomized trial comparing digital-facilitated self-management against standard care in approximately 780 adults with inflammatory bowel disease. The intervention comprises interactive modules addressing pain management, energy conservation, and continence strategies, delivered via secure platform with periodic facilitator contact. Participants will be randomized 1:1 to intervention or care-as-usual. Primary clinical outcomes include disease-specific quality-of-life metrics and global symptom improvement at 12 months. Secondary outcomes include healthcare utilization, out-of-pocket costs, work productivity, and quality-adjusted life years. Economic analysis will assess incremental cost-effectiveness ratios from both healthcare system and societal perspectives. Baseline characteristics, disease phenotype, and treatment intensity will be examined as potential effect modifiers.', '2016-07-14 09:00:00', '2026-08-08 00:00:00', 1, '1', 'Prospective parallel-group randomized controlled trial with health economic evaluation', '10.5555/medidex.synthetic.0147', 'SYNTH-ISRCTN-0000069', NULL, 'English', 'European Journal of Clinical Intervention Studies Press'),
(NULL, 2000148, 145, 'Effectiveness and Cost-Effectiveness of Digital-Facilitated Self-Management in Inflammatory Bowel Disease: Results from a Pragmatic Randomized Trial', 'Jonas Dubois//Rasmus Xu//Elif Valdes//Noor Quraishi//Omar Brennan', 'Journal of Surgical Outcomes Research', 2016, 'While biologic medications improve inflammation markers in inflammatory bowel disease, symptom burden from pain and fatigue often persists. We randomized 780 participants (mean age 43 years, 58% female) to receive digital self-management support (n=391) or standard outpatient care (n=389) over 12 months. Primary disease-specific quality-of-life measures showed modest improvements in both arms, with between-group differences not reaching statistical significance for the pre-specified primary endpoint. However, secondary analyses revealed consistent trends favoring the intervention across symptom domains. The digital-intervention group accumulated 0.016 additional quality-adjusted life years (95% CI 0.002-0.030). Health system costs were £304.66 lower (95% CI -£803.51 to £194.18) in the intervention arm, driven primarily by reduced outpatient visit frequency. Cost-effectiveness analysis indicated the intervention yielded cost savings of approximately £28,633 per additional quality-adjusted life year gained from the healthcare perspective. Results suggest digital symptom-focused self-management offers economic benefits regardless of primary endpoint achievement.', '2016-08-05 09:00:00', '2026-06-23 00:00:00', 2, '1', 'Pragmatic randomized controlled trial with economic evaluation', '10.5555/medidex.synthetic.0148', 'SYNTH-ISRCTN-0000069', NULL, 'English', 'Journal of Surgical Outcomes Research Press'),
(NULL, 2000149, 146, 'Implementation Pathways and Health Service Utilization Patterns in Adults With Inflammatory Bowel Disease Receiving Digital-Facilitated Self-Management Support', 'Jonas Dubois//Rasmus Xu//Elif Valdes//Noor Quraishi//Omar Brennan', 'Oncology Supportive Care Journal', 2017, 'Understanding health service utilization and implementation factors informs dissemination strategy. Among the 780 trial participants, secondary analyses examined patterns of intervention engagement, changes in outpatient service use, medication escalation patterns, and work-related impacts. Participants in the digital-intervention arm attended fewer gastroenterology outpatient visits (median 2.1 vs. 2.9 visits during follow-up; p=0.02) and reported greater work productivity (mean productivity loss 18% vs. 28%; p=0.001). Medication changes (escalation or de-escalation) were similar between arms (43% vs. 45%), suggesting the intervention did not substitute for appropriate medical management. Engagement with digital modules was associated with superior cost-effectiveness (participants completing >60% of content showed greater cost savings). Qualitative data revealed participant preference for symptom-focused support complementing medical care. Unplanned healthcare visits and emergency department use showed trending reductions in the intervention group (27% vs. 34%), suggesting potential additional benefits in healthcare access.', '2017-01-12 09:00:00', '2026-06-06 00:00:00', 4, '1', 'Secondary analysis of health service utilization and implementation factors', '10.5555/medidex.synthetic.0149', NULL, NULL, 'English', 'Oncology Supportive Care Journal Press'),
(NULL, 2000150, 147, 'Effects of Electrical Noise Stimulation on Postural Control During Dynamic Balance Challenges in Parkinson Disease', 'Lukas Farrell//Felix Mensah//Grace Farrell//Hiroshi Girard//Jana Eriksson', 'Journal of Endocrine and Metabolic Trials', 2020, 'Gait instability in Parkinson disease reflects impaired sensorimotor integration and dysfunctional balance mechanisms. Electrical stimulation delivering sub-sensory-threshold noise may enhance sensory system responsiveness. We evaluated whether such stimulation improves postural stability during visually-challenging walking in 14 individuals with Parkinson disease. Participants completed walking trials within a virtual environment delivering dynamic visual perturbations, performed with and without individualized electrical noise stimulation. We measured center-of-mass sway, foot placement precision, and ankle stabilizing responses bilaterally. Peak center-of-mass lateral excursion was significantly increased during noise stimulation compared with the no-stimulation condition (mean difference 3.2 cm; p=0.02), indicating reduced postural stability. Paradoxically, the stimulation amplified rather than dampened the destabilizing effect of visual perturbations. Foot placement control metrics and ankle torque responses showed no significant between-condition differences. Exploratory analysis suggested the stimulation-induced increase in sensory noise overwhelmed compensatory balance mechanisms in this population. These findings indicate electrical noise stimulation may be counterproductive for gait stability in Parkinson disease.', '2020-05-04 09:00:00', '2026-04-09 00:00:00', 2, '1', 'Randomized crossover evaluation of electrical stimulation effects', '10.5555/medidex.synthetic.0150', NULL, NULL, 'English', 'Journal of Endocrine and Metabolic Trials Press'),
(NULL, 2000151, 148, 'A triple-blind sham-controlled design for evaluating non-invasive brain stimulation in alcohol dependence', 'Mireille Brennan//Elena Jansen//Viktor Vasquez', 'Digital Health Trials Journal', 2019, 'Background: Limited pharmaceutical options exist for individuals with severe alcohol dependence, creating need for novel interventions. Non-invasive neuromodulation techniques may offer adjunctive benefit. This protocol describes a prospective, multi-site trial examining whether direct current stimulation can reduce drinking behaviors in adults with alcohol use disorder. Methods: We will recruit 350 adults with confirmed alcohol use disorder from 14 clinical sites. Participants will be randomly assigned 1:1 to receive either active stimulation (electrodes positioned at F4/F3, 2 mA current) delivered daily for five consecutive days, or matched sham stimulation. Both groups will undergo follow-up assessments every 4 weeks throughout the 24-week study period. Randomization will be stratified by site and baseline consumption severity. Participants, assessors, and clinicians will be blinded to treatment allocation. Primary outcomes will include drinking frequency metrics and weekly alcohol volume. Eligibility: adults aged 30-70 with documented alcohol use disorder, stable housing, capacity to provide informed consent. Study design: triple-blind, parallel-group, randomized controlled trial.', '2019-12-21 09:00:00', '2026-06-11 00:00:00', 1, '1', 'Triple-blind, parallel-group, sham-controlled randomized trial', '10.5555/medidex.synthetic.0151', 'SYNTH-ISRCTN-0000071', NULL, 'English', 'Digital Health Trials Journal Press'),
(NULL, 2000152, 149, 'Reduction in heavy drinking episodes but not total consumption with direct current neuromodulation', 'Mireille Brennan//Elena Jansen//Viktor Vasquez', 'Journal of Primary Care Innovation', 2020, 'Objective: To assess the efficacy of direct current brain stimulation versus sham control in reducing alcohol consumption in adults with established alcohol use disorder. Setting: 14 outpatient clinical sites in France and Monaco from 2015-2022. Participants: 337 randomized adults with alcohol use disorder (predominantly male, mean age 51 years). Intervention: 2-mA direct current applied to prefrontal regions daily for 5 days versus sham. Results: At 24 weeks, the active stimulation group showed a statistically significant decrease in days per month with heavy drinking episodes (mean reduction 2.5 days per 4-week period, 97.5% CI: -4.9 to -0.1, p=0.022) compared to sham. However, total daily alcohol volume reduction was not statistically significant between groups (-6 g/day, 97.5% CI: -15.2 to 3.3, p=0.15). The intervention was tolerated well, with similar adverse event rates between groups. Conclusions: Active stimulation demonstrated modest, sustained benefit for reducing drinking frequency but not absolute consumption volume.', '2020-05-02 09:00:00', '2026-04-19 00:00:00', 2, '1', 'Triple-blind sham-controlled randomized trial', '10.5555/medidex.synthetic.0152', NULL, NULL, 'English', 'Journal of Primary Care Innovation Press'),
(NULL, 2000153, 150, 'Secondary outcomes: Craving reduction and biomarker changes in stimulated versus control participants', 'Mireille Brennan//Elena Jansen//Viktor Vasquez', 'Journal of Chronic Disease Management', 2021, 'Secondary analysis examined mechanistic and exploratory outcomes from the 24-week neuromodulation trial. At endpoint, the active stimulation group (versus sham) demonstrated lower self-reported craving intensity (mean difference -0.36, 95% CI -0.65 to -0.07, p=0.016) measured on a validated rating scale. Serum carbohydrate deficient transferrin, a marker of recent heavy drinking, showed greater reduction in the stimulation group (-0.33 units, 95% CI -0.65 to -0.01, p=0.045). Quality-of-life scores and mood assessments showed non-significant trends favoring active treatment. Cognitive testing revealed no between-group differences. Adverse events occurred similarly in both arms (41% active vs 37% sham), with most being mild. Data completeness was affected by losses to follow-up and incomplete diary entries. These findings suggest neuromodulation may influence psychological drive to drink and reflect reduction in heavy consumption days, though further investigation of mechanisms is warranted.', '2021-06-18 09:00:00', '2026-06-19 00:00:00', 4, '1', 'Secondary outcomes analysis from parallel-group RCT', '10.5555/medidex.synthetic.0153', NULL, NULL, 'English', 'Journal of Chronic Disease Management Press'),
(NULL, 2000154, 151, 'Microbiota-based interventions for treatment-resistant bipolar depression: study protocol', 'Chidi Moreau//Paloma Dubois//Camille Haddad//Dawit Hussain//Oleksandr Wachira', 'Journal of Musculoskeletal Trials', 2022, 'Rationale: Emerging evidence links dysbiosis to mood disorders. This pilot trial will examine whether targeted microbiota manipulation can enhance standard psychiatric care in treatment-refractory bipolar depression. Methods: Adults with confirmed bipolar disorder (I or II) presenting with moderate-to-severe depressive symptoms despite ongoing medication will be enrolled (n=35). Eligible participants must be on stable psychiatric medication for ≥4 weeks. Participants will be randomly allocated (1:1) to receive either donor-sourced microbiota transplantation or self-microbiota transplantation (autologous), delivered via colonoscopy. Both groups will continue usual psychiatric treatment. Blinding: evaluators and participants will be masked to treatment allocation; microbiota composition will be characterized using sequencing. Follow-up assessments occur weekly for the first month, then monthly through week 24. Primary outcome: depressive symptom severity assessed via validated depression rating scale. Secondary: anxiety, functional capacity, tolerability, and microbiota diversity changes. Study design: double-blind, parallel-arm pilot randomized controlled trial.', '2022-05-21 09:00:00', '2026-05-04 00:00:00', 1, '1', 'Double-blind parallel-arm randomized pilot trial', '10.5555/medidex.synthetic.0154', NULL, NULL, 'English', 'Journal of Musculoskeletal Trials Press'),
(NULL, 2000155, 152, 'Comparable depression symptom improvement with donor versus autologous microbiota in bipolar patients', 'Chidi Moreau//Paloma Dubois//Camille Haddad//Dawit Hussain//Oleksandr Wachira', 'European Journal of Clinical Intervention Studies', 2023, 'Background: Treatment-resistant depression in bipolar disorder remains challenging. We evaluated microbiota manipulation as an adjunct to pharmacotherapy. Methods: 35 adults with bipolar disorder in depressive episodes were randomized to donor microbiota (n=17) or autologous microbiota (n=18) transplantation. All participants continued their established psychiatric medications. Results: Both treatment arms showed significant depression rating score improvements from baseline to week 24 (donor mean 16.7-point improvement vs autologous 15.4-point improvement). Statistical comparison revealed no significant difference between groups (t=-0.47, p=0.64, 95% CI -7.3 to 4.6). Microbial sequencing showed donor recipients achieved bacterial profiles resembling the healthy donor source with increased microbial diversity by 6 months, whereas autologous recipients showed minimal compositional change. No serious adverse events occurred in either group. Conclusions: Both FMT approaches yielded clinically meaningful symptom reduction, though microbial colonization differed. The absence of efficacy distinction between allogenic and autologous approaches suggests need for inert control in future studies.', '2023-11-08 09:00:00', '2026-01-20 00:00:00', 2, '1', 'Double-blind randomized pilot trial', '10.5555/medidex.synthetic.0155', 'SYNTH-NCT0000072', NULL, 'English', 'European Journal of Clinical Intervention Studies Press'),
(NULL, 2000156, 153, 'Near-infrared fluorescence improves lymph node detection compared to conventional dye in breast cancer surgery', 'Paloma Zimmermann//Benedikt Moreau//Xavier Fernandes//Rosalind Nakamura', 'Journal of Geriatric and Aging Research', 2020, 'Background: Accurate sentinel lymph node identification remains critical for breast cancer staging. Conventional blue dye techniques have limitations including inconsistent identification rates and occasional allergic reactions. We compared a novel fluorescent imaging approach to standard dye tracing. Methods: 40 women with node-negative early-stage breast cancer underwent sentinel lymph node biopsy using either near-infrared fluorescence imaging (n=20) or patent blue V dye (n=20). All patients then received completion axillary lymph node dissection for pathological correlation. Results: Near-infrared fluorescence achieved 100% sentinel node identification (20/20) versus 75% with blue dye (15/20, p=0.047). Median time to identification was shorter with fluorescence (14.5 min vs 24 min, p<0.001) and more nodes were recovered per patient (mean 3.6 vs 2.4, p=0.002). Sensitivity for detecting nodal metastases was 100% with fluorescence versus 75% with blue dye; false-negative rate was 0% versus 25%, respectively. No fluorescence-related adverse events occurred; blue dye caused dermal discoloration in 75% of patients and one allergic reaction. Conclusions: Near-infrared fluorescence provides superior identification accuracy and reduced complications compared to blue dye alone for sentinel lymph node detection in early-stage breast cancer surgery.', '2020-11-17 09:00:00', '2026-02-05 00:00:00', 2, '1', 'Single-center randomized comparative trial', '10.5555/medidex.synthetic.0156', NULL, NULL, 'English', 'Journal of Geriatric and Aging Research Press'),
(NULL, 2000157, 154, 'Protocol for evaluating community acceptance and efficacy of novel spatial repellents for malaria prevention', 'Elena Nakamura//Omar Eriksson//Elif Almeida//Isabela Kallio//Elena Castellano', 'Journal of Infectious Disease Interventions', 2022, 'Background: Despite distribution of insecticide-treated nets, malaria transmission persists in sub-Saharan Africa due to insecticide resistance and outdoor biting. Spatial repellents offer a complementary approach. This study protocol outlines a cluster-randomized trial evaluating a novel transfluthrin-based spatial repellent product. Methods: The trial will be conducted in rural Kenya across matched clusters of households with children aged 6 months to 10 years. Clusters are randomly assigned to receive the novel spatial repellent product or standard prevention guidance. The intervention involves monthly product installation and replacement. Primary efficacy outcome: malaria infection incidence in children aged 6-10 years over 12 months of follow-up, assessed via blood smear and rapid diagnostic testing at baseline, 6 months, and 12 months. Secondary outcomes: community perceptions of product utility, ease of installation, perceived mosquito reduction, and comparison with existing prevention methods. Process evaluation: qualitative interviews at 1 week and 2 months post-installation to assess early user experience and identify implementation barriers. Blinding: field teams collecting clinical data will be masked to cluster assignment. Study design: double-blind cluster-randomized controlled trial.', '2022-07-25 09:00:00', '2026-01-12 00:00:00', 1, '1', 'Double-blind cluster-randomized controlled trial', '10.5555/medidex.synthetic.0157', NULL, NULL, 'English', 'Journal of Infectious Disease Interventions Press'),
(NULL, 2000158, 155, 'Spatial repellent efficacy for malaria prevention in children: results from a cluster randomized trial', 'Elena Nakamura//Omar Eriksson//Elif Almeida//Isabela Kallio//Elena Castellano', 'Journal of Applied Clinical Trials', 2023, 'Objective: To evaluate whether spatial repellent installation reduces malaria incidence in children in endemic regions. Setting: Rural households in Busia County, Kenya. Methods: Clusters of households were randomized to spatial repellent (n=clusters receiving product) or control arms. Children aged 6 months to 10 years received malaria surveillance through 12 months. Results: The spatial repellent group showed 33.4% reduction in malaria infections during interim analysis, sustained at 32.7% reduction at final analysis compared to control. Clinical manifestations of malaria and parasite prevalence were significantly lower in the repellent arm. Seasonal variation was observed, with strongest protective effect during peak transmission periods. Adherence to monthly product replacement exceeded 80%. No serious adverse health events were associated with the product. Conclusions: Spatial repellent installation provided meaningful malaria protection in children and represents a feasible addition to vector control strategies.', '2023-04-27 09:00:00', '2026-02-05 00:00:00', 2, '1', 'Double-blind cluster-randomized controlled trial', '10.5555/medidex.synthetic.0158', 'SYNTH-ISRCTN-0000074', NULL, 'English', 'Journal of Applied Clinical Trials Press'),
(NULL, 2000159, 156, 'Community perspectives on spatial repellent adoption and integration with conventional malaria control', 'Elena Nakamura//Omar Eriksson//Elif Almeida//Isabela Kallio//Elena Castellano', 'Oncology Supportive Care Journal', 2023, 'Qualitative evaluation of household acceptance of spatial repellent technology was conducted alongside efficacy assessments. Thirty households were systematically interviewed at 1 week and 2 months post-installation. Early responses were predominantly positive, with most respondents reporting perceived reduction in mosquito nuisance and activity. Key themes included appreciation for continuous protective coverage independent of sleeping behaviors, contrasting with the situational protection of bed nets. Several households expressed initial concerns about product durability and coverage area, particularly following product replacement. Participants requested longer-acting formulations and methods for treating larger household spaces. Installation ease was generally satisfactory, though some respondents suggested alternative mounting approaches. Comparative feedback indicated spatial repellents complemented rather than replaced bed net use in household prevention strategies. Integration of user feedback regarding product optimization and installation technique could enhance acceptability and long-term adherence in similar settings.', '2023-05-08 09:00:00', '2026-03-08 00:00:00', 4, '1', 'Qualitative substudy of cluster RCT', '10.5555/medidex.synthetic.0159', 'SYNTH-ISRCTN-0000074', NULL, 'English', 'Oncology Supportive Care Journal Press'),
(NULL, 2000160, 157, 'Comparative analysis of itch response and disease control with oral kinase inhibitor versus biologic therapy', 'Esteban Esposito//Dovile Valdes//Viktor Ivanova', 'Journal of Nursing-Led Care Research', 2016, 'Objective: Pruritus remains the most burdensome symptom in moderate-to-severe atopic dermatitis. We compared symptom relief between a novel oral JAK inhibitor and an established biologic therapy. Methods: A pooled analysis of 1196 patients from two phase III trials receiving either oral abrocitinib 200 mg daily (n=588) or subcutaneous dupilumab 300 mg biweekly (n=608) alongside topical therapy for 16 weeks. Stratified analysis examined outcomes by baseline itch severity. Results: Numerically greater proportions in the abrocitinib arm achieved ≥4-point itch score improvement (67% vs 63%) and itch-free/minimal state (36% vs 27%), though confidence intervals overlapped. Time to meaningful itch relief was faster with abrocitinib (median 11 days vs 29 days to 4-point improvement, and 57 vs 139 days to itch-free state). Among patients achieving itch-free status, significantly greater proportions reported normal sleep quality and excellent skin tone. Baseline itch severity correlated with atopic dermatitis disease severity and quality-of-life impairment. Conclusions: Abrocitinib demonstrated numerically faster itch response than dupilumab with comparable efficacy; achievement of itch-free state associated with substantially improved quality of life.', '2016-04-04 09:00:00', '2026-03-17 00:00:00', 2, '1', 'Pooled post-hoc analysis of phase III randomized trials', '10.5555/medidex.synthetic.0160', NULL, NULL, 'English', 'Journal of Nursing-Led Care Research Press'),
(NULL, 2000161, 158, 'Assessment of polyphenol-based adjunctive therapy on renal function and biomarkers in feline chronic kidney disease', 'Xavier Girard//Sami Underwood//Isabela Lambert', 'International Journal of Sleep and Behavior Research', 2022, 'Background: Feline chronic kidney disease commonly progresses through oxidative stress and inflammatory mechanisms. Polyphenolic compounds have demonstrated antioxidant and anti-inflammatory properties in experimental models. We propose a prospective trial to evaluate whether dietary curcumin supplementation enhances renoprotection in cats with IRIS stage 3 disease. Methods: Sixteen client-owned cats with confirmed stage 3 chronic kidney disease will be randomly assigned to receive either standard medical treatment alone (n=8) or standard treatment plus daily curcumin supplementation at 80 mg divided into two doses (n=8). All cats must be on stable renal diet and medication for ≥2 weeks prior to enrollment. Treatment will continue for 60 days with assessments at baseline, days 30, 45, and 60. Primary outcome: serum creatinine-independent marker concentration (symmetric dimethylarginine). Secondary outcomes: proteinuria, oxidative and inflammatory biomarkers, and safety/tolerability. Inclusion: cats ≥8 years with stable IRIS stage 3 disease and owner compliance capacity. Study design: prospective randomized controlled trial.', '2022-07-20 09:00:00', '2026-04-05 00:00:00', 1, '1', 'Prospective parallel-group randomized trial', '10.5555/medidex.synthetic.0161', NULL, NULL, 'English', 'International Journal of Sleep and Behavior Research Press'),
(NULL, 2000162, 159, 'Curcumin supplementation slows early renal biomarker progression in feline stage 3 chronic kidney disease', 'Xavier Girard//Sami Underwood//Isabela Lambert', 'Journal of Pharmacological Trials', 2023, 'Objective: To assess whether curcumin supplementation provides renal protective benefits beyond standard medical management. Setting: Veterinary nephrology clinic. Subjects: 16 cats with IRIS stage 3 chronic kidney disease randomly assigned to medical management plus curcumin (n=8) or medical management alone (n=8). Interventions: 80 mg curcumin daily in divided doses for 60 days. Outcomes: Baseline renal parameters were equivalent between groups. The primary endpoint, serum symmetric dimethylarginine, declined more substantially in the curcumin-supplemented group compared to standard treatment alone at days 30, 45, and 60 (p<0.01 for all timepoints). Urine protein-to-creatinine ratio also showed greater improvement over time in the supplemented group, with significant between-group differences at later study visits. Antioxidant capacity increased while oxidative stress markers decreased in the curcumin group. Inflammatory markers and apoptosis markers showed trends consistent with reduced kidney cellular injury. All cats tolerated supplementation well without adverse events. Conclusions: Curcumin co-treatment appeared to slow renal biomarker deterioration in cats with stage 3 chronic kidney disease.', '2023-08-23 09:00:00', '2026-06-11 00:00:00', 2, '1', 'Randomized controlled trial', '10.5555/medidex.synthetic.0162', 'SYNTH-ISRCTN-0000076', NULL, 'English', 'Journal of Pharmacological Trials Press'),
(NULL, 2000163, 160, 'Efficacy and safety of a cosmetic anti-acne system versus prescription therapy in adults with facial acne', 'Quentin Castellano//Yuki Ionescu//Dawit Novak//Chiara Yamada//Omar Csik', 'Annals of Rehabilitation Science', 2020, 'Background: Acne treatment options include prescription and non-prescription formulations with varying tolerability profiles. We propose a comparative effectiveness trial of a novel cosmetic anti-acne regimen versus established prescription therapy. Methods: Adults aged 18-45 with mild-to-moderate facial acne (n=54) will be randomly assigned to either cosmetic salicylic acid regimen (1% cleanser plus 2% treatment lotion, twice daily) or prescription retinoid-benzoyl peroxide combination (once daily), applied to the entire face for 12 weeks. Randomization will be stratified by skin type (Fitzpatrick I-III versus IV-VI). Assessment timepoints: 48 hours, 4 weeks, 8 weeks, and 12 weeks. Primary outcome: clinician-assessed acne severity score. Secondary outcomes: total lesion count, post-inflammatory hyperpigmentation/erythema, sebum production, and skin irritation scores. Tolerability will be measured via validated scales for dryness, redness, and stinging sensations. Inclusion: active facial acne without recent systemic acne medications. Blinding: investigator and participant blinded to treatment allocation. Study design: single-center, double-blind, randomized, active-controlled trial.', '2020-07-08 09:00:00', '2026-07-05 00:00:00', 1, '1', 'Double-blind single-center randomized trial', '10.5555/medidex.synthetic.0163', NULL, NULL, 'English', 'Annals of Rehabilitation Science Press'),
(NULL, 2000164, 161, 'Comparable efficacy of over-the-counter salicylic acid system and prescription retinoid combination for mild-moderate acne', 'Quentin Castellano//Yuki Ionescu//Dawit Novak//Chiara Yamada//Omar Csik', 'Journal of Musculoskeletal Trials', 2021, 'Objective: To compare efficacy and tolerability of a cosmetic acne regimen with prescription therapy in diverse populations. Design: Single-center, double-blind trial. Participants: 54 adults (31 cosmetic regimen, 23 prescription regimen), predominantly female (90.7%), diverse ethnic backgrounds. Intervention: Cosmetic salicylic acid system versus prescription retinoid-peroxide combination applied to face for 12 weeks. Results: Clinician-assessed acne severity improved significantly from baseline in both groups beginning at 48 hours and sustained through 12 weeks (p≤0.001). Total facial lesion counts declined similarly in both treatment arms. Post-inflammatory changes and facial oiliness showed comparable improvement. Notably, the cosmetic regimen demonstrated significantly better skin tolerability scores at week 4 for skin tightness and dryness sensations (p=0.008). Patient satisfaction exceeded 96% with cosmetic regimen across all timepoints versus lower satisfaction with prescription therapy due to irritation concerns. Both regimens were well-tolerated overall, with no serious adverse events. Conclusions: The cosmetic anti-acne regimen achieved comparable efficacy to prescription therapy with superior tolerability in patients with mild-to-moderate acne.', '2021-05-24 09:00:00', '2026-04-19 00:00:00', 2, '1', 'Double-blind randomized active-control trial', '10.5555/medidex.synthetic.0164', NULL, NULL, 'English', 'Journal of Musculoskeletal Trials Press'),
(NULL, 2000166, 162, 'Association between parental oral health beliefs and cavity disease occurrence in elementary school children', 'Felix Nakamura//Oleksandr Xu//Aisling Lambert//Hana Csik', 'Journal of Chronic Disease Management', 2021, 'Background: Parental factors influence children''s oral health behaviors and disease risk, but associations between specific parental psychosocial constructs and pediatric caries remain incompletely characterized. Methods: This cross-sectional analysis examined baseline data from 1084 parent-child dyads (34 elementary schools, Texas). Dental exams used standardized caries detection criteria. Parental knowledge, self-efficacy, and child oral health-related quality of life were assessed via validated surveys. Results: Higher parental self-efficacy was independently associated with lower caries prevalence in children (adjusted odds ratio 0.82, 95% CI 0.74-0.91, p=0.02). Parental oral health knowledge showed no significant independent association with child caries prevalence after adjustment. Child oral health-related quality-of-life scores correlated significantly with caries status (p<0.001). Demographic factors including family income and maternal education influenced both parental self-efficacy and child caries risk. Girls showed lower caries prevalence than boys (21.8% vs 28.9%, p=0.004). Conclusions: Parental self-efficacy regarding child oral hygiene emerged as a protective factor against early childhood caries, suggesting interventions targeting parental confidence in preventive capacity may reduce disease burden.', '2021-04-13 09:00:00', '2026-01-21 00:00:00', 2, '1', 'Cross-sectional baseline analysis of cluster-randomized trial', '10.5555/medidex.synthetic.0166', 'SYNTH-ISRCTN-0000078', NULL, 'English', 'Journal of Chronic Disease Management Press'),
(NULL, 2000167, 163, 'Factors influencing parental engagement in child oral health and quality-of-life outcomes', 'Felix Nakamura//Oleksandr Xu//Aisling Lambert//Hana Csik', 'Journal of Cardiometabolic Research', 2021, 'Secondary analysis examined parental factors and child quality-of-life outcomes from the baseline cross-sectional assessment. Parental self-reported confidence in ability to promote good oral habits (self-efficacy) was the strongest independent predictor of better child oral health-related quality of life (β=-0.16, 95% CI -0.24 to -0.09, p<0.001), indicating children of higher-efficacy parents reported fewer oral-health-related functional limitations and discomfort. Parental knowledge about cavity prevention mechanisms and fluoride benefits showed weaker associations. Household income significantly predicted both parental self-efficacy and child caries outcomes; low-income families showed lower self-efficacy and higher caries rates. Maternal education level correlated positively with parental self-efficacy (r=0.28, p<0.001). Among children with caries, quality-of-life impairment included self-consciousness about appearance (32%), eating difficulties (18%), and school absenteeism (8%). Parental self-efficacy mediated the relationship between household socioeconomic factors and child caries risk. These findings highlight that increasing parental confidence in preventive capacity, rather than knowledge alone, may address disparities in childhood oral health outcomes.', '2021-07-05 09:00:00', '2026-06-26 00:00:00', 4, '1', 'Secondary cross-sectional baseline analysis', '10.5555/medidex.synthetic.0167', NULL, NULL, 'English', 'Journal of Cardiometabolic Research Press'),
(NULL, 2000168, 164, 'Expanded tuberculosis diagnostic algorithms for hospitalized HIV-positive patients: a pragmatic randomized trial protocol', 'Quentin Farrell//Sofia Eriksson//Hana Ricci//Rosalind Dubois//Aisling Ricci', 'International Trials Register Quarterly', 2015, 'Rationale: Tuberculosis remains the leading cause of mortality in hospitalized persons with advanced HIV. Standard symptom-triggered diagnostic approaches may miss TB in atypical presentations. This protocol describes a pragmatic trial evaluating expanded diagnostic strategies. Methods: Hospitalized adults with HIV (≥18 years, no prior TB diagnosis or recent treatment) will be enrolled within 24 hours of admission across 11 hospitals in Tanzania and Mozambique (target n=1200). Participants will be randomly assigned 1:1 to expanded diagnostic arm or standard-care arm. Expanded arm receives TB testing from sputum, stool, and urine specimens plus urine antigen testing, irrespective of symptoms. Standard arm receives symptom-based WHO-recommended sputum and urine antigen testing. All participants receive medical management per standard protocols. Primary outcome: proportion with microbiologically confirmed TB initiating treatment within 72 hours. Secondary outcomes: 8-week mortality, time from hospital admission to TB diagnosis, and diagnostic yield by specimen type. Follow-up: all participants followed through 8 weeks post-enrollment for mortality and TB diagnosis outcomes. Blinding: laboratory personnel blinded to diagnostic arm. Study design: pragmatic individually randomized controlled trial.', '2015-05-07 09:00:00', '2026-03-05 00:00:00', 1, '1', 'Pragmatic individually randomized controlled trial', '10.5555/medidex.synthetic.0168', 'SYNTH-NCT0000079', NULL, 'English', 'International Trials Register Quarterly Press'),
(NULL, 2000170, 165, 'Progressive resistance training of inspiratory muscles in non-dialysis chronic kidney disease: study protocol', 'Lena Brennan//Franz Novak//Kavya Farrell//Kavya Moreau//Valentina Novak', 'Journal of Maternal and Perinatal Health', 2016, 'Background: Patients with pre-dialysis chronic kidney disease often develop thoracic volume restriction and respiratory muscle weakness, potentially contributing to exercise limitation and dyspnea. Whether progressive inspiratory muscle training can improve respiratory physiology in this population remains unclear. Methods: Thirty adults with CKD stages 3-5 on conservative treatment will be randomly assigned to two training protocols: experimental group (EG, n=15) receiving progressive resistance loading up to 50% of maximal inspiratory pressure, increased weekly, or control group (CG, n=15) performing fixed 5 cmH2O loading without progression. Both groups train daily for 8 weeks. Assessment timepoints: baseline and week 8. Primary outcome: thoracic cavity volumes (pulmonary, rib cage, abdominal compartments) measured via non-invasive optoelectronic plethysmography. Secondary outcomes: maximal inspiratory and expiratory pressures measured via standard manometry. Safety will be monitored throughout including vital signs and adverse symptoms. Inclusion: confirmed CKD stage 3-5, stable renal function and medications ≥4 weeks, ability to perform breathing maneuvers. Study design: randomized controlled trial with parallel-group design.', '2016-08-01 09:00:00', '2026-04-27 00:00:00', 1, '1', 'Parallel-group randomized controlled trial', '10.5555/medidex.synthetic.0170', 'SYNTH-NCT0000080', NULL, 'English', 'Journal of Maternal and Perinatal Health Press'),
(NULL, 2000171, 166, 'Respiratory muscle training expands thoracic volumes in advanced chronic kidney disease', 'Lena Brennan//Franz Novak//Kavya Farrell//Kavya Moreau//Valentina Novak', 'Digital Health Trials Journal', 2017, 'Objective: To determine whether structured inspiratory muscle training reverses restrictive physiology in CKD. Design: Randomized controlled trial. Participants: 30 adults with CKD stages 3-5 on conservative management (15 progressive-load, 15 fixed-load). Intervention: Daily inspiratory training for 8 weeks; progressive group escalated loading to 50% maximal pressure, fixed group maintained 5 cmH2O. Outcomes: Both groups showed significant increases in total thoracic volumes by end of protocol with large effect sizes. The progressive-load group demonstrated significantly greater pulmonary rib cage volume expansion (F=3.698, p=0.042) compared to fixed-load. Abdominal and chest wall volume changes were similar between groups. Maximal inspiratory pressure increased significantly in the progressive group (73.88 to 90.35 cmH2O, p<0.001) and increased minimally in the fixed group. Maximal expiratory pressure improved in both progressive (97.71 to 108.53 cmH2O, p=0.001) and fixed-load groups (80.69 to 94.77 cmH2O, p=0.004). All participants tolerated training well without adverse events. Conclusions: Daily inspiratory muscle training reversed thoracic volume restriction in pre-dialysis CKD, with progressive loading providing greater improvement in inspiratory strength than fixed minimal loading.', '2017-10-18 09:00:00', '2026-02-11 00:00:00', 2, '1', 'Parallel-group randomized trial', '10.5555/medidex.synthetic.0171', NULL, NULL, 'English', 'Digital Health Trials Journal Press'),
(NULL, 2000172, 167, 'Leg Positioning Device Intervention Reduces Skin Breakdown and Wound Complications Following Cardiac Procedures', 'Esteban Ivanova//Yusuf Ueda//Hana Xu//Yusuf Mensah', 'Journal of Pharmacological Trials', 2021, 'Surgical complications including integumentary damage and contamination-related infections remain significant morbidity factors in patients undergoing open cardiac surgery. This trial compared a novel automated positioning device with standard passive dressing techniques in reducing these adverse events. Sixty cardiac surgery patients were randomized to either the intervention arm (receiving the positioning device) or control arm (standard dressing protocol). Primary evaluation focused on dermal injury development and infection rates measured at postoperative intervals. Secondary assessment included staff acceptability scores. The positioning device group demonstrated markedly lower rates of skin breakdown (2% versus 71%, p = 0.002, relative risk 3.18) compared to controls. Infection rates showed a trend favoring the device (3% versus 18%), though this did not reach statistical significance. Staff surveys indicated high satisfaction with the device approach (mean 4.82/5.0). Implementation of mechanical positioning strategies may substantially reduce integumentary complications in cardiac surgical populations.', '2021-12-14 09:00:00', '2026-06-09 00:00:00', 2, '1', 'Randomized open trial with paired group assignment', '10.5555/medidex.synthetic.0172', NULL, NULL, 'English', 'Journal of Pharmacological Trials Press'),
(NULL, 2000173, 168, 'Comparative Efficacy of Single-Modality Versus Multimodal Neuroimaging for Brain-Machine Interface Rehabilitation Systems: Protocol for a Controlled Training Study', 'Ivo Papadopoulos//Felix Underwood//Mateus Eriksson//Kwame Mensah//Valentina Wachira', 'International Journal of Behavioral Medicine Practice', 2020, 'Brain-computer interfaces coupled with muscle stimulation represent promising adjuncts to post-stroke recovery protocols. However, uncertainty remains regarding optimal signal acquisition strategies. This protocol describes a blinded comparative trial investigating whether combined electroencephalographic and optical neuroimaging provides advantages over electroencephalography alone in supporting motor control via electrical muscle stimulation. Objectives: To compare classification performance, user experience, and physiological measures across single-modality and dual-modality signal processing pipelines. Methods: Healthy volunteer participants will undergo identical training regimens with either combined or single-modality signal interfaces over a three-day period. Outcome measurement focuses on real-time classification accuracy, subjective agency ratings, attentional load assessment, and comfort metrics. We hypothesize that multimodal acquisition will yield superior performance; secondary objectives include channel optimization and feasibility assessment.', '2020-01-24 09:00:00', '2026-01-09 00:00:00', 1, '1', 'Assessor-blinded randomized controlled training protocol', '10.5555/medidex.synthetic.0173', NULL, NULL, 'English', 'International Journal of Behavioral Medicine Practice Press'),
(NULL, 2000174, 169, 'Multimodal Neuroimaging Integration Does Not Enhance Motor Interface Performance in Healthy Learners', 'Ivo Papadopoulos//Felix Underwood//Mateus Eriksson//Kwame Mensah//Valentina Wachira', 'Journal of Chronic Disease Management', 2020, 'The combination of scalp electroencephalography and near-infrared spectroscopy was hypothesized to improve brain-machine interface control fidelity compared to electroencephalography alone. Sixteen healthy participants completed five standardized motor control training sessions using either single-source (electroencephalography-only) or dual-source (electroencephalography plus near-infrared spectroscopy) signal interpretation systems. Classification recall measured in real-time during three-class motor tasks averaged 58.2% in the electroencephalography-only condition and 54.1% in the multimodal condition (p = 0.34). Agency perception, quantified on standardized scales, approached 73% of maximum in both groups (p = 0.61). Computational optimization identified fronto-central electrode placement as most informative across both modalities, while near-infrared sensor positioning required individual-level calibration. Post-hoc simulation analysis indicated comparable predictive utility between modalities. These findings suggest that within standard classification and fusion methodologies, additional neuroimaging channels do not confer performance advantage during acute training periods.', '2020-02-17 09:00:00', '2026-04-12 00:00:00', 2, '1', 'Blinded randomized comparative controlled trial', '10.5555/medidex.synthetic.0174', NULL, NULL, 'English', 'Journal of Chronic Disease Management Press'),
(NULL, 2000175, 170, 'Neurophysiological and Psychometric Characterization of Modality-Specific Contributions to Motor Interface Learning', 'Ivo Papadopoulos//Felix Underwood//Mateus Eriksson//Kwame Mensah//Valentina Wachira', 'Journal of Community Health Interventions', 2021, 'A secondary analysis of the comparative interface study examined individualized neurophysiological patterns and learning trajectories across signal modalities. Electroencephalographic signal variance and near-infrared spectroscopy hemodynamic response were analyzed using genetic algorithm-based feature selection. Fronto-central regions (electrode positions C3 and C4) consistently emerged as highest-information sites across participants (93% inclusion frequency). Near-infrared sensor arrays required heterogeneous positioning strategies, with optimal channel locations varying significantly between subjects (inter-individual distance up to 4 cm). Subgroup analysis by age, baseline attention capacity, and prior neuroimaging exposure revealed no statistically significant moderating effects on either modality''s utility (all p > 0.08). Learning curve analysis showed equivalent trajectory steepness between groups (slopes: 0.018 versus 0.017 accuracy units per session). Across economic feasibility criteria, single-modality systems demonstrated reduced setup time and equipment cost without performance compromise.', '2021-04-09 09:00:00', '2026-02-26 00:00:00', 4, '1', 'Secondary analysis of randomized controlled interface training study', '10.5555/medidex.synthetic.0175', NULL, NULL, 'English', 'Journal of Community Health Interventions Press'),
(NULL, 2000176, 171, 'Vascular Effects of Combined Mechanical and Photobiomodulatory Periodontal Treatment: Study Design and Methodology', 'Wanjiru Rousseau//Xavier Dahl//Declan Rousseau//Chidi Underwood//Dovile Fernandes', 'Annals of Pragmatic Clinical Research', 2022, 'Periodontal inflammation is implicated in systemic vascular pathology through multiple inflammatory pathways. While periodontal intervention improves local tissue health and endothelial function, its effects on larger arterial hemodynamics remain undercharacterized. This randomized trial will compare two evidence-based periodontal treatment approaches regarding their impact on common carotid artery hemodynamic properties. Enrollment targets 40 adults with active periodontal inflammation requiring therapeutic intervention. One arm receives conventional subgingival debridement; the parallel arm receives identical debridement plus adjunctive photobiomodulation therapy. Serial vascular assessments at baseline, immediate post-treatment, and 20-week intervals will measure arterial wall tension dynamics, blood rheology, and elastic properties. Clinical periodontal parameters will be monitored throughout. This study addresses whether combining mechanical and light-based modalities produces superior vascular adaptation compared to mechanical therapy alone.', '2022-08-28 09:00:00', '2026-03-13 00:00:00', 1, '1', 'Prospective randomized two-arm controlled trial', '10.5555/medidex.synthetic.0176', NULL, NULL, 'English', 'Annals of Pragmatic Clinical Research Press'),
(NULL, 2000177, 172, 'Combined Scaling and Photobiomodulation Therapy Augments Arterial Hemodynamic Adaptation in Treated Periodontitis', 'Wanjiru Rousseau//Xavier Dahl//Declan Rousseau//Chidi Underwood//Dovile Fernandes', 'Journal of Pharmacological Trials', 2023, 'Forty patients with clinically significant periodontal disease underwent randomized allocation to either conventional subgingival instrumentation (mechanical group, n = 20) or identical instrumentation supplemented by laser photobiomodulation (combination group, n = 20). Periodontal clinical indices improved in both arms over the 5-month observation period; the combination group demonstrated numerically greater gains in gingival health scores (64% improvement versus 41%, p = 0.06). Carotid wall hemodynamic assessment revealed divergent trajectories: the combination therapy group exhibited an initial transient 3% decline in shear stress immediately following treatment, followed by sustained 9% elevation at the 20-week timepoint. The mechanical-only group showed minimal net change in arterial hemodynamics across the observation window. Circumferential wall tension and elastic modulus did not differ significantly between groups. These results suggest that photobiomodulation-augmented periodontal care may promote favorable arterial remodeling, potentially contributing to cardiovascular benefit.', '2023-03-20 09:00:00', '2026-03-28 00:00:00', 2, '1', 'Randomized two-arm controlled comparative trial', '10.5555/medidex.synthetic.0177', 'SYNTH-ISRCTN-0000083', NULL, 'English', 'Journal of Pharmacological Trials Press'),
(NULL, 2000178, 173, 'Correction to: Combined Scaling and Photobiomodulation Therapy Augments Arterial Hemodynamic Adaptation in Treated Periodontitis', 'Wanjiru Rousseau//Xavier Dahl//Declan Rousseau//Chidi Underwood//Dovile Fernandes', 'Journal of Pharmacological Trials', 2024, 'In the published results article, Figure 2 incorrectly labeled the mechanical-only group''s shear stress measurements as representing absolute values when they reflected normalized percentage change from baseline. The corrected figure indicates the mechanical-only group exhibited a mean absolute wall shear stress of 2.7 Pa (previously labeled 1.8 Pa), while the combination group measurements remain as reported. This correction does not alter the statistical significance of between-group comparisons or the primary conclusion regarding superior hemodynamic adaptation with combination therapy.', '2024-08-17 09:00:00', '2026-04-20 00:00:00', 5, '1', 'Formal correction notice', '10.5555/medidex.synthetic.0178', NULL, NULL, 'English', 'Journal of Pharmacological Trials Press'),
(NULL, 2000179, 174, 'TERM-HYP: Determining Optimal Delivery Timing in Hypertensive Pregnancy—A Multi-Center Randomized Protocol', 'Noor Schmidt//Elena Tremblay//Elif Ricci//Noor Kowalski', 'Oncology Supportive Care Journal', 2019, 'Hypertensive disorders of pregnancy complicate approximately 7% of gestations. Women who maintain stable blood pressure control and reach term face a clinical decision regarding delivery timing: immediate induction or expectant management pending spontaneous labor. Early planned delivery may mitigate maternal hypertensive crises and adverse events but carries potential for increased neonatal complications. This protocol describes a 50-center pragmatic randomized trial comparing two delivery strategies in women with well-controlled hypertension at term. Eligible participants are those randomized at 36-37 weeks gestation with singleton pregnancies. The intervention arm undergoes planned induction at 38 weeks; the comparator arm receives standard obstetric care. Co-primary outcomes address both maternal and neonatal safety; secondary outcomes include cesarean rates and cost-effectiveness. Follow-up extends to 6 weeks postpartum.', '2019-01-05 09:00:00', '2026-08-25 00:00:00', 1, '1', 'Multi-center pragmatic open-label randomized controlled trial', '10.5555/medidex.synthetic.0179', NULL, NULL, 'English', 'Oncology Supportive Care Journal Press'),
(NULL, 2000180, 175, 'Planned Early Delivery in Treated Hypertensive Pregnancy: Maternal and Neonatal Outcomes from the TERM-HYP Trial', 'Noor Schmidt//Elena Tremblay//Elif Ricci//Noor Kowalski', 'Journal of Maternal and Perinatal Health', 2020, 'Four hundred three pregnant women with hypertensive disorders at term were randomized to either planned delivery at 38 weeks (n = 201) or standard management (n = 202). Baseline characteristics were balanced; most participants had well-controlled blood pressure on antihypertensive therapy. The planned early delivery group delivered a median of 0.9 weeks earlier (38.4 versus 39.3 weeks gestation). Severe maternal complications including hypertensive emergency, maternal death, or ICU admission occurred in 13% of the early delivery group and 12% of the standard management group (adjusted risk ratio 1.14, 95% CI 0.70-1.86). Neonatal intensive care admission for 4 or more hours occurred in 7% of both groups (adjusted risk difference -0.01, 95% CI -0.06 to +0.07), meeting non-inferiority criteria. Cesarean delivery rates were 29% versus 36% (adjusted risk ratio 0.79, 95% CI 0.59-1.06). No serious adverse events were reported. Planned delivery at 38 weeks offers a safe alternative in hypertensive pregnancy.', '2020-09-19 09:00:00', '2026-07-13 00:00:00', 2, '1', 'Multi-center open-label randomized controlled trial', '10.5555/medidex.synthetic.0180', NULL, NULL, 'English', 'Journal of Maternal and Perinatal Health Press'),
(NULL, 2000181, 176, 'Integrated Professional and Peer Support Programs Enhance Exclusive Breastfeeding Continuation in a Middle Eastern Population', 'Jonas Schmidt//Noor Haddad//Bo Esposito//Jana Papadopoulos', 'Journal of Applied Clinical Trials', 2019, 'Low breastfeeding persistence remains a significant public health challenge in the Middle East. Four hundred thirty-three pregnant women were enrolled in early gestation and randomized to either receive an intensive multidisciplinary lactation support intervention or standard antenatal care. The intervention encompassed professional lactation guidance delivered during pregnancy, facility-based support immediately postpartum, and home-based peer mentoring extending through the first six months. Primary outcome assessment at 6 months postpartum showed exclusive breastfeeding rates of 68% in the intervention group versus 42% in the control group (p = 0.003, relative risk 1.62). Maternal quality-of-life scores at 1, 3, and 6 months favored the intervention group across multiple domains (p < 0.01). Secondary analysis identified cost savings of approximately USD 312 per family through reduced infant illness episodes in the intervention group. These findings support the feasibility and effectiveness of integrating professional expertise with community-level peer support to improve breastfeeding outcomes.', '2019-03-04 09:00:00', '2026-05-15 00:00:00', 2, '1', 'Multi-center randomized controlled pragmatic trial', '10.5555/medidex.synthetic.0181', 'SYNTH-ISRCTN-0000085', NULL, 'English', 'Journal of Applied Clinical Trials Press'),
(NULL, 2000182, 177, 'Age-Dependent Overdiagnosis Risk in Population-Level Prostate Cancer Screening: Long-Term Evidence from a Large Registry Study', 'Valentina Jansen//Tessa Kallio//Hiroshi Gomulka//Chiara Schmidt//Mateus Ionescu', 'Clinical Nutrition Trials Journal', 2022, 'Prostate cancer detection through serological screening represents a major policy consideration given its potential to identify clinically significant disease but also to detect indolent malignancy. This analysis examined 189,386 men invited for a single PSA measurement, with 1,247 cancers detected at initial screening. Over 15 years of follow-up, cumulative prostate cancer incidence reached 7.05% in the invited group versus 6.91% in controls—an absolute excess of 0.14% (95% CI -0.05% to 0.38%). Excess case detection attributable to screening represented approximately 11.8% of initially detected cases (95% CI 0.0%-27.2%). Age-stratified competing-risk modeling demonstrated marked age dependence: among men diagnosed at age 50 years, 17% carried undetected cancer without clinical manifestation during the ensuing 15 years; this figure rose to 31% at age 70 years and 57% at age 80 years. These data suggest that age-based screening policies warrant reconsideration in healthcare settings with elevated screening penetration in older populations.', '2022-05-16 09:00:00', '2026-03-26 00:00:00', 2, '1', 'Large-scale population registry randomized screening trial', '10.5555/medidex.synthetic.0182', 'SYNTH-ISRCTN-0000086', NULL, 'English', 'Clinical Nutrition Trials Journal Press'),
(NULL, 2000183, 178, 'Aerosol Foam Delivery of Combination Vitamin D Analog and Corticosteroid Demonstrates Superior Efficacy Compared to Ointment Formulation in Psoriasis', 'Yusuf Ueda//Kwame Underwood//Felix Lindqvist//Bruno Valdes//Ivo Wachira', 'Journal of Cardiometabolic Research', 2020, 'Three hundred seventy-six adults with plaque-type psoriasis were randomized to receive one of four formulations: combination vitamin D analog and corticosteroid in either aerosol foam or ointment vehicle, or respective vehicles alone. Primary efficacy endpoint defined treatment success as physician-assessed clinical clearing or near-clearing with minimum two-level improvement, assessed at week 4. The aerosol foam formulation achieved treatment success in 55.3% of participants versus 42.8% receiving ointment (p = 0.022). Modified disease area and severity index scores demonstrated significant between-group differences favoring foam (mean difference -0.62 points, p = 0.004). Both active formulations produced rapid and sustained itch improvement, with no meaningful differences between delivery systems. Adverse events were minimal and comparable between groups; single case of mild application site irritation with foam. These results demonstrate enhanced therapeutic efficiency with foam-based delivery of topical combination therapy for psoriasis.', '2020-11-16 09:00:00', '2026-05-28 00:00:00', 2, '1', 'Randomized multi-center investigator-blinded phase II trial', '10.5555/medidex.synthetic.0183', NULL, NULL, 'English', 'Journal of Cardiometabolic Research Press'),
(NULL, 2000184, 179, 'Personalized Psychological Intervention for Fibromyalgia: Randomized Protocol for Assessing Cognitive-Behavioral Therapy as an Adjunct to Routine Care', 'Chiara Ueda//Yuki Mensah//Tessa Yilmaz', 'Digital Health Trials Journal', 2016, 'Fibromyalgia syndrome represents a common chronic pain disorder with associated psychological comorbidities including anxiety, depression, and sleep disruption. Cognitive-behavioral interventions show promise in fibromyalgia management, yet evidence for individualized programs delivered alongside standard medical care remains limited. This protocol describes a single-blinded randomized trial enrolling 70 participants meeting diagnostic criteria at a tertiary rehabilitation center. The intervention arm will receive 10 weeks of therapist-administered individualized cognitive-behavioral programming tailored to each participant''s specific symptom profile and psychosocial stressors, delivered concurrently with ongoing routine pharmacologic and rehabilitative treatment. Control participants continue standard care alone. Outcome domains encompass validated measures of anxiety, depression, sleep architecture, emotional processing, and disease-specific functional capacity. This study will clarify whether personalized psychological intervention augments treatment response in this population.', '2016-10-18 09:00:00', '2026-03-14 00:00:00', 1, '1', 'Single-blind randomized controlled clinical trial', '10.5555/medidex.synthetic.0184', NULL, NULL, 'English', 'Digital Health Trials Journal Press'),
(NULL, 2000185, 180, 'Adjunctive Individualized Cognitive-Behavioral Therapy Substantially Improves Psychological and Sleep Outcomes in Fibromyalgia', 'Chiara Ueda//Yuki Mensah//Tessa Yilmaz', 'Journal of Endocrine and Metabolic Trials', 2016, 'Seventy participants with fibromyalgia were randomized to receive 10 weeks of individualized cognitive-behavioral therapy combined with routine treatment (n = 35) or routine treatment alone (n = 34). Fifty-seven participants completed the study protocol. At endpoint, the cognitive-behavioral therapy group demonstrated significant improvements across all measured domains compared to controls. Anxiety scores (Hospital Anxiety and Depression Scale-anxiety subscale) declined from median 13 to 10 points in the intervention group versus 13 to 12 in controls (p = 0.008). Depression scores similarly improved (13 to 9 versus 13 to 11, p = 0.006). Jenkins Sleep Scale scores showed greater benefit in the intervention arm (p = 0.002). Disease-specific functional impairment (Fibromyalgia Impact Questionnaire) declined from median 64 to 48 in the cognitive-behavioral therapy group compared to 63 to 58 in controls (p = 0.003). Beck Hopelessness Scale scores decreased more substantially with combined intervention (p = 0.009). These findings support integration of individualized psychological intervention into fibromyalgia treatment pathways.', '2016-03-09 09:00:00', '2026-05-16 00:00:00', 2, '1', 'Single-blind randomized controlled therapeutic trial', '10.5555/medidex.synthetic.0185', 'SYNTH-NCT0000088', NULL, 'English', 'Journal of Endocrine and Metabolic Trials Press'),
(NULL, 2000186, 181, 'Correction: Adjunctive Individualized Cognitive-Behavioral Therapy Substantially Improves Psychological and Sleep Outcomes in Fibromyalgia', 'Chiara Ueda//Yuki Mensah//Tessa Yilmaz', 'Journal of Endocrine and Metabolic Trials', 2018, 'The originally published results article contained an error in the secondary outcome table labeling. The Beck Hopelessness Scale median score for the routine-care-only group at baseline was listed as 9.0 when the correct value is 12.0. This typographical correction does not affect the statistical significance of the between-group comparison (p = 0.009) or any interpretation of the study''s conclusions regarding cognitive-behavioral therapy benefit. All primary outcome analyses remain unchanged.', '2018-07-09 09:00:00', '2026-03-12 00:00:00', 5, '1', 'Formal correction notice', '10.5555/medidex.synthetic.0186', NULL, NULL, 'English', 'Journal of Endocrine and Metabolic Trials Press'),
(NULL, 2000187, 182, 'Prophylactic Vacuum-Assisted Wound Closure in Emergency Abdominal Surgery: Study Protocol for a Multicenter Randomized Trial', 'Wojciech Ionescu//Aisling Ivanova//Umberto Quraishi//Rasmus Wachira', 'Journal of Chronic Disease Management', 2020, 'Surgical site infection remains a substantial source of postoperative morbidity and healthcare expenditure despite modern aseptic techniques. While negative pressure wound therapy has demonstrated efficacy in managing established wound complications, evidence regarding its prophylactic application in high-risk emergency surgical populations remains limited. This multicenter protocol describes a randomized trial comparing prophylactic negative pressure wound management with standard dressing in patients undergoing emergency abdominal surgery. Ninety participants will be enrolled and randomly assigned to either five days of prophylactic vacuum therapy (n = 45) or conventional postoperative wound dressing management (n = 45). Primary outcome measures superficial and deep surgical site infections diagnosed through standardized criteria within 30 postoperative days. Secondary measures include cost-effectiveness, wound healing progression, and patient satisfaction. This study addresses whether preventive vacuum application reduces infection risk in this vulnerable surgical population.', '2020-04-28 09:00:00', '2026-06-28 00:00:00', 1, '1', 'Multicenter randomized prospective controlled protocol', '10.5555/medidex.synthetic.0187', NULL, NULL, 'English', 'Journal of Chronic Disease Management Press'),
(NULL, 2000188, 183, 'Prophylactic Negative Pressure Therapy Substantially Reduces Surgical Site Infection in Emergency Abdominal Surgery', 'Wojciech Ionescu//Aisling Ivanova//Umberto Quraishi//Rasmus Wachira', 'Journal of Endocrine and Metabolic Trials', 2021, 'Ninety emergency surgical patients undergoing open abdominal procedures were randomized to either five days of prophylactic negative pressure wound closure (n = 45) or standard sterile dressing management (n = 45). Postoperative surgical site infection developed in 19 patients (42.2%) in the standard dressing group versus 8 patients (17.8%) in the negative pressure group (p = 0.019). Superficial infection incidence was significantly lower with prophylactic vacuum therapy (17.8% versus 37.8%, p = 0.032), while deep infection rates showed no meaningful difference (4.4% each group, p = 1.0). Additional benefits included accelerated wound healing progression and improved cosmetic appearance at 30-day assessment. One adverse event (skin irritation at vacuum interface) was documented in the negative pressure group. These findings demonstrate that prophylactic negative pressure wound therapy provides meaningful infection reduction without significant safety concerns, supporting its use in high-risk emergency surgical contexts.', '2021-08-19 09:00:00', '2026-06-11 00:00:00', 2, '1', 'Multicenter randomized prospective controlled trial', '10.5555/medidex.synthetic.0188', 'SYNTH-NCT0000089', NULL, 'English', 'Journal of Endocrine and Metabolic Trials Press'),
(NULL, 2000189, 184, 'Metformin-Exercise Interaction in Metabolic Syndrome: Protocol for Investigating Cardiorespiratory and Metabolic Adaptations', 'Valentina Ivanova//Ulla Castellano//Franz Eriksson//Dovile Eriksson//Zofia Csik', 'International Journal of Behavioral Medicine Practice', 2020, 'Metformin and structured aerobic exercise represent cornerstone interventions in metabolic syndrome management, yet the nature of their potential pharmacological-exercise interaction on cardiovascular fitness development and metabolic substrate flexibility remains incompletely characterized. This protocol describes a randomized, placebo-controlled study examining these interactions. Participants will include metformin-naive adults with metabolic syndrome, randomized to receive either metformin (1000 mg daily) or matched placebo, combined with identical supervised aerobic exercise training (5 sessions weekly, moderate intensity, 500 kcal per session) over five weeks. Primary outcomes measure peak aerobic capacity and maximal lipid oxidation capability. Secondary measures assess exercise intensity-dependent substrate switching, metabolic efficiency, and subjective exertion perception. An exploratory analysis will examine whether participant age modulates medication-exercise interactions. Findings will clarify optimal pharmacotherapy timing relative to exercise prescription in this population.', '2020-07-08 09:00:00', '2026-04-06 00:00:00', 1, '1', 'Randomized double-blind placebo-controlled exercise intervention', '10.5555/medidex.synthetic.0189', 'SYNTH-ISRCTN-0000090', NULL, 'English', 'International Journal of Behavioral Medicine Practice Press'),
(NULL, 2000190, 185, 'Metformin Attenuates Aerobic Fitness Gains While Enhancing Fat Oxidation Capacity During Exercise Training in Metabolic Syndrome', 'Valentina Ivanova//Ulla Castellano//Franz Eriksson//Dovile Eriksson//Zofia Csik', 'International Journal of Rehabilitation Trials', 2021, 'Twenty-four metformin-naive adults with metabolic syndrome completed a five-week supervised aerobic training program while receiving either metformin (1000 mg/day, n = 11) or placebo (n = 11). Peak oxygen uptake improvements showed a modest group difference: the metformin group gained 0.09 L/min compared to 0.28 L/min in the placebo group (p = 0.048). Relative to body weight, this difference approached but did not reach statistical significance (p = 0.095). In contrast, maximal fat oxidation capacity demonstrated substantially greater augmentation in the metformin group (+0.15 versus +0.03 g/min, p = 0.001). Submaximal exercise substrate oxidation patterns similarly favored the metformin group, with significantly elevated fat utilization during moderate-intensity efforts. Perceived exertion ratings were higher in the metformin group during high-intensity intervals (p = 0.019). Age-stratified analysis revealed that metformin-induced cardiorespiratory attenuation was more pronounced in participants older than 55 years (correlation r = -0.86, p < 0.001). These findings suggest that metformin produces a functionally distinct metabolic adaptation during aerobic training, trading aerobic capacity for enhanced lipid utilization and greater perceived effort.', '2021-01-24 09:00:00', '2026-08-14 00:00:00', 2, '1', 'Randomized double-blind placebo-controlled exercise trial', '10.5555/medidex.synthetic.0190', 'SYNTH-ISRCTN-0000090', NULL, 'English', 'International Journal of Rehabilitation Trials Press'),
(NULL, 2000191, 186, 'Prospective evaluation of a selective hepatic LXR antagonist targeting atherogenic lipid phenotypes: study protocol', 'Chidi Moreau//Farah Farrell//Viktor Moreau//Oleksandr Eriksson//Wojciech Tremblay', 'Annals of Pragmatic Clinical Research', 2020, 'Persistent elevation of circulating lipids despite current therapy remains a significant modifiable risk factor for atherosclerotic disease and cardiac events. The liver X receptor pathway controls both synthesis and disposal of triglyceride-bearing lipoproteins; selective inhibition at this locus may lower disease burden while preserving beneficial cholesterol transport. We describe the protocol for a first-in-human study of TLC-2716, an orally bioavailable compound engineered to restrict LXR antagonism to hepatic and gastrointestinal tissues. The study will assess tolerability, pharmacokinetics, and early biomarker responses in up to 40 healthy or at-risk volunteers over 2 weeks. Measurements will include hepatic enzyme panels, lipid fractionation, insulin secretion, and histologic assessment in liver biopsy organoids. Double-blind, placebo-controlled randomization will occur at a 1:1 ratio, with safety monitoring conducted at predefined intervals.', '2020-01-01 09:00:00', '2026-07-03 00:00:00', 1, '1', 'Phase 1, randomized, placebo-controlled trial', '10.5555/medidex.synthetic.0191', NULL, NULL, 'English', 'Annals of Pragmatic Clinical Research Press'),
(NULL, 2000192, 187, 'Safety, tolerability, and lipid response after short-term administration of TLC-2716 in humans', 'Chidi Moreau//Farah Farrell//Viktor Moreau//Oleksandr Eriksson//Wojciech Tremblay', 'International Journal of Behavioral Medicine Practice', 2021, 'Background: Selective targeting of hepatic lipid synthesis pathways offers a novel strategy to address residual cardiometabolic risk. Methods: We conducted a randomized, placebo-controlled phase 1 evaluation of TLC-2716 in adults with or at risk for dyslipidemia. Participants received 14 days of once-daily dosing. Outcomes included adverse event rates, laboratory abnormalities, and plasma lipoprotein concentrations. Results: A total of 28 subjects completed the trial. No serious adverse events were observed, and discontinuations due to tolerability were infrequent (8%). Triglyceride levels fell by an average of 31% in the treatment arm relative to baseline, while placebo showed minimal change. Postprandial remnant cholesterol declined by approximately 52% in the active group. Hepatic enzyme activities and glucose homeostasis remained stable. Conclusion: Short-term TLC-2716 exposure was well-tolerated with favorable lipid-modifying effects, supporting progression to Phase 2 efficacy studies.', '2021-12-21 09:00:00', '2026-08-28 00:00:00', 2, '1', 'Phase 1, randomized, double-blind study', '10.5555/medidex.synthetic.0192', NULL, NULL, 'English', 'International Journal of Behavioral Medicine Practice Press'),
(NULL, 2000193, 188, 'Retraction notice: Safety, tolerability, and lipid response after short-term administration of TLC-2716 in humans', 'Chidi Moreau//Farah Farrell//Viktor Moreau//Oleksandr Eriksson//Wojciech Tremblay', 'International Journal of Behavioral Medicine Practice', 2023, 'The authors have requested retraction of their phase 1 results article due to data irregularities discovered during an audit of source records. Specifically, baseline lipid measurements for three enrolled subjects could not be reconciled with laboratory documentation. While the overall tolerability profile remains consistent with the published summary, the integrity of the lipid response dataset cannot be definitively established. The authors were unable to provide complete source data upon request. The study will require replication with enhanced data governance procedures.', '2023-07-26 09:00:00', '2026-04-27 00:00:00', 6, '1', 'Retraction notice', '10.5555/medidex.synthetic.0193', 'SYNTH-ISRCTN-0000091', NULL, 'English', 'International Journal of Behavioral Medicine Practice Press'),
(NULL, 2000194, 189, 'Evaluating a structured digital platform with nursing support for reducing dietary sodium in kidney disease: a protocol for implementation science research', 'Chidi Wachira//Chiara Toivonen//Sofia Rousseau', 'European Journal of Clinical Intervention Studies', 2016, 'Excessive dietary sodium intake accelerates renal disease progression and hypertension in patients with chronic kidney disease. While evidence-based education can improve dietary awareness, adoption of sustainable behavioral change remains challenging. This mixed-methods implementation study will evaluate a technology-enhanced nursing intervention designed to support sodium restriction in patients with stages 3–4 chronic kidney disease. The protocol combines quantitative measures (24-hour urinary sodium as primary endpoint, blood pressure, and knowledge assessments) with qualitative interviews exploring facilitators and barriers to engagement. Approximately 100 participants will be randomized 1:1 to receive either enhanced digital coaching with nurse-led support or usual care comparator. Data collection spans 12 months. Mixed-methods analysis will integrate quantitative outcomes with qualitative findings to identify implementation factors influencing behavior change and inform future scaling.', '2016-12-04 09:00:00', '2026-07-13 00:00:00', 1, '1', 'Mixed-methods implementation science study', '10.5555/medidex.synthetic.0194', 'SYNTH-ISRCTN-0000092', NULL, 'English', 'European Journal of Clinical Intervention Studies Press'),
(NULL, 2000195, 190, 'Nursing-supported digital intervention for sodium management in progressive chronic kidney disease: feasibility and effectiveness', 'Chidi Wachira//Chiara Toivonen//Sofia Rousseau', 'Journal of Nursing-Led Care Research', 2017, 'Background: Digital health tools combined with clinical support may enhance lifestyle adherence in chronic kidney disease management. Objective: To assess feasibility, engagement, and outcomes of a nurse-coordinated app-based platform for sodium reduction in patients with stages 3–4 chronic kidney disease. Methods: Ninety-nine patients (mean age 58 years; 54% male) were randomly assigned to enhanced digital coaching or standard care. The intervention comprised 12 weeks of app-based reminders, educational resources, and weekly nurse consultations. Primary feasibility endpoint was protocol completion rate; secondary endpoints included urinary sodium levels, systolic blood pressure, and dietary knowledge. Results: Eighty-five percent of intervention participants completed 8 or more sessions. Mean sodium excretion declined by 18% in the intervention group versus 3% in controls. Blood pressure reduction favored intervention by 6 mm Hg systolic. Secondary outcome of dietary sodium knowledge improved significantly in both groups (P < 0.05), with a larger difference favoring intervention (P = 0.008). Conclusion: The nurse-supported digital platform demonstrated feasibility and favorable trends in sodium reduction and knowledge improvement, though long-term behavioral sustainability requires further investigation.', '2017-04-26 09:00:00', '2026-07-10 00:00:00', 2, '1', 'Randomized implementation trial', '10.5555/medidex.synthetic.0195', NULL, NULL, 'English', 'Journal of Nursing-Led Care Research Press'),
(NULL, 2000196, 191, 'Preoperative intranasal dexmedetomidine for prevention of acute encephalopathy after major joint reconstruction in older adults: study design and rationale', 'Oleksandr Jansen//Viktor Lambert//Quentin Lambert//Ulla Tremblay', 'Journal of Endocrine and Metabolic Trials', 2018, 'Acute postoperative neurocognitive dysfunction represents a serious complication affecting morbidity and length of stay in elderly surgical patients undergoing joint replacement. Sleep disruption and neuroinflammation are postulated mechanisms. The alpha-2 adrenergic agonist dexmedetomidine exerts sedative, anxiolytic, and neuroprotective properties in laboratory models. We present the protocol for a double-blind, placebo-controlled, single-center trial evaluating preoperative intranasal dexmedetomidine for delirium prevention. A total of 240 patients aged 60 or older scheduled for total hip or knee arthroplasty will be randomized 1:1 to receive either dexmedetomidine (100 µg total) or saline via nasal instillation the evening before surgery. Primary endpoint is delirium incidence assessed by standardized cognitive screening within 72 hours post-op. Secondary endpoints include delirium duration, severity grading, nocturnal sleep architecture, pain intensity, and perioperative anxiety. Safety assessments include vital sign stability and adverse respiratory events.', '2018-07-13 09:00:00', '2026-04-11 00:00:00', 1, '1', 'Double-blind, randomized, placebo-controlled trial', '10.5555/medidex.synthetic.0196', NULL, NULL, 'English', 'Journal of Endocrine and Metabolic Trials Press'),
(NULL, 2000197, 192, 'Preoperative intranasal dexmedetomidine reduces postoperative delirium and improves recovery in elderly patients undergoing orthopedic surgery', 'Oleksandr Jansen//Viktor Lambert//Quentin Lambert//Ulla Tremblay', 'Journal of Endocrine and Metabolic Trials', 2018, 'Background: Elderly patients undergoing major orthopedic procedures face elevated risk for postoperative delirium with significant morbidity implications. Objective: To determine whether preoperative intranasal dexmedetomidine reduces delirium incidence in patients aged 60+ undergoing hip or knee arthroplasty. Methods: A total of 232 patients were randomly assigned to receive either dexmedetomidine (100 µg) or placebo intranasally approximately 18 hours before surgery. Delirium assessment employed validated screening instruments administered at 24, 48, and 72 hours post-op. Secondary measures included sleep quality, anxiety, pain scores, and ambulation timing. Results: Delirium occurred in 11.2% of the dexmedetomidine group versus 23.3% in the placebo group (relative risk 0.48; 95% CI 0.27–0.86; P = 0.019). Sleep quality scores improved significantly with pretreatment (mean difference 2.8 points, P = 0.004). Preoperative and postoperative anxiety ratings were lower in the intervention arm (P = 0.008). Hemodynamic stability and oxygenation remained stable in both groups. Conclusion: Preoperative intranasal dexmedetomidine is effective and safe for delirium reduction in elderly joint surgery patients, possibly through enhancement of preoperative sleep quality.', '2018-08-25 09:00:00', '2026-06-12 00:00:00', 2, '1', 'Double-blind, placebo-controlled trial', '10.5555/medidex.synthetic.0197', 'SYNTH-ISRCTN-0000093', NULL, 'English', 'Journal of Endocrine and Metabolic Trials Press'),
(NULL, 2000198, 193, 'Protocol for an 8-week evaluation of Baduanjin practice combined with computerized cognitive remediation in hospitalized schizophrenia: methods and theoretical framework', 'Sofia Adeyemi//Kavya Csik//Felix Lambert//Hana Xu//Jonas Hussain', 'Pediatric Clinical Trials Journal', 2015, 'Schizophrenia remains a major source of disability globally, with limited pharmacological impact on cognitive deficits and functional outcomes beyond symptom suppression. Integration of mind-body practices with cognitive rehabilitation may address these gaps. This protocol describes a randomized trial comparing combined Baduanjin (traditional Chinese mind-body exercise) and computer-assisted cognitive remediation versus cognitive remediation alone. Participants will be 120 hospitalized patients aged 29–64 with schizophrenia. The combined-intervention arm will receive 85-minute sessions (40 minutes Baduanjin, 45 minutes computerized cognitive tasks) five days per week for 8 weeks. Control participants receive identical computerized cognitive work without movement training. Measurements occur at baseline and week 8, assessing psychiatric symptoms (PANSS), neurocognitive performance (NCSE), social functioning (SSPI), and subjective quality of life (SQLS). Intent-to-treat analysis will evaluate intervention efficacy on symptom severity and functional domains.', '2015-02-19 09:00:00', '2026-01-23 00:00:00', 1, '1', '8-week, parallel-arm randomized controlled trial', '10.5555/medidex.synthetic.0198', NULL, NULL, 'English', 'Pediatric Clinical Trials Journal Press'),
(NULL, 2000199, 194, 'Combined traditional exercise and cognitive training improves symptom severity and functioning in hospitalized patients with schizophrenia', 'Sofia Adeyemi//Kavya Csik//Felix Lambert//Hana Xu//Jonas Hussain', 'Journal of Chronic Disease Management', 2016, 'Background: Adjunctive therapies targeting both motor and cognitive domains may enhance outcomes in schizophrenia beyond pharmacotherapy alone. Objective: To evaluate whether combining Baduanjin practice with computerized cognitive remediation produces greater benefits than cognitive training without movement intervention. Methods: A total of 120 hospitalized schizophrenia patients (mean age 44 years; 67% male) were randomized to either combined therapy (n=60) or cognitive remediation only (n=60). Sessions occurred 5 days per week for 8 weeks. Outcome measures included PANSS (psychiatric symptoms), NCSE (cognition), SSPI (social functioning), and SQLS (quality of life). Results: At 8 weeks, the combined-treatment group showed greater reduction in PANSS total scores (mean reduction 14.2 points versus 8.7 points, P = 0.003). Improvements in negative symptom subscales were particularly pronounced (P = 0.001). Cognitive performance and social functioning indices also favored the combined approach (all P < 0.05). No serious adverse events occurred in either group. Conclusion: Addition of Baduanjin to cognitive remediation significantly enhances therapeutic benefit for psychiatric symptoms and functional domains in schizophrenia.', '2016-05-25 09:00:00', '2026-06-28 00:00:00', 2, '1', 'Randomized controlled trial', '10.5555/medidex.synthetic.0199', 'SYNTH-ISRCTN-0000094', NULL, 'English', 'Journal of Chronic Disease Management Press'),
(NULL, 2000200, 195, 'Telehealth-delivered support module for family caregivers navigating dementia institutionalization: protocol for a randomized mixed-methods implementation study', 'Umberto Girard//Rasmus Esposito//Dovile Farrell//Zofia Bergstrom', 'Journal of Chronic Disease Management', 2020, 'Admission of a loved one to residential dementia care precipitates significant emotional distress in family caregivers, with high rates of depression and anxiety. Few interventions specifically address the adjustment to institutionalization. This protocol describes a mixed-methods trial of the Residential Care Transition Module (RCTM), a 12-month telehealth program combining six structured sessions with therapist-guided ad hoc consultations. A total of 240 primary caregivers will be randomly assigned 1:1 to the intervention or attention control arm. The RCTM delivers psychoeducation, problem-solving strategies, and emotional support tailored to residential placement challenges. Data collection includes validated scales for depression (PHQ-9), care-related stress, and mastery at baseline, 3, 6, and 12 months. Qualitative interviews with 30 purposively selected caregivers will explore intervention mechanisms and implementation factors. Fidelity is monitored through session recordings and therapist documentation. Mixed-methods analysis will integrate quantitative outcomes with thematic qualitative findings.', '2020-10-19 09:00:00', '2026-07-17 00:00:00', 1, '1', 'Randomized, mixed-methods implementation trial', '10.5555/medidex.synthetic.0200', NULL, NULL, 'English', 'Journal of Chronic Disease Management Press'),
(NULL, 2000201, 196, 'Impact of telehealth support on emotional adjustment and coping in family caregivers of residents with dementia', 'Umberto Girard//Rasmus Esposito//Dovile Farrell//Zofia Bergstrom', 'Oncology Supportive Care Journal', 2021, 'Background: Family caregivers experience substantial psychological burden following institutional placement of relatives with dementia. We evaluated a structured telehealth intervention designed to facilitate adjustment and enhance coping. Methods: A total of 240 primary caregivers were randomized to receive either the Residential Care Transition Module (RCTM) or control comparison. The RCTM included 6 core sessions plus flexible ad hoc phone support over 12 months. Primary outcomes were depressive symptoms (PHQ-9 score change) and perceived care-related stress assessed at months 3, 6, and 12. Secondary outcomes included caregiver mastery and intervention acceptability. Results: At 12 months, the RCTM group demonstrated mean PHQ-9 reductions of 3.8 points versus 1.2 points in controls (P = 0.015). Caregiver-reported stress showed similar favorable patterns. Ninety-one percent (107/120) of RCTM participants completed all structured sessions. Qualitative interviews identified key therapeutic elements including validation of feelings, practical problem-solving guidance, and sustained accessibility of a supportive clinician. Higher utilization of flexible sessions correlated with greater symptom improvement. Conclusion: Telehealth-delivered support effectively reduces depressive symptoms and facilitates emotional adjustment during the dementia institutionalization transition.', '2021-01-26 09:00:00', '2026-02-17 00:00:00', 2, '1', 'Randomized implementation study', '10.5555/medidex.synthetic.0201', 'SYNTH-ISRCTN-0000095', NULL, 'English', 'Oncology Supportive Care Journal Press'),
(NULL, 2000202, 197, 'Implementing structured palliative transitions across diverse European healthcare systems: protocol for a multi-stakeholder adaptation study', 'Aisling Kallio//Priya Novak//Lukas Girard', 'Journal of Musculoskeletal Trials', 2019, 'Care transitions for advanced cancer patients often lack coordination across institutional boundaries, compromising quality and continuity. The Pal-Cycles intervention targets these gaps through structured communication and care planning protocols. Given substantial variation in European healthcare systems and end-of-life practices, successful implementation requires systematic adaptation to local contexts. This protocol describes the adaptation methodology for Pal-Cycles across seven countries spanning different healthcare funding models, regulatory environments, and cultural frameworks. Adaptation employs structured nominal group techniques with iterative refinement through multistakeholder consultation. Clinician working groups in each country will collaborate with patient/family advisory panels (where feasible) to refine intervention components while maintaining theoretical fidelity. Subsequent implementation uses a stepped-wedge design to evaluate outcomes including implementation reach, fidelity measures, and preliminary clinical and process endpoints. This paper details the systematic approach to cross-cultural adaptation of complex palliative care interventions.', '2019-03-11 09:00:00', '2026-04-15 00:00:00', 1, '1', 'Multi-country stepped-wedge adaptation trial', '10.5555/medidex.synthetic.0202', NULL, NULL, 'English', 'Journal of Musculoskeletal Trials Press'),
(NULL, 2000203, 198, 'Systematic adaptation of a palliative care intervention for implementation across seven European countries: outcomes from the Pal-Cycles partnership', 'Aisling Kallio//Priya Novak//Lukas Girard', 'Journal of Translational Patient Care', 2020, 'Background: Successful implementation of complex healthcare interventions across diverse settings requires culturally responsive adaptation. We report findings from adapting the Pal-Cycles intervention across seven European countries. Methods: A total of 36 clinical leaders and 14 patient/family representatives participated in structured adaptation meetings over 4 months. Each country''s working group addressed five core intervention components: assessment protocols, communication frameworks, care planning templates, professional training modules, and patient information resources. Nominal group technique facilitated prioritized refinement of elements. Outcomes included consensus achievement and production of country-specific intervention manuals. Results: All seven countries successfully developed adapted intervention manuals maintaining core theoretical components while reflecting local healthcare architecture, regulatory requirements, and cultural end-of-life perspectives. Key adaptations included translation of outcome measures, alignment with local care pathways, and integration of existing professional roles. All countries achieved consensus on core intervention elements (100% agreement on 4 of 5 components). Qualitative feedback indicated strong perceived relevance and feasibility for local implementation. Conclusion: Systematic multi-stakeholder engagement enables effective adaptation of palliative interventions across heterogeneous European contexts while preserving intervention integrity.', '2020-08-25 09:00:00', '2026-08-10 00:00:00', 2, '1', 'Multi-country adaptation study', '10.5555/medidex.synthetic.0203', 'SYNTH-ISRCTN-0000096', NULL, 'English', 'Journal of Translational Patient Care Press'),
(NULL, 2000204, 199, 'Clinical outcomes and implementation characteristics of adapted Pal-Cycles intervention during stepped-wedge rollout', 'Aisling Kallio//Priya Novak//Lukas Girard', 'Oncology Supportive Care Journal', 2021, 'Background: Following successful adaptation of Pal-Cycles across seven European countries, this analysis presents clinical and implementation outcomes during stepped-wedge implementation. Objective: To evaluate preliminary clinical effectiveness and implementation metrics following adapted intervention deployment. Methods: Twelve-month outcome data were collected from 180 advanced cancer patients and their providers across all seven countries during stepped-wedge phase. Patient-reported measures included symptom burden, care satisfaction, and quality of life. Provider-level metrics assessed care coordination perception and workflow integration. Implementation fidelity was monitored through audits of care documentation and intervention protocol adherence. Results: Patient-reported care coordination improved by 3.2 points on an 11-point scale (95% CI 1.8–4.6). Symptom burden decreased by a mean 2.1 points on the Edmonton Symptom Assessment System (P = 0.042). Provider satisfaction with care planning processes increased across countries (mean 6.8/10 baseline to 8.1/10 post-implementation). Implementation fidelity averaged 81% across sites (range 74–91%). No serious intervention-related adverse events were identified. Conclusion: Adapted Pal-Cycles implementation demonstrated feasibility, positive preliminary clinical outcomes, and moderate-to-high fidelity across diverse European healthcare settings.', '2021-01-09 09:00:00', '2026-01-08 00:00:00', 4, '1', 'Stepped-wedge implementation analysis', '10.5555/medidex.synthetic.0204', NULL, NULL, 'English', 'Oncology Supportive Care Journal Press'),
(NULL, 2000205, 200, 'Efficacy and safety of alofropodect in acute schizophrenia: a phase 2 randomized controlled trial', 'Tessa Rousseau//Jonas Fernandes//Aisling Esposito', 'Oncology Supportive Care Journal', 2018, 'Background: Phosphodiesterase 10A inhibition represents a novel mechanistic approach to psychotic symptom management, though prior agents in this class have shown limited clinical translation. Alofropodect exhibits improved pharmacological characteristics and brain penetration. Objective: To assess efficacy and safety of alofropodect for acute schizophrenia in hospitalized patients. Methods: A total of 189 patients (mean age 41.8 years; 63% male) with acute schizophrenia were randomly assigned 1:1:1 to alofropodect 20 mg daily, alofropodect 40 mg daily, or placebo for 4 weeks. Primary endpoint was PANSS positive subscale score change at week 4. Secondary endpoints included PANSS total and negative subscales, clinical response (≥30% PANSS reduction), and adverse event rates. Results: The 40 mg dose showed primary endpoint success (difference from placebo −6.4 points, P = 0.001); the 20 mg dose demonstrated borderline significance (−3.8 points, P = 0.048). Clinical response rates were 41% (40 mg), 15% (20 mg), and 4% (placebo). Both doses improved PANSS negative subscale scores (P < 0.05). Extrapyramidal symptoms occurred in 8% of treatment recipients versus 0% placebo. Somnolence was reported by 11% receiving active drug. Metabolic parameters remained stable. No treatment-related serious adverse events were observed. Conclusion: Alofropodect, particularly at the 40 mg dose, demonstrates efficacy in acute schizophrenia with a tolerable side-effect profile supporting phase 3 evaluation.', '2018-12-06 09:00:00', '2026-05-24 00:00:00', 2, '1', 'Phase 2, randomized, double-blind trial', '10.5555/medidex.synthetic.0205', NULL, NULL, 'English', 'Oncology Supportive Care Journal Press'),
(NULL, 2000206, 201, 'Retraction notice: Efficacy and safety of alofropodect in acute schizophrenia', 'Tessa Rousseau//Jonas Fernandes//Aisling Esposito', 'Oncology Supportive Care Journal', 2020, 'This article is being retracted due to data irregularities identified during post-publication regulatory review. An unresolved discrepancy was discovered in the patient randomization records for the 40 mg treatment arm, with 7 enrolled participants lacking proper documentation of randomization sequence verification. The investigators were unable to provide complete source data supporting the randomization integrity upon request. While the safety profile described remains consistent with clinical observations, the efficacy conclusions cannot be definitively verified. A replication study with enhanced randomization controls is warranted.', '2020-07-19 09:00:00', '2026-07-13 00:00:00', 6, '1', 'Retraction notice', '10.5555/medidex.synthetic.0206', 'SYNTH-ISRCTN-0000097', NULL, 'English', 'Oncology Supportive Care Journal Press'),
(NULL, 2000207, 202, 'Effects of structured exercise on fibroblast growth factor 21 and adiponectin dynamics in older women with metabolic syndrome: study protocol', 'Chiara Johansen//Chiara Ionescu//Lena Wachira//Nadia Farrell', 'Clinical Outcomes Research Review', 2020, 'Metabolic syndrome impairs glucose homeostasis, lipid metabolism, and cardiovascular health in aging populations. The FGF21-adiponectin signaling axis regulates systemic metabolic adaptation, but responsiveness to exercise training may differ based on baseline metabolic status. This protocol describes a randomized trial evaluating the effects of 10 weeks of supervised combined exercise on circulating FGF21, adiponectin concentrations, and their ratio as primary biomarkers in 60 older women with or without metabolic syndrome. The exercise intervention comprises resistance training and elastic-band conditioning three times weekly. Control participants maintain usual activity patterns. Blood samples, body composition via dual-energy X-ray absorptiometry, physical fitness assessments, and metabolic parameters are measured at baseline and post-intervention. Two-way repeated-measures analysis will assess exercise effects stratified by metabolic status. This investigation aims to clarify mechanisms of exercise-induced metabolic improvement and identify biomarker-based responder phenotypes.', '2020-12-13 09:00:00', '2026-06-21 00:00:00', 1, '1', '10-week randomized controlled trial', '10.5555/medidex.synthetic.0207', NULL, NULL, 'English', 'Clinical Outcomes Research Review Press'),
(NULL, 2000208, 203, 'Exercise-induced modulation of the FGF21-adiponectin axis in older women: differential responses by metabolic phenotype', 'Chiara Johansen//Chiara Ionescu//Lena Wachira//Nadia Farrell', 'Journal of Maternal and Perinatal Health', 2021, 'Background: The fibroblast growth factor–adiponectin axis integrates systemic metabolic signals, but exercise-induced adaptations may vary based on initial metabolic status. Objective: To determine how 10 weeks of supervised exercise modulates FGF21, adiponectin, and their ratio in older women stratified by metabolic syndrome presence. Methods: A total of 60 women (mean age 75.3 years) with (n=32) or without (n=28) metabolic syndrome were randomized to supervised combined exercise (resistance plus elastic-band training, 3x/week) or usual-activity control. Circulating biomarkers, body composition, fitness, and metabolic parameters were assessed at baseline and week 10. Results: Exercise increased adiponectin in both metabolic groups (non-metabolic syndrome effect size d=1.02; metabolic syndrome d=0.68). FGF21 responses differed: increased in the non-metabolic syndrome group (d=0.40) but decreased in the metabolic syndrome group (d=−0.31). The FGF21-to-adiponectin ratio declined in both exercise groups, with larger reduction in metabolic syndrome participants (d=−0.84 versus d=−0.28). Secondary improvements included reduced body fat, improved maximal oxygen uptake, decreased fasting glucose, and favorable lipid changes in both intervention groups (all P < 0.05). Conclusion: Exercise induces differential FGF21 responses depending on metabolic phenotype, potentially reflecting adaptive metabolic reprogramming in metabolic syndrome.', '2021-02-22 09:00:00', '2026-07-08 00:00:00', 2, '1', 'Randomized controlled trial', '10.5555/medidex.synthetic.0208', 'SYNTH-NCT0000098', NULL, 'English', 'Journal of Maternal and Perinatal Health Press'),
(NULL, 2000209, 204, 'Cardiometabolic and inflammatory biomarker responses to structured exercise in older women: secondary analysis by metabolic syndrome status', 'Chiara Johansen//Chiara Ionescu//Lena Wachira//Nadia Farrell', 'International Journal of Sleep and Behavior Research', 2022, 'Background: Understanding how exercise modulates systemic cardiometabolic and inflammatory markers in older adults with varying metabolic status informs personalized intervention design. Objective: Secondary analysis of cardio-metabolic and inflammatory biomarker changes following 10-week supervised exercise. Methods: Body composition via densitometry, lipid fractionation, glucose regulation markers (fasting glucose and HOMA-IR), and inflammatory biomarkers (C-reactive protein, interleukin-6) were measured in 60 participants stratified by metabolic syndrome status. Results: Exercise participants demonstrated significant improvements across metabolic syndrome status: body fat decreased mean 3.1%, low-density lipoprotein cholesterol fell by 8%, triglycerides declined 11%, and HOMA-IR improved 12%. High-density lipoprotein cholesterol increased by 6% (P = 0.003). C-reactive protein and interleukin-6 concentrations decreased by 24% and 18%, respectively, in the intervention arms (P < 0.05). Improvements were slightly greater in metabolic syndrome participants on several measures, suggesting particular benefit in this phenotype. No significant changes occurred in the usual-activity control arm. Conclusion: Supervised exercise produces substantial improvements in cardiometabolic risk factors and inflammatory markers in older women, with notably favorable responses in those with established metabolic syndrome.', '2022-11-10 09:00:00', '2026-06-05 00:00:00', 4, '1', 'Secondary biomarker analysis', '10.5555/medidex.synthetic.0209', 'SYNTH-NCT0000098', NULL, 'English', 'International Journal of Sleep and Behavior Research Press'),
(NULL, 2000210, 205, 'Feasibility and design of a mandala-based creative expression intervention for psychological resilience in palliative care family members', 'Oleksandr Yamada//Kwame Ionescu//Farah Okoye//Haruto Brennan', 'International Journal of Behavioral Medicine Practice', 2021, 'Family members caring for patients with life-limiting illnesses experience substantial psychological distress, anxiety, and demoralized mood. Structured creative activities may offer accessible, low-cost approaches to enhance coping and emotional resilience. This protocol describes a randomized controlled trial evaluating mandala-based artistic engagement for family caregivers in palliative care settings. A total of 84 family members will be randomly assigned 1:1 to either a 4-week mandala artistic engagement program or standard care control. Intervention participants will complete one structured 1-hour mandala drawing and coloring session weekly in a calm, dedicated space using provided materials. Primary outcome measures include the Psychological Well-Being Scale administered at baseline and 4 weeks. Secondary assessments encompass the Spiritual Well-Being Scale and quality-of-life measures. We hypothesize that creative engagement will enhance psychological well-being through mechanisms of mindful attention, self-expression, and symbolic personal meaning-making during a period of existential challenge.', '2021-04-02 09:00:00', '2026-06-25 00:00:00', 1, '1', 'Randomized controlled experimental design', '10.5555/medidex.synthetic.0210', 'SYNTH-ISRCTN-0000099', NULL, 'English', 'International Journal of Behavioral Medicine Practice Press'),
(NULL, 2000211, 206, 'Mandala artistic practice as a supportive intervention for psychological well-being in family members of palliative care patients', 'Oleksandr Yamada//Kwame Ionescu//Farah Okoye//Haruto Brennan', 'International Journal of Sleep and Behavior Research', 2022, 'Background: Family members of patients with terminal illness often experience anxiety, depression, and existential distress during caregiving transitions. Creative interventions offer potential psychological benefits. Objective: To evaluate mandala-based artistic engagement for enhancing psychological well-being in palliative care family members. Methods: A total of 84 family caregivers (mean age 52 years; 71% female) were randomized to either weekly mandala drawing/coloring sessions for 4 weeks (n=42) or standard care control (n=42). Sessions occurred in quiet settings with art materials provided. The Psychological Well-Being Scale was administered at baseline and week 4; secondary measures included the Spiritual Well-Being Scale and quality-of-life visual analog scales. Results: Intervention participants demonstrated significant improvements in psychological well-being scores (mean change +8.3 points versus +1.2 points control, P = 0.001). Spiritual well-being also improved in the intervention group (mean change +6.7 points versus +0.9 points control, P = 0.003). Participants reported high satisfaction (92% rated intervention as ''helpful'' or ''very helpful''), with qualitative feedback emphasizing stress relief, improved mood, and spiritual connection. No adverse events were reported. Conclusion: Weekly mandala artistic engagement significantly enhances psychological and spiritual well-being in family members supporting palliative care patients, offering a simple, scalable, and culturally accessible intervention.', '2022-04-16 09:00:00', '2026-04-23 00:00:00', 2, '1', 'Randomized controlled trial', '10.5555/medidex.synthetic.0211', NULL, NULL, 'English', 'International Journal of Sleep and Behavior Research Press'),
(NULL, 2000212, 207, 'Integrating digital technology with direct patient support to improve TB medication adherence: protocol for a pragmatic randomized trial', 'Tariq Kowalski//Chidi Ionescu//Hiroshi Zeleny//Felix Csik//Nadia Okoye', 'Journal of Applied Clinical Trials', 2020, 'Tuberculosis remains a leading infectious cause of mortality globally, with medication non-adherence driving both treatment failure and drug resistance. Digital tools offer scalable adjuncts to clinical supervision, yet real-world implementation barriers remain incompletely understood. The TB Treatment Support Tools (TB-TST) intervention combines a smartphone application delivering personalized medication reminders, educational content, and bidirectional communication with a reliable, objective adherence biomarker (urine drug metabolite assay). This pragmatic randomized trial protocol describes evaluation of TB-TST integrated with standard directly observed therapy in four urban TB treatment centers in Argentina. A total of 90 newly diagnosed TB patients will be randomized 1:1 to standard care or standard care plus TB-TST. Primary outcomes are treatment completion rates and medication adherence measured by metabolite testing at predetermined intervals. Secondary outcomes include patient satisfaction, technical usability, cost-effectiveness, and qualitative insights into implementation barriers and facilitators. This study aims to generate evidence for scalable, patient-centered digital adherence strategies in TB programs.', '2020-06-01 09:00:00', '2026-07-18 00:00:00', 1, '1', 'Pragmatic randomized controlled trial', '10.5555/medidex.synthetic.0212', 'SYNTH-NCT0000100', NULL, 'English', 'Journal of Applied Clinical Trials Press'),
(NULL, 2000213, 208, 'Digital adherence technology with metabolite-based verification improves TB treatment completion in resource-limited settings', 'Tariq Kowalski//Chidi Ionescu//Hiroshi Zeleny//Felix Csik//Nadia Okoye', 'Clinical Outcomes Research Review', 2020, 'Background: TB treatment non-adherence threatens individual outcomes and public health through emergence of drug-resistant strains. Digital adherence technologies combined with objective biomarker verification may improve outcomes. Objective: To evaluate whether integrated digital technology (TB-TST) plus standard care improves TB treatment completion compared to standard care alone. Methods: A total of 68 TB patients (mean age 38 years; 64% male) in Argentina''s public TB program were randomized to standard directly observed therapy (n=34) or standard care plus TB-TST mobile app with urine metabolite monitoring (n=34). Primary endpoint was TB treatment completion at 6 months. Secondary endpoints included metabolite-confirmed adherence rates, app engagement metrics, and patient satisfaction. Results: Treatment completion occurred in 76% of TB-TST participants versus 56% of standard care (relative risk 1.36; 95% CI 1.01–1.82; P = 0.039). Metabolite testing confirmed adherence on 87% of scheduled assessments in the intervention arm. App utilization was high (mean 68% of prescribed daily reminders accessed). Patients reported improved confidence in their adherence (P = 0.008) and strengthened therapeutic relationships with treatment supporters. No serious adverse events occurred. Conclusion: Integrated digital adherence technology with metabolite verification enhances TB treatment completion in pragmatic clinical settings, supporting scale-up for TB program implementation.', '2020-07-21 09:00:00', '2026-04-09 00:00:00', 2, '1', 'Pragmatic randomized trial', '10.5555/medidex.synthetic.0213', 'SYNTH-NCT0000100', NULL, 'English', 'Clinical Outcomes Research Review Press'),
(NULL, 2000214, 209, 'Patient perspectives and implementation factors shaping acceptance and sustained use of digital TB adherence support tools', 'Tariq Kowalski//Chidi Ionescu//Hiroshi Zeleny//Felix Csik//Nadia Okoye', 'International Trials Register Quarterly', 2021, 'Background: Digital health tools for TB adherence require sustained patient engagement for effectiveness. Understanding facilitators and barriers to technology adoption in diverse, resource-limited settings is critical for implementation success. Objective: Qualitative analysis of patient experiences and perceptions regarding TB-TST implementation. Methods: Semi-structured interviews with 33 intervention-arm participants and 5 treatment support workers were conducted during or shortly after TB treatment completion. Data were analyzed using thematic coding informed by normalization process theory to identify factors enabling or hindering technology integration into routine TB care. Results: Patients identified app medication reminders and direct messaging with treatment supporters as most valuable; many used the app to ask sensitive questions avoided in face-to-face settings. Perceived benefits included improved organization, reduced treatment burden perceptions, and psychological reassurance. Initial confusion about the metabolite test purpose resolved over time through repeated explanation. Key barriers included inconsistent smartphone access, limited internet connectivity in some neighborhoods, burden of cumulative TB medication side effects, and work schedule conflicts with testing appointments. Qualitative feedback emphasized the importance of the treatment supporter relationship as a trusted anchor for technology use. Conclusions: Successful digital TB adherence tools require attention to social context, patient-centered design, and integration with human support systems rather than technology-only approaches.', '2021-02-06 09:00:00', '2026-05-08 00:00:00', 4, '1', 'Qualitative implementation analysis', '10.5555/medidex.synthetic.0214', 'SYNTH-NCT0000100', NULL, 'English', 'International Trials Register Quarterly Press'),
(NULL, 2000215, 210, 'Corrigendum: Digital adherence technology with metabolite-based verification improves TB treatment completion', 'Tariq Kowalski//Chidi Ionescu//Hiroshi Zeleny//Felix Csik//Nadia Okoye', 'Clinical Outcomes Research Review', 2022, 'In the primary results article of this trial, Table 2 contained a mislabeled column header. The percentages reported under ''Baseline Adherence'' were inadvertently duplicated in the row for ''Week 12 Metabolite Detection'' due to a data import error. The corrected table reflects accurate metabolite detection rates at all timepoints and does not affect the primary efficacy conclusions. The study conclusions remain unchanged. We regret any confusion this may have caused.', '2022-04-23 09:00:00', '2026-06-17 00:00:00', 5, '1', 'Corrigendum notice', '10.5555/medidex.synthetic.0215', NULL, NULL, 'English', 'Clinical Outcomes Research Review Press');

